/**
 * AIT Resource Loader
 *
 * 将体积较大的第三方库延迟到真正使用对应功能时再加载，避免每个页面
 * 都在 content script 初始化阶段解析这些资源。
 */
(function initAITResourceLoader() {
    'use strict';

    const bundles = Object.freeze({
        'runner-editor': {
            scripts: [
                'js/runner/codemirror/codemirror.min.js',
                'js/runner/codemirror/javascript.min.js',
                'js/runner/codemirror/xml.min.js',
                'js/runner/codemirror/css.min.js',
                'js/runner/codemirror/sql.min.js',
                'js/runner/codemirror/htmlmixed.min.js',
                'js/runner/codemirror/markdown.min.js'
            ]
        },
        'runner-markdown': {
            scripts: [
                'js/runner/libs/marked.min.js'
            ]
        },
        'runner-mermaid': {
            scripts: [
                'js/mermaid/lib/mermaid.min.js'
            ]
        },
        'export-mathjax': {
            scripts: [
                'js/conversationExport/libs/mathjax-config.js',
                'js/conversationExport/libs/mathjax-tex-svg.js'
            ]
        }
    });

    const scriptPromises = new Map();
    const bundlePromises = new Map();

    function getResourceUrl(path) {
        return chrome.runtime.getURL(path);
    }

    function loadScript(path) {
        if (!scriptPromises.has(path)) {
            const promise = import(getResourceUrl(path)).catch((error) => {
                scriptPromises.delete(path);
                throw error;
            });
            scriptPromises.set(path, promise);
        }
        return scriptPromises.get(path);
    }

    async function loadBundle(name) {
        const bundle = bundles[name];
        if (!bundle) {
            throw new Error(`Unknown resource bundle: ${name}`);
        }

        if (!bundlePromises.has(name)) {
            const promise = (async () => {
                for (const path of bundle.scripts || []) {
                    await loadScript(path);
                }
            })().catch((error) => {
                bundlePromises.delete(name);
                throw error;
            });
            bundlePromises.set(name, promise);
        }

        return bundlePromises.get(name);
    }

    window.AITResourceLoader = Object.freeze({
        load: loadBundle,
        isLoaded: (name) => bundlePromises.has(name)
    });
})();

;

// Source: js/global/ai-state-monitor/index.js
/**
 * AI State Monitor - AI 输出状态监控器
 * 
 * 通过搭便车在 DOMObserverManager 的 body 订阅上，
 * 检测 AI 是否正在生成回复，状态变化时派发全局事件。
 * 
 * 解决问题：
 * - 多个模块各自用 setInterval 轮询 isAIGenerating()
 * - 导致重复检测、定时器管理复杂
 * 
 * 解决方案：
 * - 单一监控，状态变化时派发 ai:stateChange 事件
 * - 消费方通过 window.addEventListener 订阅
 * 
 * 使用示例：
 * ```javascript
 * // 订阅实际状态变化，功能卸载时调用返回的函数
 * const unwatch = AIStateMonitor.getInstance().watch(adapter, onChange);
 * 
 * // 监听状态变化
 * window.addEventListener('ai:stateChange', (e) => {
 *     if (e.detail.generating) {
 *         log('AI 开始输出');
 *     } else {
 *         log('AI 输出结束');
 *     }
 * });
 * 
 * // 同步查询当前状态
 * AIStateMonitor.getInstance().isGenerating; // true / false
 * ```
 */

class AIStateMonitor {
    static _instance = null;

    static getInstance() {
        if (!AIStateMonitor._instance) {
            AIStateMonitor._instance = new AIStateMonitor();
        }
        return AIStateMonitor._instance;
    }

    constructor() {
        if (AIStateMonitor._instance) {
            throw new Error('Use AIStateMonitor.getInstance() instead');
        }
        this._generating = false;
        this._adapter = null;
        this._unsubscribe = null;
        this._watchers = new Set();
    }

    /**
     * 当前是否正在生成
     * @returns {boolean}
     */
    get isGenerating() {
        return this._generating;
    }

    /**
     * 同一平台的功能共用一个监控器，最后一个订阅者离开时停止。
     * @param {Object} adapter - 平台适配器（需实现 isAIGenerating 方法）
     * @param {(generating: boolean) => void} [onChange] - 仅接收检测到的状态变化
     * @returns {() => void} 取消订阅
     */
    watch(adapter, onChange) {
        if (typeof adapter?.isAIGenerating !== 'function') return () => {};
        const watcher = { adapter, onChange };
        this._watchers.add(watcher);
        this._syncAdapter();
        return () => {
            if (this._watchers.delete(watcher)) this._syncAdapter();
        };
    }

    _adapterKey(adapter) {
        return adapter?.platformId || adapter;
    }

    _syncAdapter() {
        const adapter = this._watchers.values().next().value?.adapter ?? null;
        if (this._adapterKey(adapter) === this._adapterKey(this._adapter)) return;
        this._stop();
        if (adapter) this._start(adapter);
    }

    _start(adapter) {
        this._adapter = adapter;

        // 平台可提供更精确的监听（GPT 新版停止按钮可能只改变属性）。
        if (typeof adapter.observeAIGeneration === 'function') {
            this._unsubscribe = adapter.observeAIGeneration(() => this._checkState());
            this._checkState();
            return;
        }
        
        // 搭便车在 body observer 上：停止按钮的出现/消失是 DOM 节点变化，
        // body observer 天然能捕获到，不需要额外的 setInterval
        if (window.DOMObserverManager) {
            this._unsubscribe = window.DOMObserverManager.getInstance().subscribeBody('ai-state-monitor', {
                callback: () => this._checkState(),
                filter: { hasAddedNodes: true },
                debounce: 300
            });
        }
    }

    /**
     * 停止监控
     */
    _stop() {
        if (this._unsubscribe) {
            this._unsubscribe();
            this._unsubscribe = null;
        }
        
        // 如果停止时还在生成状态，派发一次结束事件
        if (this._generating) {
            this._generating = false;
            this._dispatch(false);
        }
        
        this._adapter = null;
    }

    /**
     * 检查状态并在变化时派发事件
     * @private
     */
    _checkState() {
        if (!this._adapter) return;
        
        const newState = !!this._adapter.isAIGenerating();
        
        if (newState !== this._generating) {
            this._generating = newState;
            const key = this._adapterKey(this._adapter);
            for (const watcher of this._watchers) {
                if (this._adapterKey(watcher.adapter) !== key) continue;
                try { watcher.onChange?.(newState); } catch {}
            }
            this._dispatch(newState);
        }
    }

    /**
     * 派发状态变化事件
     * @private
     */
    _dispatch(generating) {
        try {
            window.dispatchEvent(new CustomEvent('ai:stateChange', {
                detail: { generating }
            }));
        } catch (e) {
            // 静默处理
        }
    }
}

// 暴露到全局
if (typeof window !== 'undefined') {
    window.AIStateMonitor = AIStateMonitor;
}

;

// Source: js/global/ai-complete-reminder-toast/index.js
/**
 * Shared AI reply completion toast.
 * Used by both the real completion reminder and settings preview.
 */
(function() {
    const ANCHOR_CLASS = 'ait-timeline-ai-complete-toast-anchor';
    const TOAST_CLASS = 'ait-ai-complete-toast';

    const getMessage = (platformName = 'AI') => {
        return TimelineI18n.getMessage('timelineAICompleteNotLatestToast', platformName) ||
            `${platformName} 回复已完成`;
    };

    const getAnchor = () => {
        const existingAnchor = document.querySelector(`.${ANCHOR_CLASS}`);
        if (existingAnchor?.isConnected) {
            return existingAnchor;
        }

        const anchor = document.createElement('div');
        anchor.className = ANCHOR_CLASS;
        anchor.style.cssText = [
            'position: fixed',
            'top: 72px',
            'right: 26px',
            'width: 1px',
            'height: 1px',
            'pointer-events: none',
            'z-index: 2147483647'
        ].join(';');
        document.body.appendChild(anchor);
        return anchor;
    };

    const getOptions = () => ({
        duration: 3500,
        iconType: 'check',
        color: false,
        className: TOAST_CLASS,
        useClassStyles: true,
        position: 'left',
        gap: 10
    });

    const show = (platformName = 'AI') => {
        if (!window.globalToastManager) return false;

        window.globalToastManager.info(getMessage(platformName), getAnchor(), getOptions());
        return true;
    };

    const removeAnchor = () => {
        document.querySelectorAll(`.${ANCHOR_CLASS}`).forEach(anchor => anchor.remove());
    };

    window.AICompleteReminderToast = {
        show,
        getAnchor,
        getMessage,
        getOptions,
        removeAnchor
    };
})();

;

// Source: js/global/input-modal/index.js
/**
 * Global Input Modal Manager - 全局输入对话框管理器
 * 
 * 负责管理整个扩展的输入对话框，提供统一的用户输入交互
 * 
 * 特性：
 * - 全局单例模式
 * - 完全可配置（标题、默认值、占位符、验证）
 * - 键盘交互（ESC取消、Enter确认）
 * - 点击遮罩层取消
 * - 深色模式自适应
 * - Promise 异步返回
 * - 自动聚焦和光标定位
 * - ✨ 组件自治：URL 变化时自动关闭并清理 DOM（无需外部调用）
 * 
 * @example
 * // 基本用法
 * const result = await window.globalInputModal.show({
 *     title: '请输入标题',
 *     defaultValue: 'Hello',
 *     placeholder: '请输入...',
 *     required: true,
 *     requiredMessage: '不能为空'
 * });
 * 
 * if (result) {
 *     log('用户输入:', result);
 * } else {
 *     log('用户取消了');
 * }
 */

class GlobalInputModal {
    constructor() {
        // 配置
        this.config = {
            defaultMaxLength: 100,
            animationDuration: 200
        };
        
        // 状态
        this.state = {
            isShowing: false,
            currentOverlay: null,
            currentResolve: null,
            currentUrl: location.href  // 记录当前 URL
        };
        
        // ✅ 监听 URL 变化，自动关闭 modal（组件自治）
        this._boundHandleUrlChange = this._handleUrlChange.bind(this);
        this._attachUrlListeners();
        
    }
    
    /**
     * 显示输入对话框
     * @param {Object} options - 配置选项
     * @param {string} options.title - 对话框标题（必填）
     * @param {string} options.defaultValue - 默认输入值
     * @param {string} options.placeholder - 输入框占位符
     * @param {boolean} options.required - 是否必填（默认 false）
     * @param {string} options.requiredMessage - 必填验证失败消息
     * @param {number} options.maxLength - 最大长度（默认 100）
     * @param {Function} options.validator - 自定义验证函数 (value) => { valid: boolean, message: string }
     * @param {string} options.confirmText - 确认按钮文本（默认从 i18n 获取）
     * @param {string} options.cancelText - 取消按钮文本（默认从 i18n 获取）
     * @returns {Promise<string|null>} 返回用户输入的值，取消则返回 null
     */
    async show(options = {}) {
        try {
            await TimelineI18n.ready();

            // 参数校验
            if (!options.title) {
                return null;
            }
            
            // 防止重复显示
            if (this.state.isShowing) {
                return null;
            }
            
            // 合并配置
            const config = {
                title: options.title,
                defaultValue: options.defaultValue || '',
                placeholder: options.placeholder || TimelineI18n.getMessage('zmxvkp'),
                required: options.required !== undefined ? options.required : false,
                requiredMessage: options.requiredMessage || TimelineI18n.getMessage('pzmkvx'),
                maxLength: options.maxLength || this.config.defaultMaxLength,
                validator: options.validator || null,
                confirmText: options.confirmText || TimelineI18n.getMessage('vkmzpx'),
                cancelText: options.cancelText || TimelineI18n.getMessage('commonCancel')
            };
            
            return await this._showModal(config);
            
        } catch (error) {
            return null;
        }
    }
    
    /**
     * 强制关闭当前显示的 modal
     */
    forceClose() {
        if (this.state.isShowing && this.state.currentResolve) {
            this._cleanup();
            this.state.currentResolve(null);
            this.state.currentResolve = null;
        }
    }
    
    /**
     * 销毁管理器
     */
    destroy() {
        this.forceClose();
        this._detachUrlListeners();  // 清理事件监听器
    }
    
    // ==================== 内部方法 ====================
    
    /**
     * 显示 Modal（内部实现）
     */
    async _showModal(config) {
        return new Promise((resolve) => {
            // 创建遮罩层
            const overlay = document.createElement('div');
            overlay.className = 'global-input-modal-overlay';
            
            // 创建对话框
            const dialog = document.createElement('div');
            dialog.className = 'global-input-modal';
            
            // 转义 HTML
            const escapeHTML = (str) => {
                const div = document.createElement('div');
                div.textContent = str;
                return div.innerHTML;
            };
            
            dialog.innerHTML = `
                <div class="global-input-modal-header">
                    <h3>${escapeHTML(config.title)}</h3>
                </div>
                <div class="global-input-modal-body">
                    <input 
                        type="text" 
                        class="global-input-modal-input" 
                        placeholder="${escapeHTML(config.placeholder)}" 
                        value="${escapeHTML(config.defaultValue)}" 
                        maxlength="${config.maxLength}"
                        autocomplete="off"
                    />
                </div>
                <div class="global-input-modal-footer">
                    <button class="global-input-modal-cancel">${escapeHTML(config.cancelText)}</button>
                    <button class="global-input-modal-confirm">${escapeHTML(config.confirmText)}</button>
                </div>
            `;
            
            overlay.appendChild(dialog);
            document.body.appendChild(overlay);
            
            // 获取元素
            const input = dialog.querySelector('.global-input-modal-input');
            const confirmBtn = dialog.querySelector('.global-input-modal-confirm');
            const cancelBtn = dialog.querySelector('.global-input-modal-cancel');
            
            // 更新状态
            this.state.isShowing = true;
            this.state.currentOverlay = overlay;
            this.state.currentResolve = resolve;
            
            // 显示对话框（带动画）
            requestAnimationFrame(() => {
                overlay.classList.add('visible');
                input.focus();
                
                // 如果有默认值，将光标定位到末尾
                if (config.defaultValue) {
                    setTimeout(() => {
                        const length = input.value.length;
                        input.setSelectionRange(length, length);
                    }, 0);
                }
            });
            
            // 验证输入
            const validateInput = () => {
                const value = input.value.trim();
                
                // 必填验证
                if (config.required && !value) {
                    return {
                        valid: false,
                        message: config.requiredMessage
                    };
                }
                
                // 自定义验证
                if (config.validator && value) {
                    return config.validator(value);
                }
                
                return { valid: true };
            };
            
            // 提交输入
            const submitInput = () => {
                const validation = validateInput();
                
                if (!validation.valid) {
                    // 显示错误提示（使用全局 toast 管理器）
                    if (window.globalToastManager) {
                        window.globalToastManager.error(validation.message, input);
                    }
                    return;
                }
                
                const value = input.value.trim();
                this._cleanup();
                resolve(value || null);
            };
            
            // 取消输入
            const cancelInput = () => {
                this._cleanup();
                resolve(null);
            };
            
            // 确定按钮
            confirmBtn.addEventListener('click', submitInput);
            
            // 取消按钮
            cancelBtn.addEventListener('click', cancelInput);
            
            // 点击遮罩层取消
            overlay.addEventListener('click', (e) => {
                if (e.target === overlay) {
                    cancelInput();
                }
            });
            
        });
    }
    
    /**
     * 清理 DOM 和状态
     */
    _cleanup() {
        if (!this.state.currentOverlay) return;
        
        const overlay = this.state.currentOverlay;
        
        // 隐藏动画
        overlay.classList.remove('visible');
        
        // 等待动画完成后移除 DOM
        setTimeout(() => {
            if (overlay.parentNode) {
                overlay.parentNode.removeChild(overlay);
            }
        }, this.config.animationDuration);
        
        // 重置状态
        this.state.isShowing = false;
        this.state.currentOverlay = null;
        this.state.currentResolve = null;
        
    }
    
    // ==================== URL 变化监听（组件自治）====================
    
    /**
     * 附加 URL 变化监听器
     * 当 URL 变化时自动关闭 modal，无需外部调用
     */
    _attachUrlListeners() {
        try {
            window.addEventListener('url:change', this._boundHandleUrlChange);
        } catch (error) {
        }
    }
    
    /**
     * 移除 URL 变化监听器
     */
    _detachUrlListeners() {
        try {
            window.removeEventListener('url:change', this._boundHandleUrlChange);
        } catch (error) {
        }
    }
    
    /**
     * 处理 URL 变化
     * ✅ 组件自治：URL 变化时自动关闭 modal
     */
    _handleUrlChange() {
        const newUrl = location.href;
        
        // URL 变化了，自动关闭 modal
        if (newUrl !== this.state.currentUrl) {
            this.state.currentUrl = newUrl;
            
            // 如果 modal 正在显示，自动关闭
            if (this.state.isShowing) {
                this.forceClose();
            }
        }
    }
}

// ==================== 全局单例初始化 ====================

// 创建全局实例（只在第一次加载时）
if (typeof window.globalInputModal === 'undefined') {
    window.globalInputModal = new GlobalInputModal();
}

;

