// Source: js/smartInputBox/smart-enter-manager.js
/**
 * Smart Enter Manager
 * 
 * 智能 Enter 管理器
 * 实现 Enter 换行 + 快速双击 Enter 发送
 */

class SmartEnterManager {
    constructor(adapter, options = {}) {
        if (!adapter) {
            throw new Error('SmartEnterManager requires an adapter');
        }
        
        this.adapter = adapter;
        this.config = {
            doubleClickInterval: options.doubleClickInterval || SMART_ENTER_CONFIG.DOUBLE_CLICK_INTERVAL
        };
        
        // ✅ 平台设置（内存缓存）
        this.platformSettings = {};
        
        // ✅ 发送模式（内存缓存）
        this.smartEnterMode = SMART_ENTER_MODES.DOUBLE_ENTER;
        
        // 状态
        this.state = {
            lastEnterTime: 0,
            enterCount: 0,
            savedSelection: null,  // 保存的光标位置/选区
            allowNextEnter: false,  // 是否允许下一次 Enter 通过（用于发送）
            isInsertingNewline: false  // 是否正在插入换行（合成事件不应被拦截）
        };
        
        // 定时器
        this.newlineTimer = null;
        this.debounceTimer = null;  // 防抖定时器
        
        // DOMObserverManager 取消订阅函数
        this._unsubscribeObserver = null;
        
        // Storage 监听器
        this.storageListener = null;
        
        // 使用 WeakMap 跟踪已附加的元素及其事件处理器
        // WeakMap 的好处：当元素被移除时会自动清理，不会造成内存泄漏
        this.attachedElements = new WeakMap();
        this._externalKeydownInput = null;
        this._inputListenerController = new AbortController();
        
        // ✅ 健康检查定时器
        this.healthCheckInterval = null;
        
        // ✅ 提示词按钮管理器
        this.promptButtonManager = null;
        this._currentPlatform = null;
    }
    
    /**
     * 初始化
     */
    async init() {
        await TimelineI18n.ready();

        // ✅ 预加载平台信息（平台配置现在异步获取，缓存供同步方法使用）
        this._currentPlatform = await getCurrentPlatform();

        // 1. 加载平台设置
        await this._loadPlatformSettings();
        if (window.AITContentSession?.active === false) return;
        
        // 2. 监听 Storage 变化（实时响应用户开关）
        this._attachStorageListener();
        
        // 3. 始终附加到输入框（不管开关状态）
        this._attachToInputIfNeeded();
        
        // 4. 始终启动 DOM 监听（不管开关状态）
        this._startObserving();
        
        // 5. ✅ 启动健康检查
        this._startHealthCheck();
        
        // 6. ✅ 初始化提示词按钮
        await this._initPromptButton();
    }
    
    /**
     * ✅ 初始化提示词按钮
     */
    async _initPromptButton() {
        try {
            // 检查 PromptButtonManager 是否已加载
            if (typeof PromptButtonManager === 'undefined') {
                return;
            }
            
            // 创建并初始化
            this.promptButtonManager = new PromptButtonManager(this.adapter);
            await this.promptButtonManager.init();
            
        } catch (e) {
        }
    }
    
    /**
     * ✅ 加载平台设置
     */
    async _loadPlatformSettings() {
        try {
            const result = await chrome.storage.local.get(['smartInputPlatformSettings', 'smartEnterMode']);
            this.platformSettings = result.smartInputPlatformSettings || {};
            this.smartEnterMode = result.smartEnterMode || SMART_ENTER_MODES.DOUBLE_ENTER;
        } catch (e) {
            this.platformSettings = {};
            this.smartEnterMode = SMART_ENTER_MODES.DOUBLE_ENTER;
        }
    }
    
    /**
     * ✅ 检查当前平台是否启用
     */
    _isPlatformEnabled() {
        try {
            const platform = this._currentPlatform;
            if (!platform) return true; // 未知平台，默认启用
            
            // ✅ 首先检查平台是否支持智能回车功能
            if (platform.features?.smartEnter !== true) {
                return false; // 平台不支持该功能
            }
            
            // 从缓存中检查（默认关闭）
            return this.platformSettings[platform.id] === true;
        } catch (e) {
            return false; // 出错默认关闭
        }
    }
    
    /**
     * 附加 Storage 变化监听器
     */
    _attachStorageListener() {
        this.storageListener = (changes, areaName) => {
            if (areaName === 'local') {
                // ✅ 监听平台设置变化
                if (changes.smartInputPlatformSettings) {
                    this._resetState();
                    this.platformSettings = changes.smartInputPlatformSettings.newValue || {};
                }
                // ✅ 监听发送模式变化
                if (changes.smartEnterMode) {
                    this._resetState();
                    this.smartEnterMode = changes.smartEnterMode.newValue || SMART_ENTER_MODES.DOUBLE_ENTER;
                }
            }
        };
        
        chrome.storage.onChanged.addListener(this.storageListener);
    }
    
    /**
     * 移除 Storage 变化监听器
     */
    _detachStorageListener() {
        if (this.storageListener) {
            try { chrome.storage.onChanged.removeListener(this.storageListener); } catch {}
            this.storageListener = null;
        }
    }
    
    /**
     * 附加到输入框（带防抖）
     */
    _attachToInputIfNeeded() {
        try {
            const input = this.adapter.findInputElement();
            
            if (input) {
                // 使用 WeakMap 检查是否已附加
                if (!this.attachedElements.has(input)) {
                    this._attachListener(input);
                }
            }
        } catch (e) {
        }
    }
    
    /**
     * 防抖处理附加逻辑
     */
    _debouncedAttach() {
        // 清除之前的定时器
        if (this.debounceTimer) {
            clearTimeout(this.debounceTimer);
        }
        
        // 延迟执行
        this.debounceTimer = setTimeout(() => {
            this._attachToInputIfNeeded();
            this.debounceTimer = null;
        }, SMART_ENTER_CONFIG.DEBOUNCE_DELAY);
    }
    
    /**
     * 启动 DOM 监听
     * 使用 DOMObserverManager 统一管理
     */
    _startObserving() {
        if (this._unsubscribeObserver) return;
        
        try {
            if (window.DOMObserverManager) {
                this._unsubscribeObserver = window.DOMObserverManager.getInstance().subscribeBody('smart-enter', {
                    callback: () => this._debouncedAttach(),
                    filter: { hasAddedNodes: true },
                    debounce: SMART_ENTER_CONFIG.DEBOUNCE_DELAY  // 200ms 防抖
                });
            }
        } catch (e) {
        }
    }
    
    /**
     * 停止 DOM 监听
     */
    _stopObserving() {
        if (this._unsubscribeObserver) {
            this._unsubscribeObserver();
            this._unsubscribeObserver = null;
        }
    }
    
    /**
     * ✅ 启动健康检查
     * 定期检测输入框是否仍然有效，如果失效则重新绑定
     */
    _startHealthCheck() {
        if (this.healthCheckInterval) clearInterval(this.healthCheckInterval);
        
        this.healthCheckInterval = setInterval(() => {
            try {
                const currentInput = this.adapter.findInputElement();
                
                // 情况1: 页面上找不到输入框了 (可能正在加载或切换)
                if (!currentInput) return;
                
                // 情况2: 找到了输入框，但还没有被绑定 (可能是新生成的)
                if (!this.attachedElements.has(currentInput)) {
                    // log('[SmartInputBox] Detected new input element, rebinding...');
                    this._attachListener(currentInput);
                }
                
                // 情况3: 检查已绑定的元素是否还在文档中
                // (由于使用了 WeakMap，不需要手动清理旧的，只需要确保新的被绑定)
                
            } catch (e) {
                // 忽略错误
            }
        }, 5000); // 每 5 秒检查一次
    }
    
    /**
     * 附加键盘监听器到输入框
     * @param {HTMLElement} inputElement - 输入框元素
     */
    _attachListener(inputElement) {
        if (!inputElement) return;

        // 使用祖先监听时，编辑器替换后也必须移除旧闭包，避免重复处理。
        if (this._externalKeydownInput && this._externalKeydownInput !== inputElement) {
            this._detachListener(this._externalKeydownInput);
        }
        
        // 创建绑定的事件处理器
        const keydownTarget = this.adapter.getKeydownEventTarget(inputElement);
        const handleKeyDown = (e) => {
            if (e.target !== inputElement && !inputElement.contains(e.target)) return;
            this._handleKeyDown(inputElement, e);
        };
        const handleInput = this._handleInput.bind(this);
        
        // 附加 keydown 监听器（使用 capture 模式优先拦截）
        keydownTarget.addEventListener('keydown', handleKeyDown, {
            capture: true,
            signal: this._inputListenerController.signal
        });
        if (keydownTarget !== inputElement) this._externalKeydownInput = inputElement;
        
        // 附加 input 监听器（检测内容变化）
        inputElement.addEventListener('input', handleInput, { signal: this._inputListenerController.signal });
        
        // 保存事件处理器引用到 WeakMap，方便后续清理
        this.attachedElements.set(inputElement, {
            handleKeyDown,
            handleInput,
            keydownTarget
        });
    }
    
    /**
     * 移除输入框的监听器
     * @param {HTMLElement} inputElement - 输入框元素
     */
    _detachListener(inputElement) {
        if (!inputElement) return;
        
        // 从 WeakMap 获取事件处理器引用
        const handlers = this.attachedElements.get(inputElement);
        if (!handlers) return;

        this._resetState();
        
        // 移除事件监听器
        handlers.keydownTarget.removeEventListener('keydown', handlers.handleKeyDown, { capture: true });
        inputElement.removeEventListener('input', handlers.handleInput);
        
        // 从 WeakMap 中删除
        this.attachedElements.delete(inputElement);
        if (this._externalKeydownInput === inputElement) this._externalKeydownInput = null;
    }
    
    /**
     * 处理 input 事件（内容变化）
     * 在监听窗口期内，如果内容变化，取消当前的Enter处理
     */
    _handleInput() {
        // 如果有待执行的换行定时器，取消它
        if (this.newlineTimer) {
            clearTimeout(this.newlineTimer);
            this.newlineTimer = null;
            
            // 重置状态（内容变化了，之前的Enter操作失效）
            this._resetState();
        }
    }
    
    /**
     * 处理 Enter 键按下事件
     * @param {HTMLElement} inputElement - 输入框元素
     * @param {KeyboardEvent} e - 键盘事件
     */
    _handleKeyDown(inputElement, e) {
        // 只处理 Enter 键
        if (e.key !== 'Enter') {
            return;
        }

        // 输入法确认候选词的 Enter 不能触发换行或发送。
        if (e.isComposing || e.keyCode === 229) {
            this._resetState();
            return;
        }
        
        // 如果是我们触发的 Enter（用于发送或插入换行），允许通过
        if (this.state.allowNextEnter || this.state.isInsertingNewline) {
            return;
        }
        
        // ✅ 检查当前平台是否启用
        if (!this._isPlatformEnabled()) {
            return;
        }

        if (window.AITExtensionContext?.isActive() === false) return;

        // 长按产生的重复事件不能被识别为双击发送。
        if (e.repeat) {
            e.preventDefault();
            e.stopPropagation();
            return;
        }
        
        const mode = this.smartEnterMode || SMART_ENTER_MODES.DOUBLE_ENTER;
        
        if (mode === SMART_ENTER_MODES.DOUBLE_ENTER) {
            this._handleDoubleEnterMode(inputElement, e);
        } else if (mode === SMART_ENTER_MODES.CTRL_ENTER) {
            this._handleCtrlEnterMode(inputElement, e);
        } else if (mode === SMART_ENTER_MODES.SHIFT_ENTER) {
            this._handleShiftEnterMode(inputElement, e);
        }
    }
    
    /**
     * 模式1：快速双击 Enter 发送（原有逻辑）
     */
    _handleDoubleEnterMode(inputElement, e) {
        if (e.shiftKey || e.ctrlKey || e.altKey || e.metaKey) {
            return;
        }
        
        e.preventDefault();
        e.stopPropagation();
        
        const now = Date.now();
        const timeSinceLastEnter = now - this.state.lastEnterTime;
        
        if (this.state.enterCount > 0 && timeSinceLastEnter < this.config.doubleClickInterval) {
            this.state.enterCount++;
            
            if (this.state.enterCount >= 2) {
                if (this.newlineTimer) {
                    clearTimeout(this.newlineTimer);
                    this.newlineTimer = null;
                }
                this._triggerSend(inputElement);
                this._resetState();
            }
        } else {
            if (this.newlineTimer) {
                clearTimeout(this.newlineTimer);
                this.newlineTimer = null;
            }
            
            this._saveSelection(inputElement);
            this.state.enterCount = 1;
            this.state.lastEnterTime = now;
            
            this.newlineTimer = setTimeout(() => {
                this.newlineTimer = null;
                if (this.state.enterCount === 1) {
                    if (this.adapter.canSend(inputElement)) {
                        this._insertNewlineAtSavedPosition(inputElement);
                    }
                }
                this._resetState();
            }, this.config.doubleClickInterval);
        }
    }
    
    /**
     * 模式2：Ctrl/Cmd + Enter 发送
     * Enter 即时换行，Ctrl/Cmd+Enter 发送消息
     */
    _handleCtrlEnterMode(inputElement, e) {
        if ((e.ctrlKey || e.metaKey) && !e.shiftKey && !e.altKey) {
            e.preventDefault();
            e.stopPropagation();
            this._triggerSend(inputElement);
        } else if (!e.shiftKey && !e.altKey && !e.ctrlKey && !e.metaKey) {
            e.preventDefault();
            e.stopPropagation();
            this._insertNewline(inputElement);
            this._showNewlineToast(inputElement);
        }
    }
    
    /**
     * 模式3：Shift + Enter 发送
     * Enter 即时换行，Shift+Enter 发送消息
     */
    _handleShiftEnterMode(inputElement, e) {
        if (e.shiftKey && !e.ctrlKey && !e.altKey && !e.metaKey) {
            e.preventDefault();
            e.stopPropagation();
            this._triggerSend(inputElement);
        } else if (!e.shiftKey && !e.ctrlKey && !e.altKey && !e.metaKey) {
            e.preventDefault();
            e.stopPropagation();
            this._insertNewline(inputElement);
            this._showNewlineToast(inputElement);
        }
    }
    
    /**
     * 保存当前光标位置/选区
     * @param {HTMLElement} inputElement - 输入框元素
     */
    _saveSelection(inputElement) {
        try {
            const isContentEditable = inputElement.contentEditable === 'true';
            
            if (isContentEditable) {
                // contenteditable: 保存 Range 对象
                const selection = window.getSelection();
                if (selection.rangeCount > 0) {
                    this.state.savedSelection = {
                        type: 'range',
                        range: selection.getRangeAt(0).cloneRange()
                    };
                }
            } else {
                // textarea: 保存光标位置
                this.state.savedSelection = {
                    type: 'offset',
                    start: inputElement.selectionStart,
                    end: inputElement.selectionEnd
                };
            }
        } catch (e) {
        }
    }
    
    /**
     * 在保存的位置插入换行
     * @param {HTMLElement} inputElement - 输入框元素
     */
    _insertNewlineAtSavedPosition(inputElement) {
        if (!this.state.savedSelection) {
            this._insertNewline(inputElement);
            this._showNewlineToast(inputElement);
            return;
        }
        
        try {
            const isContentEditable = inputElement.contentEditable === 'true';
            
            if (isContentEditable && this.state.savedSelection.type === 'range') {
                // 恢复选区并插入换行
                const selection = window.getSelection();
                selection.removeAllRanges();
                selection.addRange(this.state.savedSelection.range);
                
                this._insertNewline(inputElement);
            } else if (!isContentEditable && this.state.savedSelection.type === 'offset') {
                // 恢复光标位置并插入换行
                inputElement.selectionStart = this.state.savedSelection.start;
                inputElement.selectionEnd = this.state.savedSelection.end;
                
                this._insertNewline(inputElement);
            } else {
                // 类型不匹配，使用当前位置
                this._insertNewline(inputElement);
            }
            
            // 显示Toast提示
            this._showNewlineToast(inputElement);
        } catch (e) {
            this._insertNewline(inputElement);
            this._showNewlineToast(inputElement);
        }
    }
    
    /**
     * 显示换行提示Toast
     * @param {HTMLElement} inputElement - 输入框元素
     */
    async _showNewlineToast(inputElement) {
        try {
            // 检查全局Toast管理器是否存在
            if (typeof window.globalToastManager === 'undefined' || !window.globalToastManager) {
                return;
            }
            
            // 检查提示次数
            const result = await chrome.storage.local.get('smartEnterToastCount');
            const count = result.smartEnterToastCount || 0;
            
            if (count >= 5) {
                return;
            }
            
            // 根据模式选择 Toast 消息
            const mode = this.smartEnterMode || SMART_ENTER_MODES.DOUBLE_ENTER;
            let toastKey = 'vxmkpz';
            if (mode === SMART_ENTER_MODES.CTRL_ENTER) {
                toastKey = 'smartEnterToastCtrlEnter';
            } else if (mode === SMART_ENTER_MODES.SHIFT_ENTER) {
                toastKey = 'smartEnterToastShiftEnter';
            }
            const ctrlLabel = navigator.platform.toUpperCase().indexOf('MAC') >= 0 ? '⌘' : 'Ctrl';
            const message = TimelineI18n.getMessage(toastKey).replace('{ctrl}', ctrlLabel);
            window.globalToastManager.info(message, inputElement, {
                duration: 2500,
                icon: '',  // 不显示图标
                color: {
                    light: {
                        backgroundColor: '#0d0d0d',  // 浅色模式：黑色背景
                        textColor: '#ffffff',        // 浅色模式：白色文字
                        borderColor: '#0d0d0d'       // 浅色模式：黑色边框
                    },
                    dark: {
                        backgroundColor: '#ffffff',  // 深色模式：白色背景
                        textColor: '#1f2937',        // 深色模式：深灰色文字
                        borderColor: '#e5e7eb'       // 深色模式：浅灰色边框
                    }
                }
            });
            
            // 增加提示次数
            await chrome.storage.local.set({ smartEnterToastCount: count + 1 });
        } catch (e) {
        }
    }
    
    /**
     * 插入换行符
     * @param {HTMLElement} inputElement - 输入框元素
     */
    _insertNewline(inputElement) {
        try {
            // 检查是否为 contenteditable 元素
            const isContentEditable = inputElement.contentEditable === 'true' || 
                                      inputElement.hasAttribute('contenteditable');
            
            if (isContentEditable) {
                // contenteditable 元素：模拟 Shift+Enter 按键事件
                // 让平台原生处理换行，确保格式正确
                
                // 确保元素有焦点
                if (document.activeElement !== inputElement) {
                    inputElement.focus();
                }
                
                // 标记正在插入换行，防止合成事件被 _handleKeyDown 再次拦截
                this.state.isInsertingNewline = true;
                
                // 创建 Shift+Enter 键盘事件
                const shiftEnterEvent = new KeyboardEvent('keydown', {
                    key: 'Enter',
                    code: 'Enter',
                    keyCode: 13,
                    which: 13,
                    shiftKey: true,
                    bubbles: true,
                    cancelable: true
                });
                
                // 触发事件，让平台原生处理换行
                inputElement.dispatchEvent(shiftEnterEvent);
                
                // 触发 keypress 和 keyup 事件
                const shiftEnterPress = new KeyboardEvent('keypress', {
                    key: 'Enter',
                    code: 'Enter',
                    keyCode: 13,
                    which: 13,
                    shiftKey: true,
                    bubbles: true,
                    cancelable: true
                });
                inputElement.dispatchEvent(shiftEnterPress);
                
                const shiftEnterUp = new KeyboardEvent('keyup', {
                    key: 'Enter',
                    code: 'Enter',
                    keyCode: 13,
                    which: 13,
                    shiftKey: true,
                    bubbles: true,
                    cancelable: true
                });
                inputElement.dispatchEvent(shiftEnterUp);
                
                // 清除标记
                this.state.isInsertingNewline = false;
            } else {
                // 普通 textarea/input 元素
                
                // 获取当前选区
                const start = inputElement.selectionStart;
                const end = inputElement.selectionEnd;
                const value = inputElement.value;
                
                // 插入换行符
                const newValue = value.substring(0, start) + '\n' + value.substring(end);
                inputElement.value = newValue;
                
                // 恢复光标位置
                const newPosition = start + 1;
                inputElement.selectionStart = newPosition;
                inputElement.selectionEnd = newPosition;
                
                // 触发 input 事件
                inputElement.dispatchEvent(new Event('input', { bubbles: true }));
                inputElement.dispatchEvent(new Event('change', { bubbles: true }));
            }
        } catch (e) {
        }
    }
    
    /**
     * 触发发送消息
     * 使用平台发送适配；默认模拟普通 Enter，让平台原生处理发送。
     * @param {HTMLElement} inputElement - 输入框元素
     */
    _triggerSend(inputElement) {
        try {
            // 检查是否可以发送（输入框非空）
            if (!this.adapter.canSend(inputElement)) {
                return;
            }
            
            // 确保元素有焦点
            if (document.activeElement !== inputElement) {
                inputElement.focus();
            }

            // 平台可使用原生发送按钮，避免合成 Enter 被编辑器忽略。
            if (typeof this.adapter.sendMessage === 'function') {
                this.adapter.sendMessage(inputElement);
                return;
            }
            
            // 设置标记，允许下一次 Enter 通过
            this.state.allowNextEnter = true;
            
            // 创建普通的 Enter 键事件（不带任何修饰键）
            const enterEvent = new KeyboardEvent('keydown', {
                key: 'Enter',
                code: 'Enter',
                keyCode: 13,
                which: 13,
                bubbles: true,
                cancelable: true
            });
            
            // 触发 Enter 事件，让平台原生处理发送
            inputElement.dispatchEvent(enterEvent);
            
            // 延迟清除标记，确保事件传播完成
            setTimeout(() => {
                this.state.allowNextEnter = false;
            }, 50);
        } catch (e) {
        }
    }
    
    /**
     * 重置状态
     */
    _resetState() {
        this.state.lastEnterTime = 0;
        this.state.enterCount = 0;
        this.state.savedSelection = null;
        this.state.allowNextEnter = false;
        this.state.isInsertingNewline = false;
        
        // 清除所有定时器
        if (this.newlineTimer) {
            clearTimeout(this.newlineTimer);
            this.newlineTimer = null;
        }
        
        if (this.debounceTimer) {
            clearTimeout(this.debounceTimer);
            this.debounceTimer = null;
        }
    }
    
    
    /**
     * 销毁管理器，清理所有监听器
     */
    destroy() {
        // 停止 DOM 监听
        this._stopObserving();
        
        // ✅ 停止健康检查
        if (this.healthCheckInterval) {
            clearInterval(this.healthCheckInterval);
            this.healthCheckInterval = null;
        }
        
        // 移除 Storage 监听
        this._detachStorageListener();
        
        // 页面可能保留多个隐藏输入框；统一释放监听，不能仅依赖当前可见节点。
        this._inputListenerController.abort();

        // 清理输入框的事件监听器引用
        try {
            if (this._externalKeydownInput) this._detachListener(this._externalKeydownInput);
            const input = this.adapter.findInputElement();
            if (input) {
                this._detachListener(input);
            }
        } catch (e) {
        }
        
        // ✅ 销毁提示词按钮
        if (this.promptButtonManager) {
            try {
                this.promptButtonManager.destroy();
                this.promptButtonManager = null;
            } catch (e) {
            }
        }
        
        // 清除所有定时器和状态
        this._resetState();
    }
}

;

// Source: js/smartInputBox/index.js
/**
 * Smart Input Box - 主入口
 * 
 * 智能输入框功能初始化
 * 
 * 功能：
 * - 提示词按钮（独立开关控制）
 * - Enter 键换行 + 快速双击 Enter 发送（独立开关控制）
 * 
 * 支持平台：
 * - 所有 features.promptButton === true 或 features.smartEnter === true 的平台
 */

(function() {
    'use strict';

    let initInFlight = false;

    // ✅ 检查当前平台是否支持智能输入功能
    async function isPlatformSupported() {
        const platform = await getCurrentPlatform();
        if (!platform) return false;

        // 检查平台是否支持智能输入功能（提示词按钮或智能回车之一）
        return platform.features?.promptButton === true || platform.features?.smartEnter === true;
    }
    
    // 等待 DOM 和依赖加载完成
    const initSmartInputBox = async () => {
        if (window.smartEnterManager || initInFlight) return;
        initInFlight = true;
        let manager = null;
        try {
            await TimelineI18n.ready();

            // 检查依赖是否加载
            if (typeof SmartEnterAdapterRegistry === 'undefined') {
                return;
            }
            
            if (typeof SmartEnterManager === 'undefined') {
                return;
            }
            
            // 获取当前页面的适配器
            const registry = window.smartEnterAdapterRegistry;
            if (!registry) {
                return;
            }
            
            const adapter = await registry.getAdapter();
            
            if (!adapter) {
                // 当前页面不匹配任何适配器，不启用功能
                return;
            }
            
            // ✅ 检查当前平台是否支持智能输入功能
            if (!(await isPlatformSupported())) {
                return;
            }
            
            // ✅ 只要平台支持，就创建管理器实例
            // Enter 换行和提示词按钮各自受自己的开关控制
            if (window.AITContentSession?.active === false) return;
            manager = new SmartEnterManager(adapter);
            window.AITContentSession?.onStop(() => manager.destroy());
            
            // 初始化
            await manager.init();
            
            // 保存到全局（方便调试和外部控制）
            window.smartEnterManager = manager;
            
        } catch (error) {
            // Do not cache a failed entry as started; release partial listeners before retrying.
            try { manager?.destroy(); } catch {}
            throw error;
        } finally {
            initInFlight = false;
        }
    };
    
    window.AITPlatformFeatures.register('smart-input', initSmartInputBox);
    
})();

;

// Source: js/scrollToBottom/scroll-to-bottom-manager.js
/**
 * Scroll To Bottom Manager
 * 
 * 回到底部按钮管理器
 * 在输入框上方居中显示一个 fixed 定位的"回到底部"按钮
 * 
 * 显示逻辑：监听时间轴的 activeChange 事件
 * - 当激活节点不是最后一个时显示按钮
 * - 当激活节点是最后一个时隐藏按钮
 */

class ScrollToBottomManager {
    constructor(adapter) {
        if (!adapter) {
            throw new Error('ScrollToBottomManager requires an adapter');
        }
        
        this.adapter = adapter;
        this.buttonElement = null;
        this.inputElement = null;
        this.isEnabled = false;
        this.isDestroyed = false;
        this.isVisible = false;
        this.globalEnabled = true;  // 全局开关状态（默认开启）
        this.platformSettings = {};
        this.storageListener = null;
        this._unsubscribeObserver = null;
        this._currentPlatform = null;
        
        // 事件处理器引用
        this._onResize = null;
        this._onActiveChange = null;
        this._onNodesChange = null;
        this._rafPending = false;
        
        // 配置
        this.config = {
            gap: 8  // 按钮与输入框的间距
        };
    }
    
    /**
     * 初始化
     */
    async init() {
        // ✅ 预加载平台信息（平台配置现在异步获取，缓存供同步方法使用）
        this._currentPlatform = await getCurrentPlatform();

        // 1. 加载平台设置
        await this._loadPlatformSettings();
        if (window.AITContentSession?.active === false) return;
        
        // 2. 监听 Storage 变化
        this._attachStorageListener();
        
        // 3. 创建按钮
        this._createButton();
        
        // 4. 检查是否启用
        if (this._isPlatformEnabled()) {
            this._enable();
        }
    }
    
    /**
     * 启用功能
     */
    _enable() {
        if (this.isEnabled) return;
        this.isEnabled = true;
        
        // 绑定事件（监听时间轴的激活变化事件）
        this._bindEvents();
        
        // 启动输入框检测（用于定位按钮位置）
        this._startInputDetection();
        
        // 尝试立即查找输入框
        this._findInputAndShow();
    }
    
    /**
     * 禁用功能
     */
    _disable() {
        if (!this.isEnabled) return;
        this.isEnabled = false;
        
        // 解绑事件
        this._unbindEvents();
        
        // 停止检测
        this._stopInputDetection();
        
        // 隐藏按钮
        this._hideButton();
        
        // 清空引用
        this.inputElement = null;
    }
    
    /**
     * 加载平台设置
     */
    async _loadPlatformSettings() {
        try {
            const result = await chrome.storage.local.get(['scrollToBottomPlatformSettings', 'scrollToBottomEnabled']);
            this.platformSettings = result.scrollToBottomPlatformSettings || {};
            // 全局开关，默认开启
            this.globalEnabled = result.scrollToBottomEnabled !== false;
        } catch (e) {
            this.platformSettings = {};
            this.globalEnabled = true;
        }
    }
    
    /**
     * 检查当前平台是否启用
     */
    _isPlatformEnabled() {
        try {
            // 先检查全局开关
            if (!this.globalEnabled) return false;
            
            const platform = this._currentPlatform;
            if (!platform) return false;
            if (platform.features?.scrollToBottom !== true) return false;
            return this.platformSettings[platform.id] !== false;
        } catch (e) {
            return true;
        }
    }
    
    /**
     * 监听 Storage 变化
     */
    _attachStorageListener() {
        this.storageListener = (changes, areaName) => {
            if (this.isDestroyed) return;
            
            if (areaName === 'local') {
                let needsUpdate = false;
                
                // 监听全局开关变化
                if (changes.scrollToBottomEnabled) {
                    this.globalEnabled = changes.scrollToBottomEnabled.newValue !== false;
                    needsUpdate = true;
                }
                
                // 监听平台设置变化
                if (changes.scrollToBottomPlatformSettings) {
                    this.platformSettings = changes.scrollToBottomPlatformSettings.newValue || {};
                    needsUpdate = true;
                }
                
                if (needsUpdate) {
                    const shouldEnable = this._isPlatformEnabled();
                    
                    if (shouldEnable && !this.isEnabled) {
                        this._enable();
                    } else if (!shouldEnable && this.isEnabled) {
                        this._disable();
                    }
                }
            }
        };
        chrome.storage.onChanged.addListener(this.storageListener);
    }
    
    /**
     * 创建按钮元素
     */
    _createButton() {
        if (this.buttonElement) return;
        
        const button = document.createElement('div');
        button.className = 'ait-scroll-to-bottom-btn';
        // 向下箭头图标 ↓
        button.innerHTML = `
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <line x1="12" y1="5" x2="12" y2="19"/>
                <polyline points="6 13 12 19 18 13"/>
            </svg>
        `;
        
        // 使用事件委托
        window.eventDelegateManager?.on('click', '.ait-scroll-to-bottom-btn', (e) => {
            e.preventDefault();
            e.stopPropagation();
            this._scrollToBottom();
        });
        
        document.body.appendChild(button);
        this.buttonElement = button;
    }
    
    /**
     * 绑定事件
     */
    _bindEvents() {
        // resize 事件
        const scheduleUpdate = () => {
            if (this._rafPending) return;
            this._rafPending = true;
            
            requestAnimationFrame(() => {
                this._rafPending = false;
                this._updatePosition();
            });
        };
        
        this._onResize = scheduleUpdate;
        window.addEventListener('resize', this._onResize);
        
        // 监听时间轴的激活节点变化事件
        this._onActiveChange = (e) => {
            const { totalCount, isLast } = e.detail || {};
            
            // 如果激活的是最后一个节点，说明用户在底部，隐藏按钮
            // 如果不是最后一个节点，显示按钮
            if (isLast) {
                this._hideButton();
            } else if (totalCount > 1) {
                this._showButton();
            }
        };
        window.addEventListener('timeline:activeChange', this._onActiveChange);
        
        // 监听节点数量变化事件（新消息添加时激活状态会通过 activeChange 事件通知）
        this._onNodesChange = () => {};
        window.addEventListener('timeline:nodesChange', this._onNodesChange);
    }
    
    /**
     * 解绑事件
     */
    _unbindEvents() {
        this._rafPending = false;
        
        if (this._onResize) {
            window.removeEventListener('resize', this._onResize);
            this._onResize = null;
        }
        
        if (this._onActiveChange) {
            window.removeEventListener('timeline:activeChange', this._onActiveChange);
            this._onActiveChange = null;
        }
        
        if (this._onNodesChange) {
            window.removeEventListener('timeline:nodesChange', this._onNodesChange);
            this._onNodesChange = null;
        }
    }
    
    /**
     * 启动输入框检测
     */
    _startInputDetection() {
        if (this._unsubscribeObserver) return;
        
        if (window.DOMObserverManager) {
            this._unsubscribeObserver = window.DOMObserverManager.getInstance().subscribeBody('scroll-to-bottom', {
                callback: () => {
                    if (!this.isEnabled || this.isDestroyed) return;
                    
                    if (!this.inputElement) {
                        this._findInputAndShow();
                    } else if (!document.body.contains(this.inputElement)) {
                        this.inputElement = null;
                        this._hideButton();
                        this._findInputAndShow();
                    } else if (this.isVisible) {
                        // 只有在按钮可见时才更新位置
                        this._updatePosition();
                    }
                },
                filter: { hasAddedNodes: true },
                debounce: 300
            });
        }
    }
    
    /**
     * 停止输入框检测
     */
    _stopInputDetection() {
        if (this._unsubscribeObserver) {
            this._unsubscribeObserver();
            this._unsubscribeObserver = null;
        }
    }
    
    /**
     * 查找输入框并更新位置
     */
    _findInputAndShow() {
        if (!this.isEnabled || this.isDestroyed) return;
        
        try {
            const selector = this.adapter.getInputSelector();
            const input = document.querySelector(selector);
            
            if (input) {
                this.inputElement = input;
                // 按钮显示/隐藏由 timeline:activeChange 事件控制
                // 这里只更新位置
                this._updatePosition();
            }
        } catch (e) {
            // 忽略
        }
    }
    
    /**
     * 更新按钮位置
     */
    _updatePosition() {
        if (!this.buttonElement || !this.inputElement || this.isDestroyed || !this.isEnabled) {
            return;
        }
        
        try {
            // 获取定位参考元素
            const referenceElement = this.adapter.getPositionReferenceElement?.(this.inputElement) || this.inputElement;
            const rect = referenceElement.getBoundingClientRect();
            
            // 参考元素不可见
            if (rect.width === 0 || rect.height === 0) {
                return;
            }
            
            // 获取按钮尺寸
            const buttonRect = this.buttonElement.getBoundingClientRect();
            const buttonWidth = buttonRect.width || 38;
            
            // 获取平台偏移量
            const offset = this.adapter.getScrollToBottomOffset?.() || { top: 0 };
            
            // 计算位置：对话框水平居中，垂直位置在输入框上方
            const top = rect.top + offset.top - buttonWidth - this.config.gap;
            const left = rect.left + (rect.width - buttonWidth) / 2;  // 水平居中
            
            // 边界检查
            const safeTop = Math.max(8, Math.min(top, window.innerHeight - buttonWidth - 8));
            const safeLeft = Math.max(8, Math.min(left, window.innerWidth - buttonWidth - 8));
            
            // 设置位置
            this.buttonElement.style.top = `${safeTop}px`;
            this.buttonElement.style.left = `${safeLeft}px`;
            this.buttonElement.style.right = 'auto';
        } catch (e) {
            // 忽略
        }
    }
    
    /**
     * 显示按钮
     */
    _showButton() {
        if (!this.buttonElement || this.isVisible) return;
        
        this.isVisible = true;
        this._updatePosition();
        this.buttonElement.classList.add('visible');
    }
    
    /**
     * 隐藏按钮
     */
    _hideButton() {
        if (!this.buttonElement || !this.isVisible) return;
        
        this.isVisible = false;
        this.buttonElement.classList.remove('visible');
    }
    
    /**
     * 滚动到底部
     * 优先使用时间轴的 API（支持虚拟滚动）
     */
    _scrollToBottom() {
        // 优先使用时间轴的对外 API（正确处理虚拟滚动）
        if (window.timelineManager?.scrollToLast) {
            const success = window.timelineManager.scrollToLast();
            if (success) return;
        }
        
        // fallback: 使用原生滚动（不支持时间轴的平台）
        const scrollContainer = this._detectScrollContainer();
        if (!scrollContainer) return;
        
        try {
            if (scrollContainer === window) {
                window.scrollTo({
                    top: document.documentElement.scrollHeight,
                    behavior: 'smooth'
                });
            } else {
                scrollContainer.scrollTo({
                    top: scrollContainer.scrollHeight,
                    behavior: 'smooth'
                });
            }
        } catch (e) {
            if (scrollContainer === window) {
                window.scrollTo(0, document.documentElement.scrollHeight);
            } else {
                scrollContainer.scrollTop = scrollContainer.scrollHeight;
            }
        }
    }
    
    /**
     * 自动检测滚动容器（复用时间轴逻辑）
     */
    _detectScrollContainer() {
        // 优先使用适配器指定的滚动容器
        const adapterContainer = this.adapter.getScrollContainer?.();
        if (adapterContainer && adapterContainer !== window) {
            return adapterContainer;
        }
        
        // 从输入框向上遍历查找滚动容器
        let parent = this.inputElement?.parentElement;
        while (parent && parent !== document.body) {
            const style = window.getComputedStyle(parent);
            if (style.overflowY === 'auto' || style.overflowY === 'scroll') {
                return parent;
            }
            parent = parent.parentElement;
        }
        
        // 备用：使用 document.scrollingElement
        return document.scrollingElement || document.documentElement || window;
    }
    
    /**
     * 销毁
     */
    destroy() {
        this.isDestroyed = true;
        this._disable();
        
        // 移除 Storage 监听
        if (this.storageListener) {
            try { chrome.storage.onChanged.removeListener(this.storageListener); } catch {}
            this.storageListener = null;
        }
        
        // 移除按钮
        if (this.buttonElement && this.buttonElement.parentNode) {
            this.buttonElement.parentNode.removeChild(this.buttonElement);
            this.buttonElement = null;
        }
    }
}

// ==================== 初始化入口 ====================

(function() {
    'use strict';
    
    let scrollToBottomManager = null;
    let initInFlight = false;
    
    async function isPlatformSupported() {
        const platform = typeof getCurrentPlatform === 'function' ? await getCurrentPlatform() : null;
        return platform?.features?.scrollToBottom === true;
    }
    
    async function getAdapter() {
        // 使用全局已有的 registry 实例
        if (window.smartEnterAdapterRegistry) {
            return await window.smartEnterAdapterRegistry.getAdapter();
        }
        return null;
    }
    
    async function init() {
        if (scrollToBottomManager || initInFlight) return;
        initInFlight = true;
        try {
            await TimelineI18n.ready();

            if (!(await isPlatformSupported())) return;

            const adapter = await getAdapter();
            if (!adapter || window.AITContentSession?.active === false) return;

            scrollToBottomManager = new ScrollToBottomManager(adapter);
            await scrollToBottomManager.init();
        } catch (e) {
            cleanup();
            throw e;
        } finally {
            initInFlight = false;
        }
    }
    
    function cleanup() {
        if (scrollToBottomManager) {
            scrollToBottomManager.destroy();
            scrollToBottomManager = null;
        }
    }
    
    window.AITContentSession?.onStop(cleanup);
    window.AITPlatformFeatures.register('scroll-to-bottom', () => {
        window.addEventListener('beforeunload', cleanup);
        return init();
    }, { delay: 500 });
})();

