// Source: js/timeline/adapters/tongyi.js
/**
 * Tongyi (通义千问) Adapter
 * 
 * Supports: qianwen.com
 * Features: 使用 class 前缀识别用户消息和文本内容
 */

class TongyiAdapter extends SiteAdapter {
    constructor() {
        super();
    }

    async matches(url) {
        return matchesPlatform(url, 'tongyi');
    }

    getUserMessageSelector() {
        // 基于 class 前缀 "questionItem" 识别用户消息容器
        return '[class*="questionItem"]';
    }

    generateTurnId(element, index) {
        const msgId = element.getAttribute('data-msgid');
        if (msgId) return `tongyi-${msgId}`;
        return `tongyi-${index}`;
    }

    extractIndexFromTurnId(turnId) {
        if (!turnId) return null;
        if (turnId.startsWith('tongyi-')) {
            const part = turnId.substring(7);
            const parsed = parseInt(part, 10);
            return (String(parsed) === part) ? parsed : part;
        }
        return null;
    }

    generateTurnIdFromIndex(identifier) {
        return `tongyi-${identifier}`;
    }

    findMarkerByStoredIndex(storedKey, markers, markerMap) {
        if (storedKey === null || storedKey === undefined) return null;
        const turnId = `tongyi-${storedKey}`;
        const marker = markerMap?.get(turnId);
        if (marker) return marker;
        if (typeof storedKey === 'number' && storedKey >= 0 && storedKey < markers.length) {
            return markers[storedKey];
        }
        return null;
    }

    extractText(element) {
        // 文本在 bubble-- 开头的 class 中
        const bubble = element.querySelector('[class*="bubble"]');
        const text = (bubble?.textContent || element.textContent || '').trim();
        return text || '[图片或文件]';
    }
    
    getTimeLabelTarget(element) {
        return element.querySelector('[class*="bubble"]') || element;
    }

    isConversationRoute(pathname) {
        // 通义千问对话 URL:
        // 对话: /chat/{id}
        // 分享: /share?shareId={id}
        return pathname.startsWith('/chat/') || 
               (pathname.startsWith('/share') && location.search.includes('shareId='));
    }

    extractConversationId(pathname) {
        try {
            // 对话 URL: /chat/{id}
            if (pathname.startsWith('/chat/')) {
                const id = pathname.replace('/chat/', '').split('/')[0];
                if (id) return id;
            }
            // 分享 URL: /share?shareId={id}
            if (pathname.startsWith('/share')) {
                const params = new URLSearchParams(location.search);
                return params.get('shareId');
            }
            return null;
        } catch {
            return null;
        }
    }

    findConversationContainer(firstMessage) {
        // 查找对话容器 - 使用 LCA（最近共同祖先）算法
        return ContainerFinder.findConversationContainer(firstMessage, {
            messageSelector: this.getUserMessageSelector()
        });
    }

    getTimeLabelPosition() {
        return { top: '0px', right: '0px', paddingTop: '4px' };
    }

    getTimelinePosition() {
        // 通义千问位置配置
        return {
            top: '120px',       // 避开顶部导航栏
            right: '22px',     // 右侧边距
            bottom: '120px',    // 避开底部输入框
        };
    }
    
    getStarChatButtonTarget() {
        const shareLink = document.querySelector('use[*|href="#qwpcicon-transmission"]') ||
            document.querySelector('[data-icon-type="qwpcicon-transmission"]');
        if (shareLink) {
            const button = shareLink.closest('button');
            return button;
        }
        return null;
    }
    
    getDefaultChatTheme() {
        // 从 text-primary text-title-attachment 元素中获取对话标题
        try {
            const titleElement = document.querySelector('.text-primary.text-title-attachment');
            if (titleElement) {
                const title = titleElement.textContent?.trim() || '';
                return title;
            }
            return '';
        } catch {
            return '';
        }
    }
    
    /**
     * 检测 AI 是否正在生成回答
     * 通义千问: 当存在 class 包含 "stop-" 的元素时，表示正在生成
     * @returns {boolean}
     */
    isAIGenerating() {
        const stopElement = document.querySelector('[class*="stop-"]');
        return !!stopElement;
    }
    
}

;

// Source: js/timeline/adapters/qwen.js
/**
 * Qwen International (千问国际版) Adapter
 *
 * Supports: chat.qwen.ai
 *
 * DOM 结构：
 *   .qwen-chat-message-user         — 用户消息容器（id 含 uuid）
 *   .user-message-content           — 用户消息文本
 *   #chat-message-container         — 对话消息容器
 *   #chat-messages-scroll-container — 滚动容器
 *   button.stop-button              — AI 生成中的停止按钮
 *   #qwen-chat-header-right         — 标题栏右侧操作区
 */

class QwenAdapter extends SiteAdapter {
    constructor() {
        super();
    }

    async matches(url) {
        return matchesPlatform(url, 'qwen');
    }

    getUserMessageSelector() {
        return '.qwen-chat-message-user';
    }

    generateTurnId(element, index) {
        const id = element.id;
        if (id && id !== 'qwen-chat-message-user-undefined' && id.length > 24) {
            return `qwen-${id}`;
        }
        return `qwen-${index}`;
    }

    extractIndexFromTurnId(turnId) {
        if (!turnId) return null;
        if (turnId.startsWith('qwen-')) {
            const part = turnId.substring(5);
            const parsed = parseInt(part, 10);
            return (String(parsed) === part) ? parsed : part;
        }
        return null;
    }

    generateTurnIdFromIndex(identifier) {
        return `qwen-${identifier}`;
    }

    findMarkerByStoredIndex(storedKey, markers, markerMap) {
        if (storedKey === null || storedKey === undefined) return null;
        const turnId = `qwen-${storedKey}`;
        const marker = markerMap?.get(turnId);
        if (marker) return marker;
        if (typeof storedKey === 'number' && storedKey >= 0 && storedKey < markers.length) {
            return markers[storedKey];
        }
        return null;
    }

    extractText(element) {
        const content = element.querySelector('.user-message-content');
        const text = (content?.textContent || element.textContent || '').trim();
        return text || '[图片或文件]';
    }

    getTimeLabelTarget(element) {
        return element.querySelector('.chat-user-message') || element;
    }

    isConversationRoute(pathname) {
        return pathname.startsWith('/c/');
    }

    extractConversationId(pathname) {
        if (pathname.startsWith('/c/')) {
            return pathname.replace('/c/', '').split('/')[0] || null;
        }
        return null;
    }

    findConversationContainer(firstMessage) {
        const container = document.querySelector('#chat-message-container');
        if (container) return container;
        return ContainerFinder.findConversationContainer(firstMessage, {
            messageSelector: this.getUserMessageSelector()
        });
    }

    getTimeLabelPosition() {
        return { top: '0px', right: '30px', paddingTop: '18px' };
    }

    getTimelinePosition() {
        return {
            top: '120px',
            right: '22px',
            bottom: '120px',
        };
    }

    getStarChatButtonTarget() {
        const headerRight = document.querySelector('#qwen-chat-header-right');
        if (headerRight) {
            const modal = headerRight.querySelector('.chat-extension-modal');
            if (modal) return modal;
        }
        return null;
    }

    getDefaultChatTheme() {
        try {
            const active = document.querySelector('.chat-item-drag-active .chat-item-drag-link-content-tip-text');
            if (active?.textContent?.trim()) return active.textContent.trim();
            return '';
        } catch { return ''; }
    }

    isAIGenerating() {
        return !!document.querySelector('button.stop-button');
    }
}

;

// Source: js/timeline/adapters/kimi.js
/**
 * Kimi Adapter
 * 
 * Supports: kimi.com, kimi.com/share/*
 * Features: 固定 class 名 user-content
 */

class KimiAdapter extends SiteAdapter {
    constructor() {
        super();
    }

    async matches(url) {
        return matchesPlatform(url, 'kimi');
    }

    getUserMessageSelector() {
        // Kimi 使用消息项级别的选择器，匹配包含 .user-content 的消息项
        // 这样选择器匹配的元素就是消息项本身，与其他平台一致
        return '.chat-content-item:has(.user-content)';
    }

    getAssistantMessageSelector() {
        return '.chat-content-item-assistant';
    }

    generateTurnId(element, index) {
        return `kimi-${index}`;
    }

    extractText(element) {
        // 从消息项中查找 .user-content 元素获取文本
        const userContent = element.querySelector('.user-content');
        const text = (userContent?.textContent || element.textContent || '').trim();
        return text || '[图片或文件]';
    }
    
    getTimeLabelTarget(element) {
        return element.querySelector('.user-content') || element;
    }

    isConversationRoute(pathname) {
        // Kimi 对话 URL: /chat/{id} 或分享页面 /share/{id}
        return pathname.includes('/chat/') || pathname.includes('/share/');
    }

    extractConversationId(pathname) {
        try {
            // 从 /chat/cuq3h25m2citjh45prb0 或 /share/xxx 提取对话 ID
            const chatMatch = pathname.match(/\/chat\/([^\/]+)/);
            if (chatMatch) return chatMatch[1];
            
            const shareMatch = pathname.match(/\/share\/([^\/]+)/);
            if (shareMatch) return shareMatch[1];
            
            return null;
        } catch {
            return null;
        }
    }

    findConversationContainer(firstMessage) {
        // 选择器现在匹配的是消息项 .chat-content-item，使用标准 LCA 算法即可
        return ContainerFinder.findConversationContainer(firstMessage, {
            messageSelector: this.getUserMessageSelector()
        });
    }

    getTimelinePosition() {
        // Kimi 位置配置
        return {
            top: '120px',       // 避开顶部导航栏
            right: '22px',     // 右侧边距
            bottom: '120px',    // 避开底部输入框
        };
    }
    
    /**
     * 获取时间标签位置配置
     */
    getTimeLabelPosition() {
        // 相对于消息元素定位
        return {
            top: '-18px',
            right: '5px'
        };
    }
    
    getStarChatButtonTarget() {
        // 返回 chat-header-actions 下的 icon 元素，收藏按钮将插入到它前面
        const headerActions = document.querySelector('.chat-header-actions');
        if (!headerActions) return null;
        return headerActions.querySelector('.icon');
    }
    
    getDefaultChatTheme() {
        // Kimi 使用页面标题作为默认主题，并过滤尾部的 " - Kimi"
        const title = document.title || '';
        return title.replace(/\s*-\s*Kimi\s*$/i, '').trim();
    }
    
    /**
     * 检测 AI 是否正在生成回答
     * Kimi: 当 .send-button-container 元素包含 stop class 时，表示正在生成
     * @returns {boolean}
     */
    isAIGenerating() {
        const sendButtonContainer = document.querySelector('.send-button-container');
        // ✅ 必须返回 boolean
        return !!(sendButtonContainer && sendButtonContainer.classList.contains('stop'));
    }
}

;

