// Source: js/timeline/adapters/custom.js
/**
 * Config-driven adapter for user-added AI sites.
 *
 * The adapter intentionally accepts only selectors and simple URL includes.
 * It never executes user-provided JavaScript.
 */
class CustomSiteAdapter extends SiteAdapter {
    constructor(config) {
        super();
        this.config = config || {};
        this.id = this.config.id || `custom-${this._slugify(location.hostname)}`;
        this.isCustom = true;
    }

    matches(url) {
        if (this.config.enabled === false) return false;
        if (!Array.isArray(this.config.sites) || this.config.sites.length === 0) return false;
        try {
            const hostname = new URL(url).hostname;
            return this.config.sites.some(site => hostname === site || hostname.endsWith(`.${site}`));
        } catch {
            return false;
        }
    }

    getUserMessageSelector() {
        return this.config.userMessageSelector || '';
    }

    getFeatures() {
        return this.config.features || {};
    }

    generateTurnId(element, index) {
        const attr = this.config.turnIdAttribute;
        const attrValue = attr ? element?.getAttribute?.(attr) : null;
        return attrValue ? `${this.id}-${attrValue}` : `${this.id}-${index}`;
    }

    extractText(element) {
        const textSelector = this.config.textSelector || '';
        const target = textSelector ? element?.querySelector?.(textSelector) : element;
        const text = (target?.textContent || '').trim();
        return text || '[图片或文件]';
    }

    isConversationRoute(pathname) {
        if (this.config.conversationUrlPattern) {
            return this._matchesConversationUrl(location.href);
        }

        const includes = this.config.conversationPathIncludes || [];
        if (!includes.length) return true;
        return includes.some(part => part && pathname.includes(part));
    }

    findConversationContainer(firstMessage) {
        const selector = this.config.conversationContainerSelector || '';
        if (selector) {
            const container = document.querySelector(selector);
            if (container) return container;
        }
        return ContainerFinder.findConversationContainer(firstMessage, {
            messageSelector: this.getUserMessageSelector()
        }) || super.findConversationContainer(firstMessage);
    }

    getTimelinePosition() {
        return {
            top: this.config.timelineTop || '120px',
            right: this.config.timelineRight || '22px',
            bottom: this.config.timelineBottom || '120px'
        };
    }

    getTimelineBarBackground() {
        return this.config.timelineBarBackground || null;
    }

    getTimelineZIndex() {
        return this.config.timelineZIndex ?? null;
    }

    getScrollOffset() {
        const offset = Number(this.config.scrollOffset);
        return Number.isFinite(offset) ? offset : 30;
    }

    shouldHideTimeline() {
        const selectors = this.config.hideTimelineSelectors || [];
        return selectors.some(selector => {
            try {
                return !!selector && document.querySelector(selector) !== null;
            } catch {
                return false;
            }
        });
    }

    getTimelineVisibilitySelectors() {
        return (this.config.hideTimelineSelectors || []).filter(Boolean);
    }

    isAIGenerating() {
        const selector = this.config.aiGeneratingSelector || '';
        if (!selector) return null;
        try {
            const el = document.querySelector(selector);
            if (!el) return false;
            if (this.config.aiGeneratingMode === 'not-hidden') {
                const style = window.getComputedStyle(el);
                return style.display !== 'none' && style.visibility !== 'hidden' && style.opacity !== '0';
            }
            return true;
        } catch {
            return null;
        }
    }

    _matchesConversationUrl(url) {
        const pattern = this.config.conversationUrlPattern;
        if (!pattern) return true;

        try {
            const regex = new RegExp(pattern);
            const urlWithoutProtocol = String(url || '').replace(/^[a-z][a-z0-9+.-]*:\/\//i, '');
            return regex.test(url) || regex.test(urlWithoutProtocol);
        } catch {
            return false;
        }
    }

    _slugify(value) {
        return String(value || 'site')
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, '-')
            .replace(/^-+|-+$/g, '') || 'site';
    }
}

;

// Source: js/timeline/adapters/registry.js
/**
 * Adapter Registry
 * 
 * Manages all site adapters and provides auto-detection
 */

class SiteAdapterRegistry {
    constructor() {
        this.builtInAdapters = [];
        this.customAdapters = [];
        this._registerBuiltInAdapters();
        this.adapters = [...this.builtInAdapters];
    }

    /**
     * 注册单个内置适配器，并挂上 platformId（与 SITE_INFO 的 id 一致）。
     * 让外部（如镜像站检测）能统一拿到「平台 id → 适配器」，无需另维护一份平台清单。
     */
    _registerAdapter(platformId, adapter) {
        if (!platformId || !adapter) return;
        adapter.platformId = platformId;
        this.builtInAdapters.push(adapter);
    }

    /**
     * 注册所有内置适配器。
     * ✨ 新增平台只需在这里加一行，镜像站检测等消费方会自动覆盖。
     */
    _registerBuiltInAdapters() {
        this._registerAdapter('chatgpt', new ChatGPTAdapter());
        this._registerAdapter('gemini', new GeminiAdapter());
        this._registerAdapter('doubao', new DoubaoAdapter());
        this._registerAdapter('deepseek', new DeepSeekAdapter());
        this._registerAdapter('yiyan', new YiyanAdapter());
        this._registerAdapter('tongyi', new TongyiAdapter());
        this._registerAdapter('qwen', new QwenAdapter());
        this._registerAdapter('kimi', new KimiAdapter());
        this._registerAdapter('yuanbao', new YuanbaoAdapter());
        this._registerAdapter('grok', new GrokAdapter());
        this._registerAdapter('perplexity', new PerplexityAdapter());
        this._registerAdapter('claude', new ClaudeAdapter());
        this._registerAdapter('notebooklm', new NotebookLMAdapter());
    }

    async loadCustomAdapters() {
        try {
            const staticConfigs = Array.isArray(window.CUSTOM_SITE_INFO)
                ? window.CUSTOM_SITE_INFO
                : [];
            const builtInSiteList = typeof getSiteInfoList === 'function'
                ? await getSiteInfoList()
                : [];
            this.customAdapters = staticConfigs
                .filter(config => config?.enabled !== false && Array.isArray(config.sites) && config.sites.length > 0)
                .filter(config => !config.sites.some(site => this._isBuiltInSite(site, builtInSiteList)))
                .map(config => new CustomSiteAdapter(config));
        } catch {
            this.customAdapters = [];
        }
        this.adapters = [...this.builtInAdapters, ...this.customAdapters];
    }

    _isBuiltInSite(site, builtInSiteList) {
        if (!site || !Array.isArray(builtInSiteList)) return false;
        return builtInSiteList.some(platform => platform.sites.some(builtInSite => (
            site === builtInSite ||
            site.endsWith(`.${builtInSite}`) ||
            builtInSite.endsWith(`.${site}`)
        )));
    }

    /**
     * Detect and return the appropriate adapter for current site
     * @returns {Promise<SiteAdapter|null>}
     */
    async detectAdapter() {
        const url = location.href;
        for (const adapter of this.adapters) {
            if (await adapter.matches(url)) {
                return adapter;
            }
        }
        return null;
    }

    /**
     * Check if current site is supported
     * @returns {Promise<boolean>}
     */
    async isSupportedSite() {
        return (await this.detectAdapter()) !== null;
    }

    /**
     * 获取全部已注册适配器（含自定义站点适配器）。
     * 自定义站点适配器没有 platformId，消费方可据此过滤。
     * @returns {Array<SiteAdapter>}
     */
    getAllAdapters() {
        return [...this.adapters];
    }
}

// 全局只读单例：供镜像站检测等模块复用，避免重复 new 与重复维护平台清单。
// timeline/quickAsk 仍各自 new SiteAdapterRegistry()，互不影响。
if (typeof window.siteAdapterRegistry === 'undefined') {
    window.siteAdapterRegistry = new SiteAdapterRegistry();
}

;

// Source: js/mermaid/index.js
/**
 * MermaidRenderer - Mermaid 检测工具 + 全屏查看器
 * 
 * 职责：
 * 1. detect(codeEl, wrapperEl) — 供 Runner 的 initializeCodeBlock 调用，
 *    判断代码块是否为 Mermaid 语法
 * 2. openFullscreen(svg) — 供输出面板点击图表时调用，
 *    打开全屏查看器（缩放 + 拖拽 + ESC 关闭）
 * 
 * 不再负责：内联渲染、扫描、DOM 监听（全部由 Runner 体系统一管理）
 * 
 * 依赖：detectDarkMode()（全局工具函数）
 */

(function() {
    'use strict';

    // ===== Mermaid 语法检测 =====

    // 图表类型关键字（首行匹配）
    const DIAGRAM_KEYWORDS = [
        'graph', 'flowchart', 'sequenceDiagram', 'classDiagram',
        'stateDiagram', 'stateDiagram-v2', 'erDiagram',
        'gantt', 'pie', 'gitGraph', 'journey', 'mindmap',
        'timeline', 'quadrantChart', 'xychart-beta', 'xychart',
        'sankey-beta', 'sankey', 'block-beta', 'block',
        'packet-beta', 'packet', 'architecture-beta', 'architecture',
        'C4Context', 'C4Container', 'C4Component', 'C4Dynamic', 'C4Deployment',
        'requirementDiagram', 'requirement', 'zenuml',
        'kanban', 'radar-beta', 'treemap'
    ];

    // 明确的编程语言标签（命中则跳过 Mermaid 检测）
    const KNOWN_PROG_LANGS = new Set([
        'javascript', 'js', 'typescript', 'ts', 'python', 'py',
        'java', 'c', 'c++', 'cpp', 'c#', 'csharp', 'go', 'golang',
        'rust', 'ruby', 'rb', 'php', 'swift', 'kotlin', 'scala',
        'r', 'matlab', 'perl', 'lua', 'dart', 'elixir', 'erlang',
        'haskell', 'ocaml', 'clojure', 'groovy', 'shell', 'bash',
        'powershell', 'sql', 'html', 'css', 'scss', 'less', 'sass',
        'xml', 'json', 'yaml', 'yml', 'toml', 'ini', 'csv',
        'markdown', 'md', 'latex', 'tex', 'dockerfile', 'makefile',
        'cmake', 'graphql', 'protobuf', 'proto', 'solidity',
        'assembly', 'asm', 'vhdl', 'verilog', 'jsx', 'tsx',
        'vue', 'svelte', 'wasm', 'zig', 'nim', 'v', 'vlang',
        'fortran', 'cobol', 'pascal', 'delphi', 'ada', 'lisp',
        'scheme', 'racket', 'prolog', 'objective-c', 'objc'
    ]);

    /**
     * 判断代码文本是否为 Mermaid 语法
     */
    function isMermaidSyntax(code) {
        if (!code || code.length < 30) return false;

        const lines = code.split('\n').filter(l => l.trim() !== '');
        if (lines.length < 2) return false;

        // 跳过 Mermaid 注释行（%%）
        let firstContentLine = '';
        for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed.startsWith('%%')) {
                firstContentLine = trimmed;
                break;
            }
        }
        if (!firstContentLine) return false;

        // 首行是否以图表关键字开头
        const lower = firstContentLine.toLowerCase();
        const matched = DIAGRAM_KEYWORDS.some(kw => {
            const kwLower = kw.toLowerCase();
            return lower === kwLower ||
                   lower.startsWith(kwLower + ' ') ||
                   lower.startsWith(kwLower + '\t');
        });
        if (!matched) return false;

        // 流式安全：末行不能以未完成连接符结尾
        const lastLine = lines[lines.length - 1].trim();
        const incomplete = ['-->', '---', '-.', '==>', '~~~', '-->|', '--|', '==>|'];
        const trailing = ['{', '[', '(', '<', '|', ',', ':'];
        if (incomplete.some(e => lastLine.endsWith(e))) return false;
        if (trailing.some(c => lastLine.endsWith(c))) return false;

        return true;
    }

    /**
     * 从代码块 DOM 中读取语言标注
     */
    function readLanguageLabel(codeEl, wrapperEl) {
        // class 中的 language-xxx（ChatGPT、Claude 等）
        const classList = (codeEl.className || '') + ' ' + (codeEl.parentElement?.className || '');
        const match = classList.match(/(?:language|lang|hljs)-(\w[\w+#-]*)/i);
        if (match) return match[1].toLowerCase();

        // Gemini code-block 装饰区域
        const deco = wrapperEl.querySelector('.code-block-decoration, [class*="code-header"]');
        if (deco) {
            const el = deco.querySelector('span, [class*="lang"]');
            const t = el?.textContent?.trim().toLowerCase();
            if (t && t.length < 30) return t;
        }

        // DeepSeek code-header
        const hdr = wrapperEl.querySelector('.code-header span, .md-code-block-info-bar span');
        if (hdr) {
            const t = hdr.textContent?.trim().toLowerCase();
            if (t && t.length < 30) return t;
        }

        return null;
    }

    /**
     * 检测代码块是否为 Mermaid
     * 
     * 策略：
     * 1. 语言标签 === 'mermaid' → true
     * 2. 语言标签是明确的编程语言 → false
     * 3. 无标签或泛化标签 → 内容启发式检测
     * 
     * @param {HTMLElement} codeEl - 代码元素
     * @param {HTMLElement} wrapperEl - 布局容器
     * @returns {boolean}
     */
    function detect(codeEl, wrapperEl) {
        const label = readLanguageLabel(codeEl, wrapperEl);
        if (label === 'mermaid') return true;
        if (label && KNOWN_PROG_LANGS.has(label)) return false;
        return isMermaidSyntax(codeEl.textContent || '');
    }

    // ===== 全屏查看器 =====

    let fullscreenOverlay = null;
    let viewerZoom = 1;
    let viewerPanX = 0;
    let viewerPanY = 0;
    let isPanning = false;
    let panStartX = 0;
    let panStartY = 0;

    function safeI18n(key, fallback) {
        try { return TimelineI18n.getMessage(key) || fallback; }
        catch { return fallback; }
    }

    /**
     * 打开全屏查看器
     * @param {string} svg - SVG 内容
     */
    function openFullscreen(svg) {
        if (fullscreenOverlay) closeFullscreen();

        viewerZoom = 1;
        viewerPanX = 0;
        viewerPanY = 0;

        const overlay = document.createElement('div');
        overlay.className = 'ait-mermaid-overlay';

        const canvas = document.createElement('div');
        canvas.className = 'ait-mermaid-canvas';
        canvas.innerHTML = svg;
        applyTransform(canvas);

        const controls = document.createElement('div');
        controls.className = 'ait-mermaid-controls';
        controls.innerHTML = `
            <button class="ait-mc-btn" data-action="zoom-in" title="Zoom In">+</button>
            <button class="ait-mc-btn" data-action="zoom-out" title="Zoom Out">−</button>
            <button class="ait-mc-btn" data-action="reset" title="Reset">⊙</button>
            <button class="ait-mc-btn ait-mc-close" data-action="close" title="Close">✕</button>
        `;

        const hint = document.createElement('div');
        hint.className = 'ait-mermaid-hint';
        hint.textContent = safeI18n('mermaidViewerHint', 'Scroll to zoom · Drag to pan · ESC to close');

        overlay.appendChild(canvas);
        overlay.appendChild(controls);
        overlay.appendChild(hint);
        document.body.appendChild(overlay);

        requestAnimationFrame(() => overlay.classList.add('visible'));
        fullscreenOverlay = overlay;

        controls.addEventListener('click', (e) => {
            const action = e.target.closest('[data-action]')?.dataset.action;
            if (!action) return;
            e.stopPropagation();
            switch (action) {
                case 'zoom-in':  viewerZoom = Math.min(viewerZoom * 1.25, 10); break;
                case 'zoom-out': viewerZoom = Math.max(viewerZoom / 1.25, 0.1); break;
                case 'reset':    viewerZoom = 1; viewerPanX = 0; viewerPanY = 0; break;
                case 'close':    closeFullscreen(); return;
            }
            applyTransform(canvas);
        });

        overlay.addEventListener('wheel', (e) => {
            e.preventDefault();
            const factor = e.deltaY < 0 ? 1.12 : 1 / 1.12;
            viewerZoom = Math.min(Math.max(viewerZoom * factor, 0.1), 10);
            applyTransform(canvas);
        }, { passive: false });

        overlay.addEventListener('mousedown', (e) => {
            if (e.target.closest('.ait-mermaid-controls')) return;
            isPanning = true;
            panStartX = e.clientX - viewerPanX;
            panStartY = e.clientY - viewerPanY;
            overlay.classList.add('panning');
        });

        const onMouseMove = (e) => {
            if (!isPanning) return;
            viewerPanX = e.clientX - panStartX;
            viewerPanY = e.clientY - panStartY;
            applyTransform(canvas);
        };
        const onMouseUp = () => {
            isPanning = false;
            overlay?.classList.remove('panning');
        };

        document.addEventListener('mousemove', onMouseMove);
        document.addEventListener('mouseup', onMouseUp);

        const onKeyDown = (e) => { if (e.key === 'Escape') closeFullscreen(); };
        document.addEventListener('keydown', onKeyDown);

        overlay.addEventListener('click', (e) => { if (e.target === overlay) closeFullscreen(); });

        overlay._cleanup = () => {
            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);
            document.removeEventListener('keydown', onKeyDown);
        };
    }

    function closeFullscreen() {
        if (!fullscreenOverlay) return;
        const overlay = fullscreenOverlay;
        fullscreenOverlay = null;
        isPanning = false;
        overlay.classList.remove('visible');
        overlay._cleanup?.();
        setTimeout(() => overlay.remove(), 250);
    }

    function applyTransform(canvas) {
        canvas.style.transform = `translate(${viewerPanX}px, ${viewerPanY}px) scale(${viewerZoom})`;
    }

    // ===== 导出 =====

    if (typeof window !== 'undefined') {
        window.MermaidRenderer = {
            detect: detect,
            openFullscreen: openFullscreen,
            STORAGE_KEY: 'mermaidRendererEnabled'
        };
    }

})();

;

// Source: js/quickAsk/quick-ask-manager.js
/**
 * Quick Ask Manager
 * 
 * 引用回复功能
 * 选中文字后显示"引用回复"按钮，点击后将选中文字以引用格式插入输入框
 */

// 位置回退映射：当首选位置空间不够时，切换到对应的备选位置
const POSITION_FALLBACK = {
    topCenter: 'bottomCenter',
    topLeft: 'bottomLeft',
    topRight: 'bottomRight',
    bottomCenter: 'topCenter',
    bottomLeft: 'topLeft',
    bottomRight: 'topRight'
};

class QuickAskManager {
    constructor() {
        this.buttonElement = null;
        this.currentSelection = null;
        this.hideTimer = null;
        this.isEnabled = false;
        this._boundHandlers = null;
        this._position = 'topLeft'; // 默认位置
        this._adapterRegistry = null; // 独立查找对话容器用，延迟初始化
        this._cachedAdapter = null;
        this._inputAdapter = null;
    }
    
    /**
     * 初始化
     */
    async init() {
        if (this.isEnabled) return;

        await TimelineI18n.ready();
        
        await this._loadPosition();
        await this._ensureAdapter();
        this._createButton();
        this._bindEvents();
        this.isEnabled = true;
    }
    
    /**
     * 启用功能
     */
    async enable() {
        if (this.isEnabled) return;

        await TimelineI18n.ready();
        
        await this._loadPosition();
        await this._ensureAdapter();
        if (window.AITContentSession?.active === false) return;
        this._createButton();
        this._bindEvents();
        this.isEnabled = true;
    }
    
    /**
     * 加载平台配置的按钮位置
     */
    async _ensureAdapter() {
        if (!this._cachedAdapter) {
            try {
                if (typeof SiteAdapterRegistry !== 'undefined') {
                    if (!this._adapterRegistry) {
                        this._adapterRegistry = new SiteAdapterRegistry();
                    }
                    this._cachedAdapter = await this._adapterRegistry.detectAdapter();
                }
            } catch (e) {
                this._cachedAdapter = null;
            }
        }

        if (!this._inputAdapter) {
            try {
                this._inputAdapter = (await window.smartEnterAdapterRegistry?.getAdapter?.()) || null;
            } catch (e) {
                this._inputAdapter = null;
            }
        }

        return this._cachedAdapter;
    }

    async _loadPosition() {
        try {
            if (typeof getCurrentPlatform === 'function') {
                const platform = await getCurrentPlatform();
                if (platform?.features?.quickAskPosition) {
                    this._position = platform.features.quickAskPosition;
                }
            }
        } catch (e) {
            // 使用默认位置
        }
    }
    
    /**
     * 禁用功能
     */
    disable() {
        if (!this.isEnabled) return;
        
        this._hideButton();
        this._unbindEvents();
        
        if (this._docMouseUpHandler) {
            document.removeEventListener('mouseup', this._docMouseUpHandler);
            this._docMouseUpHandler = null;
        }
        if (this.buttonElement) {
            this.buttonElement.remove();
            this.buttonElement = null;
        }
        
        this.isEnabled = false;
    }
    
    /**
     * 创建浮动按钮
     */
    _createButton() {
        if (this.buttonElement) return;
        
        const btn = document.createElement('div');
        btn.className = 'ait-quick-ask-btn';
        btn.innerHTML = `
            <button class="ait-quick-ask-action">
                <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2">
                    <path d="M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V21z"/>
                    <path d="M15 21c3 0 7-1 7-8V5c0-1.25-.757-2.017-2-2h-4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2h.75c0 2.25.25 4-2.75 4v3c0 1 0 1 1 1z"/>
                </svg>
                <span>${TimelineI18n.getMessage('quickAsk') || '追问'}</span>
            </button>
        `;
        btn.style.display = 'none';
        
        // ✅ 使用事件委托（解决长时间停留后事件失效问题）
        // 追问按钮：执行引用追问
        window.eventDelegateManager.on('click', '.ait-quick-ask-action', (e) => {
            e.preventDefault();
            e.stopPropagation();
            this._handleQuote();
        });
        window.eventDelegateManager.on('mousedown', '.ait-quick-ask-btn', (e) => {
            e.preventDefault();
        });

        // 标注按钮：集成到追问工具栏
        this._highlightInjected = false;
        window.eventDelegateManager.on('click', '.ait-quick-ask-btn .ait-highlight-action', (e) => {
            e.preventDefault();
            e.stopPropagation();
            if (this._savedRange) {
                const sel = window.getSelection();
                sel.removeAllRanges();
                sel.addRange(this._savedRange);
            }
            if (window.AIChatTimelineHighlight?.onHighlightAction) {
                window.AIChatTimelineHighlight.onHighlightAction();
            }
            this._hideButton();
        });

        // 复制按钮：集成到追问工具栏（仅当选区含高亮 OR 公式时显示）
        window.eventDelegateManager.on('click', '.ait-quick-ask-btn .ait-copy-action', (e) => {
            e.preventDefault();
            e.stopPropagation();
            this._handleCopy();
        });
        
        btn.addEventListener('mousedown', (e) => {
            e.preventDefault();
            this._btnMouseDown = true;
        });
        btn.addEventListener('mouseup', () => { this._btnMouseDown = false; });
        this._docMouseUpHandler = () => { this._btnMouseDown = false; };
        document.addEventListener('mouseup', this._docMouseUpHandler);
        document.body.appendChild(btn);
        this.buttonElement = btn;
    }

    /**
     * 检查并注入/移除标注按钮到追问工具栏
     */
    _syncHighlightButton() {
        if (!this.buttonElement) return;
        const hlManager = window.highlightManager;
        const hlEnabled = hlManager?.isEnabled && !hlManager?.isSelectionInsideHighlight();
        const existing = this.buttonElement.querySelector('.ait-highlight-action');

        if (hlEnabled && !existing) {
            const hlInfo = window.AIChatTimelineHighlight;
            const icon = hlInfo?.getButtonIcon?.() || '';
            const divider = document.createElement('div');
            divider.className = 'ait-toolbar-divider';
            divider.dataset.aitOwner = 'highlight';
            const hlBtn = document.createElement('button');
            hlBtn.className = 'ait-highlight-action';
            hlBtn.innerHTML = `${icon}<span>${TimelineI18n.getMessage('highlightMark') || '标注'}</span>`;
            this.buttonElement.appendChild(divider);
            this.buttonElement.appendChild(hlBtn);
        } else if (!hlEnabled && existing) {
            const divider = this.buttonElement.querySelector('.ait-toolbar-divider[data-ait-owner="highlight"]');
            if (divider) divider.remove();
            existing.remove();
        }
    }

    /**
     * 检查并注入/移除复制按钮到追问工具栏
     * 仅当选区中包含高亮 OR 公式时显示
     */
    _syncCopyButton() {
        if (!this.buttonElement) return;
        const copyApi = window.AIChatTimelineSelectionCopy;
        const need = !!(copyApi && this._savedRange && copyApi.hasRichContent(this._savedRange));
        const existing = this.buttonElement.querySelector('.ait-copy-action');

        if (need && !existing) {
            const divider = document.createElement('div');
            divider.className = 'ait-toolbar-divider';
            divider.dataset.aitOwner = 'copy';
            const btn = document.createElement('button');
            btn.className = 'ait-copy-action';
            btn.innerHTML = `${QuickAskManager._getCopyIcon()}<span>${TimelineI18n.getMessage('mvkxpz') || '复制'}</span>`;
            this.buttonElement.appendChild(divider);
            this.buttonElement.appendChild(btn);
        } else if (!need && existing) {
            const divider = this.buttonElement.querySelector('.ait-toolbar-divider[data-ait-owner="copy"]');
            if (divider) divider.remove();
            existing.remove();
        }
    }

    /**
     * 复制按钮的 SVG 图标
     * 视觉描边范围 y=3→21（与追问/标注图标的 bbox 高度一致），避免视觉上比其他按钮"高一截"
     */
    static _getCopyIcon() {
        return `<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="12" height="12" rx="2"/><path d="M5 14H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h7a2 2 0 0 1 2 2v1"/></svg>`;
    }
    
    /**
     * 绑定事件
     */
    _bindEvents() {
        // 保存事件处理器引用，以便后续移除
        this._boundHandlers = {
            mouseup: (e) => {
                // 如果点击的是按钮，不处理
                if (this.buttonElement?.contains(e.target)) return;
                
                // 延迟检查，确保选区已更新
                setTimeout(() => this._checkSelection(e), 10);
            },
            keyup: (e) => {
                if (e.shiftKey) {
                    setTimeout(() => this._checkSelection(e), 10);
                }
            },
            selectionchange: () => {
                if (this._btnMouseDown) return;
                const selection = window.getSelection();
                const selectedText = selection?.toString().trim();
                
                // 如果选区为空，隐藏按钮
                if (!selectedText || selectedText.length === 0) {
                    this._hideButton();
                }
            },
            scroll: () => this._hideButton()
        };
        
        // 监听鼠标抬起事件
        document.addEventListener('mouseup', this._boundHandlers.mouseup);
        
        // 监听键盘事件（Shift+方向键选择文字）
        document.addEventListener('keyup', this._boundHandlers.keyup);
        
        // 监听选区变化（文字失去选中时隐藏按钮）
        document.addEventListener('selectionchange', this._boundHandlers.selectionchange);
        
        // 滚动时隐藏按钮
        window.addEventListener('scroll', this._boundHandlers.scroll, { passive: true, capture: true });
    }
    
    /**
     * 解绑事件
     */
    _unbindEvents() {
        if (!this._boundHandlers) return;
        
        document.removeEventListener('mouseup', this._boundHandlers.mouseup);
        document.removeEventListener('keyup', this._boundHandlers.keyup);
        document.removeEventListener('selectionchange', this._boundHandlers.selectionchange);
        window.removeEventListener('scroll', this._boundHandlers.scroll, { capture: true });
        
        this._boundHandlers = null;
    }
    
    /**
     * 检查选区
     */
    _checkSelection(e) {
        const selection = window.getSelection();
        const selectedText = selection?.toString().trim();
        
        if (!selectedText || selectedText.length === 0) {
            this._hideButton();
            return;
        }
        
        // 检查选区是否在对话区域内（排除输入框）
        if (!this._isValidSelection(selection)) {
            this._hideButton();
            return;
        }
        
        this.currentSelection = selectedText;
        try { this._savedRange = selection.getRangeAt(0).cloneRange(); } catch { this._savedRange = null; }
        this._showButton(selection);
    }
    
    /**
     * 独立获取对话容器（不依赖时间轴模块）
     * 优先复用 timeline 已定位的容器，否则通过 adapter 独立查找
     * @returns {Element|null}
     */
    _getConversationContainer() {
        const tlContainer = window.timelineManager?.conversationContainer;
        if (tlContainer && tlContainer.isConnected) return tlContainer;

        try {
            const adapter = this._cachedAdapter;
            if (!adapter) return null;

            adapter.prepareTimelineNodes?.({
                force: true,
                reason: 'quick-ask-container'
            });
            const selector = adapter.getUserMessageSelector();
            if (!selector) return null;

            const userTurnElements = Array.from(document.querySelectorAll(selector));
            const firstMsg = userTurnElements[0] || null;
            if (!firstMsg) return null;

            return adapter.findConversationContainer(firstMsg, {
                messageSelector: selector,
                userTurnElements
            });
        } catch (e) {
            return null;
        }
    }

    /**
     * 检查选区是否有效（必须在聊天对话区域内，且不在输入框等区域内）
     */
    _isValidSelection(selection) {
        if (!selection || selection.rangeCount === 0) return false;
        
        const range = selection.getRangeAt(0);
        const container = range.commonAncestorContainer;
        const element = container.nodeType === Node.TEXT_NODE ? container.parentElement : container;
        if (!element) return false;
        
        // 排除输入框
        if (element.closest('textarea, [contenteditable="true"], input')) {
            return false;
        }
        
        // 排除我们自己的 UI 元素
        if (element.closest('.ait-quick-ask-btn, .ait-chat-timeline-wrapper, .ait-panel-modal')) {
            return false;
        }
        
        // 排除代码执行器
        if (element.closest('.runner-panel, .floating-runner-container, .runner-container')) {
            return false;
        }
        
        // 必须在聊天对话区域内（白名单机制）
        const convContainer = this._getConversationContainer();
        if (convContainer && convContainer.isConnected) {
            if (convContainer.contains(element)) return true;
            // Firefox 上 conversationContainer 可能定位偏小，检查是否在同一滚动区域内
            const convParent = convContainer.parentElement;
            if (convParent && convParent.contains(element)) return true;
        }
        
        // 降级：限制在 <main> 区域内（排除侧边栏/导航）
        if (element.closest('main, [role="main"]')) {
            return true;
        }

        // 二次降级：NotebookLM 的对话容器
        if (location.hostname === 'notebooklm.google.com' && element.closest('.chat-panel-content')) {
            return true;
        }
        
        return false;
    }
    
    /**
     * 显示按钮
     */
    _showButton(selection) {
        this._syncHighlightButton();
        this._syncCopyButton();
        if (!this.buttonElement || !selection || selection.rangeCount === 0) return;

        const range = selection.getRangeAt(0);
        const rect = range.getBoundingClientRect();
        
        // 先以不可见状态显示，以便测量真实宽度（按钮数量动态变化）
        this.buttonElement.style.visibility = 'hidden';
        this.buttonElement.style.display = 'flex';
        const measured = this.buttonElement.getBoundingClientRect();
        const btnWidth = Math.max(measured.width || 0, 80);
        const btnHeight = Math.max(measured.height || 0, 28);
        const gap = 8;
        const margin = 10; // 距离屏幕边缘的最小间距
        
        // 计算位置
        let { left, top } = this._calculatePosition(this._position, rect, btnWidth, btnHeight, gap);
        
        // 边界检查和回退
        const needFallback = this._checkBoundary(this._position, top, btnHeight, margin);
        if (needFallback) {
            const fallbackPosition = POSITION_FALLBACK[this._position];
            if (fallbackPosition) {
                const fallbackPos = this._calculatePosition(fallbackPosition, rect, btnWidth, btnHeight, gap);
                left = fallbackPos.left;
                top = fallbackPos.top;
            }
        }
        
        // 水平边界检查（通用）
        if (left < margin) left = margin;
        if (left + btnWidth > window.innerWidth - margin) {
            left = window.innerWidth - btnWidth - margin;
        }
        
        this.buttonElement.style.left = `${left}px`;
        this.buttonElement.style.top = `${top + window.scrollY}px`;
        this.buttonElement.style.visibility = '';
        
        // 触发动画
        requestAnimationFrame(() => {
            this.buttonElement.classList.add('visible');
        });
    }
    
    /**
     * 根据位置类型计算坐标
     * @param {string} position - 位置类型
     * @param {DOMRect} rect - 选区矩形
     * @param {number} btnWidth - 按钮宽度
     * @param {number} btnHeight - 按钮高度
     * @param {number} gap - 间距
     * @returns {{left: number, top: number}}
     */
    _calculatePosition(position, rect, btnWidth, btnHeight, gap) {
        let left, top;
        
        switch (position) {
            case 'topLeft':
                left = rect.left;
                top = rect.top - btnHeight - gap;
                break;
            case 'topCenter':
                left = rect.left + rect.width / 2 - btnWidth / 2;
                top = rect.top - btnHeight - gap;
                break;
            case 'topRight':
                left = rect.right - btnWidth;
                top = rect.top - btnHeight - gap;
                break;
            case 'bottomLeft':
                left = rect.left;
                top = rect.bottom + gap;
                break;
            case 'bottomCenter':
                left = rect.left + rect.width / 2 - btnWidth / 2;
                top = rect.bottom + gap;
                break;
            case 'bottomRight':
                left = rect.right - btnWidth;
                top = rect.bottom + gap;
                break;
            default:
                // 默认 topCenter
                left = rect.left + rect.width / 2 - btnWidth / 2;
                top = rect.top - btnHeight - gap;
        }
        
        return { left, top };
    }
    
    /**
     * 检查是否需要回退到备选位置
     * @param {string} position - 当前位置
     * @param {number} top - 计算出的 top 值
     * @param {number} btnHeight - 按钮高度
     * @param {number} margin - 边距
     * @returns {boolean} - 是否需要回退
     */
    _checkBoundary(position, top, btnHeight, margin) {
        if (position.startsWith('top')) {
            // 上方位置：检查是否超出顶部
            return top < margin;
        } else if (position.startsWith('bottom')) {
            // 下方位置：检查是否超出底部
            return top + btnHeight > window.innerHeight - margin;
        }
        return false;
    }
    
    /**
     * 隐藏按钮
     */
    _hideButton() {
        if (!this.buttonElement) return;
        
        this.buttonElement.classList.remove('visible');
        this.buttonElement.style.display = 'none';
        this.currentSelection = null;
        this._savedRange = null;
    }
    
    /**
     * 处理引用
     */
    _handleQuote() {
        if (!this.currentSelection) {
            this._hideButton();
            return;
        }
        
        // 格式化为引用格式（每行前加 > ），末尾换行由通用方法处理
        // 先处理伪换行：公式渲染（KaTeX/MathJax）会在元素边界插入单个换行符，
        // 需要将其合并为空格，只保留双换行作为真正的段落分隔
        const normalizedText = this.currentSelection
            .replace(/\n{2,}/g, '\n\n')       // 标准化段落分隔为双换行
            .replace(/(?<!\n)\n(?!\n)/g, ' ')  // 单个换行 → 空格（公式渲染产生的伪换行）
            .replace(/ {2,}/g, ' ');           // 合并多余空格
        
        const quotedText = normalizedText
            .split('\n')
            .map(line => line.trim() ? `> ${line.trim()}` : '>')
            .join('\n');
        
        // 插入到输入框
        this._insertToInput(quotedText);
        
        // 隐藏按钮
        this._hideButton();
        
        // 清除选区
        window.getSelection()?.removeAllRanges();
    }

    /**
     * 处理复制：保留高亮样式 + 公式 LaTeX/MathML
     * Toast 走屏幕居中顶部（不传 target）—— 因为按钮点完会立即隐藏，无可锚定元素
     */
    async _handleCopy() {
        const range = this._savedRange;
        const copyApi = window.AIChatTimelineSelectionCopy;

        if (!range || !copyApi) {
            this._hideButton();
            return;
        }

        // 同步发起 clipboard.write 以保留 user gesture
        const promise = copyApi.copyRange(range);

        // 立即隐藏按钮，避免遮挡 toast
        this._hideButton();
        window.getSelection()?.removeAllRanges();

        try {
            const ok = await promise;
            const toast = window.globalToastManager;
            if (ok) {
                toast?.success?.(
                    TimelineI18n.getMessage('xpzmvk') || '已复制',
                    null,
                    { duration: 1600 }
                );
            } else {
                toast?.error?.(
                    TimelineI18n.getMessage('kpzmvx') || '复制失败',
                    null,
                    { duration: 1600 }
                );
            }
        } catch (e) {
            window.globalToastManager?.error?.(
                TimelineI18n.getMessage('kpzmvx') || '复制失败',
                null,
                { duration: 1600 }
            );
        }
    }

    /**
     * 插入文字到输入框
     */
    _insertToInput(text) {
        // 尝试获取输入框
        const inputElement = this._findInputElement();
        
        if (!inputElement) {
            return;
        }
        
        // 滚动到输入框位置
        inputElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
        
        // 聚焦输入框
        inputElement.focus();
        
        if (inputElement.isContentEditable) {
            // contenteditable 处理：使用 insertText 追加，避免替换整个内容导致框架重新格式化
            inputElement.focus();
            
            // 移动光标到末尾 - 需要定位到最深层的文本节点
            const selection = window.getSelection();
            const range = document.createRange();
            
            // 查找最后一个可编辑位置
            let targetNode = inputElement;
            let targetOffset = 0;
            
            // 递归查找最后一个叶子节点
            const findLastLeaf = (node) => {
                if (node.nodeType === Node.TEXT_NODE) {
                    return { node, offset: node.textContent.length };
                }
                if (node.childNodes.length > 0) {
                    // 从后向前找非空节点
                    for (let i = node.childNodes.length - 1; i >= 0; i--) {
                        const child = node.childNodes[i];
                        // 跳过空文本节点
                        if (child.nodeType === Node.TEXT_NODE && child.textContent === '') continue;
                        const result = findLastLeaf(child);
                        if (result) return result;
                    }
                }
                // 如果没有子节点或都是空的，返回当前节点
                return { node, offset: node.childNodes.length };
            };
            
            const lastLeaf = findLastLeaf(inputElement);
            targetNode = lastLeaf.node;
            targetOffset = lastLeaf.offset;
            
            try {
                range.setStart(targetNode, targetOffset);
                range.setEnd(targetNode, targetOffset);
                selection.removeAllRanges();
                selection.addRange(range);
            } catch (e) {
                // 回退到原来的方式
                range.selectNodeContents(inputElement);
                range.collapse(false);
                selection.removeAllRanges();
                selection.addRange(range);
            }
            
            // 配置：空行数（1个空行 = 2个换行符）
            const separatorBlankLines = 1;  // 新旧内容之间的空行数
            const trailingBlankLines = 1;   // 追加内容末尾的空行数
            
            const existingText = inputElement.innerText || '';
            const hasContent = existingText.trim().length > 0;
            
            let separator = '';
            if (hasContent) {
                // 检查末尾已有的空行数（换行符数 - 1 = 空行数）
                const trailingMatch = existingText.match(/\n+$/);
                const existingNewlines = trailingMatch ? trailingMatch[0].length : 0;
                const existingBlankLines = Math.max(0, existingNewlines - 1);
                
                // 计算需要补充多少空行才能达到目标
                const needBlankLines = Math.max(0, separatorBlankLines - existingBlankLines);
                // 空行数 + 1 = 换行符数（至少需要 1 个换行符来换行）
                separator = existingNewlines === 0 
                    ? '\n'.repeat(separatorBlankLines + 1)  // 没有换行，加完整的
                    : '\n'.repeat(needBlankLines);          // 有换行，补差值
            }
            
            const trailing = '\n'.repeat(trailingBlankLines + 1);
            const appendText = separator + text + trailing;
            
            // Slate.js 编辑器：使用粘贴模拟（execCommand 和 DOM 操作都无法同步 Slate 内部状态）
            const isSlateEditor = inputElement.hasAttribute('data-slate-editor');

            if (isSlateEditor) {
                const slateText = hasContent ? ('\n' + text + '\n') : text + '\n';

                const slateRange = document.createRange();
                slateRange.selectNodeContents(inputElement);
                if (hasContent) {
                    slateRange.collapse(false);
                }
                const slateSel = window.getSelection();
                slateSel.removeAllRanges();
                slateSel.addRange(slateRange);

                const dt = new DataTransfer();
                dt.setData('text/plain', slateText);
                inputElement.dispatchEvent(new ClipboardEvent('paste', {
                    clipboardData: dt, bubbles: true, cancelable: true
                }));
            } else {
                // 非 Slate 编辑器：尝试 execCommand，失败则 DOM 操作
                let insertSuccess = false;
                const beforeLength = inputElement.innerText?.length || 0;

                const execResult = document.execCommand('insertText', false, appendText);
                const afterExecLength = inputElement.innerText?.length || 0;

                if (execResult && afterExecLength > beforeLength) {
                    insertSuccess = true;
                }

                if (!insertSuccess) {
                    try {
                        if (targetNode.nodeType === Node.TEXT_NODE) {
                            const originalText = targetNode.textContent;
                            targetNode.textContent = originalText + appendText;
                            insertSuccess = true;
                        } else {
                            const textNode = document.createTextNode(appendText);
                            if (targetNode === inputElement) {
                                inputElement.appendChild(textNode);
                            } else {
                                targetNode.parentNode.insertBefore(textNode, targetNode.nextSibling);
                            }
                            insertSuccess = true;
                        }

                        inputElement.dispatchEvent(new Event('input', { bubbles: true, cancelable: true }));
                        inputElement.dispatchEvent(new Event('change', { bubbles: true, cancelable: true }));
                    } catch (domError) {
                    }
                }
            }
            
            // 延迟设置焦点、光标和滚动
            setTimeout(() => {
                inputElement.focus();
                
                // 设置光标到末尾（contenteditable 需要 selection 才能显示光标）
                const selection = window.getSelection();
                const range = document.createRange();
                range.selectNodeContents(inputElement);
                range.collapse(false);
                selection.removeAllRanges();
                selection.addRange(range);
                
                inputElement.scrollTop = inputElement.scrollHeight;
            }, 100);
        } else {
            // textarea 或 input 处理：内联文本追加逻辑
            const existingText = inputElement.value || '';
            let finalText;
            if (!existingText.trim()) {
                finalText = text + '\n\n';
            } else {
                // 清理末尾换行符，添加1个空行（2个换行符）作为分隔
                const cleanedText = existingText.replace(/\n+$/, '');
                finalText = cleanedText + '\n\n' + text + '\n\n';
            }
            inputElement.value = finalText;
            inputElement.selectionStart = inputElement.selectionEnd = inputElement.value.length;
            
            // 触发 input 事件
            inputElement.dispatchEvent(new Event('input', { bubbles: true }));
            
            // 延迟设置焦点和滚动
            setTimeout(() => {
                inputElement.focus();
                inputElement.selectionStart = inputElement.selectionEnd = inputElement.value.length;
                inputElement.scrollTop = inputElement.scrollHeight;
            }, 50);
        }
    }
    
    /**
     * 查找输入框元素
     */
    _findInputElement() {
        try {
            const adapter = this._inputAdapter;
            const selector = adapter?.getInputSelector?.();
            if (!selector) return null;
            const elements = document.querySelectorAll(selector);
            for (const el of elements) {
                if (el && this._isVisibleElement(el)) {
                    return el;
                }
            }
        } catch (e) {
        }
        return null;
    }
    
    /**
     * 检查元素是否可见
     */
    _isVisibleElement(el) {
        if (!el) return false;
        const style = window.getComputedStyle(el);
        return style.display !== 'none' && 
               style.visibility !== 'hidden' && 
               style.opacity !== '0';
    }
    
    /**
     * 销毁
     */
    destroy() {
        if (this._docMouseUpHandler) {
            document.removeEventListener('mouseup', this._docMouseUpHandler);
            this._docMouseUpHandler = null;
        }
        if (this.buttonElement) {
            this.buttonElement.remove();
            this.buttonElement = null;
        }
        this._adapterRegistry = null;
        this._cachedAdapter = null;
        this._inputAdapter = null;
        this._savedRange = null;
    }
}

// 导出
window.QuickAskManager = QuickAskManager;

