// Source: js/timeline/chat-time-recorder.js
/**
 * ChatTimeRecorder - 提问时间记录器
 * 
 * 完全独立的模块，负责：
 * 1. 监听 ai:stateChange 事件（由 AIStateMonitor 派发）
 * 2. AI 开始生成时：检测新增节点并记录时间
 * 3. AI 生成结束时：兜底渲染时间标签
 * 
 * 与 TimelineManager 解耦，通过 AIStateMonitor 事件驱动
 * 
 * 简化设计：不缓存时间数据，每次直接从 storage 读取
 */
class ChatTimeRecorder {
    constructor() {
        // 状态
        this.enabled = false;
        this._pendingRecord = null;
        this._labelVisible = true;    // 时间标签是否显示（默认显示）
        
        // _renderTimeLabels 并发控制：避免短时间多次调用造成重复 storage 读
        this._renderInFlight = false;
        this._renderQueued = false;
        this._platformFeatures = {};
        this._expandedNodeIds = new Set();
        
        // 事件处理函数（绑定 this）
        this._boundOnAIStateChange = this._onAIStateChange.bind(this);
        this._boundOnTimeLabelClick = this._onTimeLabelClick.bind(this);
        this._boundOnTimeLabelKeydown = this._onTimeLabelKeydown.bind(this);
    }

    /**
     * 获取适配器
     * @returns {Object|null}
     */
    _getAdapter() {
        const adapter = window.timelineManager?.adapter || null;
        if (adapter && typeof adapter.getUserMessageSelector !== 'function') {
            return null;
        }
        return adapter;
    }

    /**
     * 获取用户消息元素列表
     * @param {Object} adapter
     * @returns {NodeList|Array}
     */
    _getUserTurnElements(adapter) {
        if (!adapter) return [];
        adapter.prepareTimelineNodes?.({
            reason: 'chat-time-recorder'
        });
        const selector = adapter.getUserMessageSelector();
        if (!selector) return [];
        const container = window.timelineManager?.conversationContainer || document;
        return container.querySelectorAll(selector);
    }

    /**
     * 获取平台特性
     * @returns {Object}
     */
    _getPlatformFeatures() {
        return this._platformFeatures || {};
    }

    /**
     * 初始化，设置事件监听
     */
    async init() {
        // 预取并缓存当前平台 features（getCurrentPlatform 现为异步）
        this._platformFeatures = (await getCurrentPlatform())?.features || {};

        // 检查当前平台是否启用 chatTimes 功能
        const features = this._getPlatformFeatures();
        this.enabled = features?.chatTimes === true;
        
        if (!this.enabled) {
            return;
        }
        
        const conversationKey = this.getConversationKey();
        if (!conversationKey) return;
        
        try {
            // 读取时间标签显示设置（默认开启）
            const result = await chrome.storage.local.get('chatTimeLabelEnabled');
            this._labelVisible = result.chatTimeLabelEnabled !== false;
            
            // 更新 lastVisit
            await ChatTimeStorageManager.updateLastVisit(conversationKey);
            
            // useStableNodeId=true 的平台，清理临时 ID（如 gemini-0）
            if (features?.useStableNodeId === true) {
                await ChatTimeStorageManager.cleanupTempIds(conversationKey);
            }
        } catch (e) {
            // 上下文失效时静默处理
            if (!e.message?.includes('Extension context invalidated')) {
            }
        }
        
        // 监听 AI 状态变化（由 AIStateMonitor 派发）
        window.addEventListener('ai:stateChange', this._boundOnAIStateChange);
        
        // 初始化期间可能已经进入生成状态，补上首次提问，避免漏掉开始事件。
        if (window.AIStateMonitor?.getInstance().isGenerating) {
            await this._recordNewNodeTime();
        } else {
            this._renderTimeLabels();
        }
    }

    /**
     * 检查功能是否启用
     */
    isEnabled() {
        return this.enabled;
    }

    /**
     * 获取会话标识键
     * @returns {string}
     */
    getConversationKey() {
        const url = location.href;
        return url.replace(/^https?:\/\//, '').split('?')[0].split('#')[0];
    }

    /**
     * AI 状态变化事件处理（由 AIStateMonitor 派发）
     * @private
     */
    async _onAIStateChange(event) {
        if (!this.enabled) return;
        
        if (event.detail?.generating) {
            // AI 开始生成 = 用户刚发送了消息，记录新节点时间
            await this._recordNewNodeTime();
        } else {
            // AI 生成结束，兜底渲染时间标签
            // （生成过程中 DOM 可能重排/重建，导致已渲染的标签丢失）
            this._renderTimeLabels();
        }
    }

    /**
     * 记录新节点的时间（AI 开始生成时调用）
     * @private
     */
    async _recordNewNodeTime() {
        const adapter = this._getAdapter();
        if (!adapter) return;
        
        const userTurnElements = this._getUserTurnElements(adapter);
        if (!userTurnElements || userTurnElements.length === 0) return;
        
        // 检查最后一个节点是否未被记录过
        const lastIndex = userTurnElements.length - 1;
        const lastElement = userTurnElements[lastIndex];
        if (!lastElement) return;
        
        const lastNodeId = adapter.generateTurnId(lastElement, lastIndex);
        
        // 从 storage 读取判断是否已记录
        const conversationKey = this.getConversationKey();
        if (!conversationKey) return;
        
        try {
            const data = await ChatTimeStorageManager.getByConversation(conversationKey);
            const recordedNodes = data.nodes || {};
            
            if (recordedNodes[String(lastNodeId)]) {
                // 节点已被记录过，只渲染
                this._renderTimeLabels();
                return;
            }
        } catch (e) {
            if (!e.message?.includes('Extension context invalidated')) {
            }
            return;
        }
        
        // 判断是否为新对话（只有一个节点）
        const isNewConversation = (userTurnElements.length === 1);
        
        // 检查平台是否使用稳定的节点 ID
        const features = this._getPlatformFeatures();
        const usesStableId = features?.useStableNodeId === true;
        const isTempId = lastNodeId.endsWith(`-${lastIndex}`);
        
        // 直接用当前 ID（可能是临时 ID）记录时间
        const timestamp = Date.now();
        const newNode = { nodeId: lastNodeId, index: lastIndex };
        this._recordNodes([newNode], timestamp, isNewConversation);
        
        if (usesStableId && isTempId) {
            // 使用稳定 ID 的平台，但还没有真正的 ID
            // 保存待处理记录，等待 ID 变化后迁移
            this._pendingRecord = {
                index: lastIndex,
                tempId: lastNodeId
            };
            // 设置轮询检查 ID 变化
            this._pollForRealId(adapter, lastIndex);
        }
    }

    /**
     * 轮询检查真实 ID（用于 Gemini 等平台的延迟 ID 分配）
     * @private
     */
    _pollForRealId(adapter, expectedIndex, retryCount = 0) {
        if (!this._pendingRecord || retryCount > 10) {
            this._pendingRecord = null;
            return;
        }
        
        setTimeout(() => {
            if (!this._pendingRecord) return;
            
            const userTurnElements = this._getUserTurnElements(adapter);
            const lastElement = userTurnElements?.[expectedIndex];
            if (!lastElement) {
                this._pendingRecord = null;
                return;
            }
            
            const nodeId = adapter.generateTurnId(lastElement, expectedIndex);
            const hasRealId = !nodeId.endsWith(`-${expectedIndex}`);
            
            if (hasRealId) {
                // 获取到真正的 ID，迁移数据
                const pending = this._pendingRecord;
                this._migrateNodeId(pending.tempId, nodeId);
                this._pendingRecord = null;
            } else {
                // 继续轮询
                this._pollForRealId(adapter, expectedIndex, retryCount + 1);
            }
        }, 500);
    }
    
    /**
     * 迁移节点 ID（从临时 ID 迁移到真实 ID）
     * @private
     */
    async _migrateNodeId(tempId, realId) {
        const conversationKey = this.getConversationKey();
        if (!conversationKey) return;
        
        try {
            const migrated = await ChatTimeStorageManager.migrateNodeId(conversationKey, tempId, realId);
            if (migrated) {
                // 重新渲染时间标签
                this._renderTimeLabels();
            }
        } catch (e) {
            if (!e.message?.includes('Extension context invalidated')) {
            }
        }
    }

    /**
     * 记录节点时间
     * @private
     */
    async _recordNodes(newNodes, customTimestamp, isNewConversation = false) {
        if (!this.enabled || !newNodes || newNodes.length === 0) return;
        
        const conversationKey = this.getConversationKey();
        if (!conversationKey) return;
        
        try {
            // 新对话时，先设置 createTime
            if (isNewConversation) {
                await ChatTimeStorageManager.setCreateTime(conversationKey);
            }
            
            const timestamp = customTimestamp || Date.now();
            const nodesToRecord = newNodes.map(n => ({ nodeId: String(n.nodeId), timestamp }));
            
            if (nodesToRecord.length === 0) return;
            
            // batchSetNodeTimes 内部会跳过已存在的节点
            const addedCount = await ChatTimeStorageManager.batchSetNodeTimes(conversationKey, nodesToRecord);
            if (addedCount > 0) {
                // 立即渲染时间标签
                this._renderTimeLabels();
            }
        } catch (e) {
            if (!e.message?.includes('Extension context invalidated')) {
            }
        }
    }

    /**
     * 渲染所有节点的时间标签
     * 
     * 使用空的 .ait-chat-time-label 节点 + CSS ::before 伪元素方案：
     * - 空节点不会把时间混入提问文本，同时可提供独立点击区域
     * - 通过 CSS 变量传递位置配置
     *
     * 并发控制：MutationObserver 抖动可能在短时间内多次触发本方法，
     * 通过 in-flight + 单 trailing 回放，把 N 次并发调用合并为最多 2 次 storage 读。
     * @private
     */
    async _renderTimeLabels() {
        if (!this.enabled || !this._labelVisible) return;
        
        // 已有渲染在执行 → 标记为「需要再跑一次」，让那个执行结束后回放
        if (this._renderInFlight) {
            this._renderQueued = true;
            return;
        }
        
        this._renderInFlight = true;
        try {
            do {
                this._renderQueued = false;
                await this._doRenderTimeLabels();
            } while (this._renderQueued);
        } finally {
            this._renderInFlight = false;
        }
    }
    
    /**
     * 实际的时间标签渲染逻辑（被 _renderTimeLabels 通过去重包装调用）
     * @private
     */
    async _doRenderTimeLabels() {
        if (!this.enabled || !this._labelVisible) return;
        
        const adapter = this._getAdapter();
        if (!adapter) return;
        
        const userTurnElements = this._getUserTurnElements(adapter);
        if (!userTurnElements || userTurnElements.length === 0) return;
        
        // 从 storage 读取时间数据
        const conversationKey = this.getConversationKey();
        if (!conversationKey) return;
        
        let nodeTimestamps = {};
        try {
            const data = await ChatTimeStorageManager.getByConversation(conversationKey);
            nodeTimestamps = data.nodes || {};
        } catch (e) {
            if (!e.message?.includes('Extension context invalidated')) {
            }
            return;
        }
        
        // 获取平台自定义位置（所有节点位置一致，只需读取一次）
        const position = adapter.getTimeLabelPosition();
        
        userTurnElements.forEach((element, index) => {
            const nodeId = adapter.generateTurnId(element, index);
            const timestamp = nodeTimestamps[String(nodeId)];
            
            if (!timestamp) return;
            
            const nodeIdKey = String(nodeId);
            const formattedTime = this.formatNodeTime(timestamp);
            const toggleable = this.isNodeTimeToggleable(timestamp);
            const expanded = toggleable && this._expandedNodeIds.has(nodeIdKey);
            const displayTime = expanded ? this.formatFullNodeTime(timestamp) : formattedTime;
            try {
                const marker = window.timelineManager?.markerMap?.get?.(nodeIdKey);
                if (marker) marker.timeLabel = formattedTime;
            } catch {}
            
            // 获取时间标签的实际渲染目标元素
            const target = adapter.getTimeLabelTarget(element);
            if (!target) return;

            let timeLabel = target.querySelector('.ait-chat-time-label');
            const labelIsCurrent = timeLabel
                && timeLabel.dataset.aitNodeId === nodeIdKey
                && timeLabel.dataset.aitTimestamp === String(timestamp)
                && timeLabel.getAttribute('data-ait-time') === displayTime
                && timeLabel.classList.contains('ait-time-toggleable') === toggleable
                && (!toggleable || timeLabel.getAttribute('aria-pressed') === String(expanded));

            // 避免 MutationObserver 触发重渲染时反复写入相同属性。
            if (labelIsCurrent && !target.hasAttribute('data-ait-time')) return;
            
            if (position.paddingTop) {
                target.style.paddingTop = position.paddingTop;
            }
            
            // 确保 target 有相对定位（::before 相对于 target 定位）
            const computedStyle = window.getComputedStyle(target);
            if (computedStyle.position === 'static') {
                target.style.position = 'relative';
            }
            
            // 通过 CSS 变量传递位置配置
            if (position.top) target.style.setProperty('--ait-time-top', position.top);
            if (position.right) target.style.setProperty('--ait-time-right', position.right);
            if (position.left) target.style.setProperty('--ait-time-left', position.left);
            if (position.bottom) target.style.setProperty('--ait-time-bottom', position.bottom);

            // 兼容扩展热重载前已经挂在 target 上的旧标签。
            target.removeAttribute('data-ait-time');

            if (!timeLabel) {
                timeLabel = document.createElement('span');
                timeLabel.className = 'ait-chat-time-label';
                timeLabel.addEventListener('click', this._boundOnTimeLabelClick);
                timeLabel.addEventListener('keydown', this._boundOnTimeLabelKeydown);
                target.appendChild(timeLabel);
            }

            timeLabel.dataset.aitNodeId = nodeIdKey;
            timeLabel.dataset.aitTimestamp = String(timestamp);
            timeLabel.setAttribute('data-ait-time', displayTime);
            timeLabel.setAttribute('aria-label', displayTime);
            timeLabel.classList.toggle('ait-time-toggleable', toggleable);

            if (toggleable) {
                timeLabel.setAttribute('role', 'button');
                timeLabel.tabIndex = 0;
                timeLabel.setAttribute('aria-pressed', String(expanded));
            } else {
                timeLabel.removeAttribute('role');
                timeLabel.removeAttribute('tabindex');
                timeLabel.removeAttribute('aria-pressed');
            }
        });
    }

    /**
     * 只有默认格式不显示年份（本年）的时间才支持切换。
     * @param {number} timestamp
     * @returns {boolean}
     */
    isNodeTimeToggleable(timestamp) {
        if (!timestamp) return false;
        const date = new Date(timestamp);
        if (Number.isNaN(date.getTime())) return false;
        return date.getFullYear() === new Date().getFullYear();
    }

    /**
     * 切换当前时间标签的简略/完整格式。
     * @param {HTMLElement} timeLabel
     */
    _toggleTimeLabel(timeLabel) {
        if (!timeLabel?.classList.contains('ait-time-toggleable')) return;

        const nodeId = timeLabel.dataset.aitNodeId;
        const timestamp = Number(timeLabel.dataset.aitTimestamp);
        if (!nodeId || !this.isNodeTimeToggleable(timestamp)) return;

        const expanded = !this._expandedNodeIds.has(nodeId);
        if (expanded) {
            this._expandedNodeIds.add(nodeId);
        } else {
            this._expandedNodeIds.delete(nodeId);
        }

        const displayTime = expanded
            ? this.formatFullNodeTime(timestamp)
            : this.formatNodeTime(timestamp);
        timeLabel.setAttribute('data-ait-time', displayTime);
        timeLabel.setAttribute('aria-label', displayTime);
        timeLabel.setAttribute('aria-pressed', String(expanded));
    }

    _onTimeLabelClick(event) {
        event.preventDefault();
        event.stopPropagation();
        this._toggleTimeLabel(event.currentTarget);
    }

    _onTimeLabelKeydown(event) {
        if (event.key !== 'Enter' && event.key !== ' ') return;
        event.preventDefault();
        event.stopPropagation();
        this._toggleTimeLabel(event.currentTarget);
    }

    /**
     * 格式化时间显示
     * @param {number} timestamp
     * @returns {string}
     */
    formatNodeTime(timestamp) {
        if (!timestamp) return '';
        const date = new Date(timestamp);
        const now = new Date();
        const isToday = date.toDateString() === now.toDateString();
        const isThisYear = date.getFullYear() === now.getFullYear();
        
        if (isToday) {
            return date.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' });
        }
        
        if (isThisYear) {
            return date.toLocaleDateString('zh-CN', { 
                month: 'short', 
                day: 'numeric', 
                hour: '2-digit', 
                minute: '2-digit' 
            });
        }
        
        return date.toLocaleDateString('zh-CN', { 
            year: 'numeric',
            month: 'short', 
            day: 'numeric', 
            hour: '2-digit', 
            minute: '2-digit' 
        });
    }

    /**
     * 格式化完整的年月日时分。
     * @param {number} timestamp
     * @returns {string}
     */
    formatFullNodeTime(timestamp) {
        if (!timestamp) return '';
        const date = new Date(timestamp);
        if (Number.isNaN(date.getTime())) return '';
        const pad = value => String(value).padStart(2, '0');
        return `${date.getFullYear()}年${pad(date.getMonth() + 1)}月${pad(date.getDate())}日 ${pad(date.getHours())}:${pad(date.getMinutes())}`;
    }

    /**
     * 重置状态（会话切换时调用）
     */
    async reset() {
        this._pendingRecord = null;
        this._expandedNodeIds.clear();
        
        // 更新新会话的 lastVisit
        if (this.enabled) {
            const conversationKey = this.getConversationKey();
            if (conversationKey) {
                try {
                    await ChatTimeStorageManager.updateLastVisit(conversationKey);
                } catch (e) {
                    if (!e.message?.includes('Extension context invalidated')) {
                    }
                }
            }
        }
    }

    /**
     * 更新时间标签显示状态
     * @param {boolean} visible - 是否显示时间标签
     */
    updateLabelVisibility(visible) {
        this._labelVisible = visible;
        
        if (visible) {
            // 显示：重新渲染时间标签
            this._renderTimeLabels();
        } else {
            // 隐藏：移除所有时间标签。
            this._removeTimeLabels();
            try {
                window.timelineManager?.markers?.forEach(marker => {
                    marker.timeLabel = null;
                });
            } catch {}
        }
    }

    /**
     * 销毁，清理状态和事件监听
     */
    destroy() {
        // 移除事件监听
        window.removeEventListener('ai:stateChange', this._boundOnAIStateChange);
        this._removeTimeLabels();
        
        // 清理状态
        this._pendingRecord = null;
        this._expandedNodeIds.clear();
        this.enabled = false;
    }

    _removeTimeLabels() {
        document.querySelectorAll('.ait-chat-time-label').forEach(el => el.remove());
        document.querySelectorAll('[data-ait-time]').forEach(el => {
            el.removeAttribute('data-ait-time');
        });
    }
}

// 创建全局单例
window.chatTimeRecorder = null;

/**
 * 初始化 ChatTimeRecorder（由 TimelineManager 调用）
 */
function initChatTimeRecorder() {
    if (window.chatTimeRecorder) {
        window.chatTimeRecorder.destroy();
    }
    window.chatTimeRecorder = new ChatTimeRecorder();
    window.chatTimeRecorder.init();
}

/**
 * 销毁 ChatTimeRecorder（由 TimelineManager 调用）
 */
function destroyChatTimeRecorder() {
    if (window.chatTimeRecorder) {
        window.chatTimeRecorder.destroy();
        window.chatTimeRecorder = null;
    }
}

/**
 * 重置 ChatTimeRecorder（会话切换时调用）
 */
function resetChatTimeRecorder() {
    if (window.chatTimeRecorder) {
        window.chatTimeRecorder.reset();
    }
}

// 导出到全局
window.ChatTimeRecorder = ChatTimeRecorder;
window.initChatTimeRecorder = initChatTimeRecorder;
window.destroyChatTimeRecorder = destroyChatTimeRecorder;
window.resetChatTimeRecorder = resetChatTimeRecorder;

;

// Source: js/timeline/notepad/notepad-manager.js
/**
 * NotepadManager - 闪记管理器（多笔记模式）
 * 全局共享、持久化到 chrome.storage，纯文本
 * 拖拽 / 调整大小交互逻辑与 FloatingRunnerContainer 保持一致
 */
class NotepadManager {
    constructor() {
        this.panel = null;
        this.textarea = null;
        this.preview = null;
        this.listContainer = null;
        this.listBtn = null;
        this.addBtn = null;
        this.isOpen = false;
        this.saveTimeout = null;

        this.activeNoteId = null;
        this.currentView = 'edit'; // 'edit' | 'list'

        // 笔记数组 [{id, content, updatedAt}]
        // 文件夹和标题信息存在 chatTimelineStars 中，key 格式：chatTimelineStar:notepad:{noteId}
        this.notes = [];

        // 文件夹管理
        this.folderManager = null;
        this.locationEl = null;
        this.locationTextEl = null;

        // 存储 key
        this.NOTES_KEY = 'aitNotepadNotes';
        this.STATE_KEY = 'aitNotepadState';

        // 兼容旧版单笔记数据迁移
        this.OLD_STORAGE_KEY = 'aitNotepadContent';

        // 默认尺寸
        this.DEFAULT_WIDTH = 260;
        this.DEFAULT_HEIGHT = 370;
        this.MIN_WIDTH = 240;
        this.MIN_HEIGHT = 280;

        // 位置（右下角锚定：距视口右边/底部的距离）& 大小
        this.position = { right: null, bottom: null };
        this.size = { width: this.DEFAULT_WIDTH, height: this.DEFAULT_HEIGHT };

        // 拖动状态
        this.isDragging = false;
        this.dragOffset = { x: 0, y: 0 };

        // 调整大小状态
        this.isResizing = false;
        this.resizeDirection = null;
        this.resizeStart = null;

        this._onMouseMove = null;
        this._onMouseUp = null;
        this._onFocusCheck = null;
        this._onStorageChange = null;
        this._onWindowResize = null;
        this._isSaving = false;

        this.loadState();
    }

    async init() {
        await TimelineI18n.ready();
        if (window.AITContentSession?.active === false) return;

        try {
            this.folderManager = new FolderManager(StorageAdapter);
        } catch (e) {}
        this.createPanel();
        await this.loadNotes();
        if (window.AITContentSession?.active === false) return;
        if (!this.notes.length) {
            this.createNote();
        } else {
            this.openNote(this.notes[this.notes.length - 1].id);
        }
        this.bindEvents();
    }

    // ─── DOM ─────────────────────────────────────────────────────────────────

    createPanel() {
        if (this.panel) return;

        const panel = document.createElement('div');
        panel.className = 'ait-notepad-panel';
        // 关闭状态不依赖样式表或透明度，避免面板文字混入网页全选复制。
        panel.hidden = true;

        panel.innerHTML = `
            <div class="ait-notepad-header">
                <span class="ait-notepad-title">
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none"
                        stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"
                        width="16" height="16">
                        <path d="M17 3a2.85 2.85 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/>
                        <path d="m15 5 4 4"/>
                    </svg>
                    ${TimelineI18n.getMessage('notepadTitle') || '闪记'}
                </span>
                <div class="ait-notepad-header-right">
                    <button class="ait-notepad-list-btn" aria-label="${TimelineI18n.getMessage('notepadAllNotes') || '全部笔记'}">
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none"
                            stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"
                            width="16" height="16">
                            <line x1="8" y1="6" x2="21" y2="6"/>
                            <line x1="8" y1="12" x2="21" y2="12"/>
                            <line x1="8" y1="18" x2="21" y2="18"/>
                            <line x1="3" y1="6" x2="3.01" y2="6"/>
                            <line x1="3" y1="12" x2="3.01" y2="12"/>
                            <line x1="3" y1="18" x2="3.01" y2="18"/>
                        </svg>
                    </button>
                    <button class="ait-notepad-add-btn" aria-label="${TimelineI18n.getMessage('notepadNewNote') || '新建笔记'}">
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none"
                            stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"
                            width="16" height="16">
                            <line x1="12" y1="5" x2="12" y2="19"/>
                            <line x1="5" y1="12" x2="19" y2="12"/>
                        </svg>
                    </button>
                    <button class="ait-notepad-close-btn" aria-label="${TimelineI18n.getMessage('notepadClose') || '关闭'}">
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none"
                            stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"
                            width="14" height="14">
                            <line x1="18" y1="6" x2="6" y2="18"/>
                            <line x1="6" y1="6" x2="18" y2="18"/>
                        </svg>
                    </button>
                </div>
            </div>
            <div class="ait-notepad-body">
                <div class="ait-notepad-list"></div>
                <textarea class="ait-notepad-editor" placeholder="${TimelineI18n.getMessage('notepadPlaceholder') || '想到什么就写什么，无需排版…'}"></textarea>
                <div class="ait-notepad-preview" aria-hidden="true" hidden></div>
            </div>
            <div class="ait-notepad-footer">
                <div class="ait-notepad-location">
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none"
                        stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"
                        width="13" height="13">
                        <path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/>
                    </svg>
                    <span class="ait-notepad-location-text ait-notepad-location-empty">${TimelineI18n.getMessage('notepadSaveToFolder') || '保存到文件夹'}</span>
                </div>
            </div>
            <div class="ait-notepad-resize-handle" data-direction="se"></div>
            <div class="ait-notepad-resize-handle" data-direction="sw"></div>
            <div class="ait-notepad-resize-handle" data-direction="ne"></div>
            <div class="ait-notepad-resize-handle" data-direction="nw"></div>
            <div class="ait-notepad-resize-handle" data-direction="e"></div>
            <div class="ait-notepad-resize-handle" data-direction="w"></div>
            <div class="ait-notepad-resize-handle" data-direction="n"></div>
            <div class="ait-notepad-resize-handle" data-direction="s"></div>
        `;

        document.body.appendChild(panel);
        this.panel = panel;
        this.textarea = panel.querySelector('.ait-notepad-editor');
        this.preview = panel.querySelector('.ait-notepad-preview');
        this.listContainer = panel.querySelector('.ait-notepad-list');
        this.listBtn = panel.querySelector('.ait-notepad-list-btn');
        this.addBtn = panel.querySelector('.ait-notepad-add-btn');
        this.locationEl = panel.querySelector('.ait-notepad-location');
        this.locationTextEl = panel.querySelector('.ait-notepad-location-text');
        this.footerEl = panel.querySelector('.ait-notepad-footer');
    }

    // ─── Events ───────────────────────────────────────────────────────────────

    bindEvents() {
        const header = this.panel.querySelector('.ait-notepad-header');
        header.addEventListener('mousedown', (e) => {
            if (e.target.closest('button')) return;
            this.startDrag(e);
        });

        this.panel.querySelectorAll('.ait-notepad-resize-handle').forEach(handle => {
            handle.addEventListener('mousedown', (e) => {
                this.startResize(e, handle.dataset.direction);
            });
        });

        this._bindHeaderButtonTooltip(
            this.listBtn,
            'notepad-list',
            TimelineI18n.getMessage('notepadAllNotes') || '全部笔记'
        );
        this._bindHeaderButtonTooltip(
            this.addBtn,
            'notepad-add',
            TimelineI18n.getMessage('notepadNewNote') || '新建笔记'
        );
        this._bindHeaderButtonTooltip(
            this.panel.querySelector('.ait-notepad-close-btn'),
            'notepad-close',
            TimelineI18n.getMessage('notepadClose') || '关闭'
        );

        this._onMouseMove = (e) => this.onMouseMove(e);
        this._onMouseUp = () => this.onMouseUp();
        document.addEventListener('mousemove', this._onMouseMove);
        document.addEventListener('mouseup', this._onMouseUp);

        this.textarea.addEventListener('input', () => this.scheduleSave());
        window.addEventListener('blur', () => {
            // Leaving the tab to reload the extension can invalidate its storage API.
            if (this.isOpen) this._flushCurrentNote();
        });

        this.textarea.addEventListener('keydown', (e) => {
            if (e.key === 'Tab') {
                e.preventDefault();
                const start = this.textarea.selectionStart;
                const end = this.textarea.selectionEnd;
                const val = this.textarea.value;
                this.textarea.value = val.substring(0, start) + '    ' + val.substring(end);
                this.textarea.selectionStart = this.textarea.selectionEnd = start + 4;
                this.scheduleSave();
            }
        });

        this.panel.querySelector('.ait-notepad-close-btn').addEventListener('click', (e) => {
            e.stopPropagation();
            this.close();
        });

        this.listBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            this.showListView();
        });

        this.addBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            this.createNote();
        });

        this.locationEl.addEventListener('click', (e) => {
            e.stopPropagation();
            this._showFolderPicker();
        });

        this.listContainer.addEventListener('click', (e) => {
            const deleteBtn = e.target.closest('.ait-notepad-item-delete');
            if (deleteBtn) {
                e.stopPropagation();
                const id = deleteBtn.closest('.ait-notepad-item').dataset.id;
                this.deleteNote(id);
                return;
            }
            const item = e.target.closest('.ait-notepad-item');
            if (item) {
                this.openNote(item.dataset.id);
            }
        });

        this._onFocusCheck = (e) => {
            if (!this.isOpen || !this.panel) return;
            if (e.target.closest('.ait-notepad-btn')) return;
            const rect = this.panel.getBoundingClientRect();
            const inside = e.clientX >= rect.left && e.clientX <= rect.right
                        && e.clientY >= rect.top && e.clientY <= rect.bottom;
            if (inside) {
                this._setFocused(true);
            } else {
                this._setFocused(false);
            }
        };
        document.addEventListener('mousedown', this._onFocusCheck, true);

        this._onStorageChange = (changes, area) => {
            if (area !== 'local') return;

            if (changes[this.NOTES_KEY] && !this._isSaving) {
                const newNotes = changes[this.NOTES_KEY].newValue;
                if (!newNotes || !newNotes.length) return;

                this.notes = newNotes;
                if (!this.isOpen) return;

                if (this.currentView === 'list') {
                    this._renderList();
                } else if (this.activeNoteId) {
                    const note = this._getNoteById(this.activeNoteId);
                    if (note && note.content !== this.textarea.value) {
                        this.textarea.value = note.content;
                        this._syncPreview();
                        const len = note.content.length;
                        this.textarea.selectionStart = this.textarea.selectionEnd = len;
                    }
                }
            }
        };
        chrome.storage.onChanged.addListener(this._onStorageChange);

        this._onWindowResize = () => {
            if (!this.isOpen || !this.panel) return;
            this.applyState();
        };
        window.addEventListener('resize', this._onWindowResize);
    }

    _bindHeaderButtonTooltip(button, id, text) {
        if (!button) return;

        button.addEventListener('mouseenter', () => {
            window.globalTooltipManager?.show(
                id,
                'button',
                button,
                text,
                { style: 'mini', placement: 'top' }
            );
        });
        button.addEventListener('mouseleave', () => {
            window.globalTooltipManager?.hide();
        });
    }

    // ─── 视图切换 / 列表渲染 ──────────────────────────────────────────────────

    async renderCurrentView() {
        this._updateListBtnVisibility();
        if (this.currentView === 'list') {
            await this.showListView();
        } else {
            this._showEditView();
        }
    }

    async showListView() {
        this._flushCurrentNote();
        await this.loadNotes();
        this._updateListBtnVisibility();

        this.currentView = 'list';
        this.activeNoteId = null;
        this.textarea.style.display = 'none';
        if (this.preview) this.preview.hidden = true;
        this.listContainer.style.display = 'flex';
        this.listContainer.style.flexDirection = 'column';
        if (this.footerEl) this.footerEl.style.display = 'none';
        this._renderList();
    }

    _showEditView() {
        this.currentView = 'edit';
        this.listContainer.style.display = 'none';
        this.textarea.style.display = '';
        if (this.preview) this.preview.hidden = false;
        this._syncPreview();
        if (this.footerEl) this.footerEl.style.display = '';
        this._updateListBtnVisibility();
    }

    _updateListBtnVisibility() {
        if (this.listBtn) {
            this.listBtn.style.display = this.notes.length >= 1 ? 'flex' : 'none';
        }
    }

    async _renderList() {
        if (!this.notes.length) {
            this.listContainer.innerHTML = '';
            return;
        }

        const sorted = [...this.notes].sort((a, b) => b.updatedAt - a.updatedAt);

        const allStars = await StarStorageManager.getAll();
        const noteStarMap = {};
        for (const star of allStars) {
            if (star.key?.includes(':notepad:') && star.noteId) {
                noteStarMap[star.noteId] = star;
            }
        }

        const folderPaths = {};
        if (this.folderManager) {
            for (const note of sorted) {
                const star = noteStarMap[note.id];
                if (star?.folderId && !(star.folderId in folderPaths)) {
                    folderPaths[star.folderId] = await this.folderManager.getFolderPath(star.folderId) || '';
                }
            }
        }

        this.listContainer.innerHTML = sorted.map(note => {
            const star = noteStarMap[note.id];
            const contentTitle = this._extractTitle(note.content) || (TimelineI18n.getMessage('notepadUntitled') || '无标题');
            const folderPath = star?.folderId ? (folderPaths[star.folderId] || '') : '';
            const starTitle = star?.question || '';
            const time = this._formatTime(note.updatedAt);

            let folderLine = '';
            if (folderPath) {
                folderLine = `<div class="ait-notepad-item-folder-line"><span class="ait-notepad-item-folder">${this._escapeHtml(folderPath)}</span>${starTitle ? `<span class="ait-notepad-item-star-title">${this._escapeHtml(starTitle)}</span>` : ''}</div>`;
            }

            return `
                <div class="ait-notepad-item" data-id="${note.id}">
                    <div class="ait-notepad-item-content">
                        <div class="ait-notepad-item-title">${this._escapeHtml(contentTitle)}</div>
                        ${folderLine}
                        <div class="ait-notepad-item-meta">
                            <span class="ait-notepad-item-time">${time}</span>
                        </div>
                    </div>
                    <button class="ait-notepad-item-delete" title="${TimelineI18n.getMessage('mzxvkp') || '删除'}">
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none"
                            stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"
                            width="14" height="14">
                            <polyline points="3 6 5 6 21 6"/>
                            <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/>
                        </svg>
                    </button>
                </div>`;
        }).join('');
    }

    // ─── 笔记 CRUD ──────────────────────────────────────────────────────────

    createNote() {
        if (this.activeNoteId) {
            const current = this._getNoteById(this.activeNoteId);
            if (current && !current.content.trim()) return;
        }

        const note = {
            id: Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
            content: '',
            updatedAt: Date.now()
        };
        this.notes.push(note);
        this.saveNotes();
        this.openNote(note.id);
    }

    openNote(id) {
        this._flushCurrentNote();

        const note = this._getNoteById(id);
        if (!note) return;

        this.activeNoteId = id;
        this.textarea.value = note.content;
        this._showEditView();
        this._updateLocationDisplay();

        requestAnimationFrame(() => {
            if (!this.panel?.classList.contains('ait-notepad-focused')) return;
            this.textarea.focus();
            const len = this.textarea.value.length;
            this.textarea.setSelectionRange(len, len);
        });
    }

    async deleteNote(id) {
        const confirmed = await window.globalPopconfirmManager?.show({
            title: TimelineI18n.getMessage('notepadConfirmDeleteTitle') || '确认删除',
            content: TimelineI18n.getMessage('notepadConfirmDeleteContent') || '删除后将无法恢复，确定要继续吗？',
            confirmText: TimelineI18n.getMessage('mzxvkp') || '删除',
            cancelText: TimelineI18n.getMessage('commonCancel') || '取消'
        });
        if (!confirmed) return;

        this.notes = this.notes.filter(n => n.id !== id);
        this.saveNotes();

        const starKey = this._getNoteStarKey(id);
        StarStorageManager.remove(starKey).catch(() => {});

        if (this.activeNoteId === id) {
            this.activeNoteId = null;
        }
        this._updateListBtnVisibility();

        if (!this.notes.length) {
            this.createNote();
        } else {
            this._renderList();
        }

        if (this.isOpen && this.panel) {
            this._setFocused(true);
        }
    }

    // ─── 文本工具 ────────────────────────────────────────────────────────────

    _extractTitle(content) {
        if (!content) return '';
        const firstLine = content.split('\n')[0].trim();
        return firstLine.length > 40 ? firstLine.slice(0, 40) + '…' : firstLine;
    }

    _extractPreview(content) {
        if (!content) return '';
        const lines = content.split('\n').filter(l => l.trim());
        const secondLine = lines.length > 1 ? lines[1].trim() : '';
        return secondLine.length > 50 ? secondLine.slice(0, 50) + '…' : secondLine;
    }

    _formatTime(ts) {
        if (!ts) return '';
        const d = new Date(ts);
        const now = new Date();
        const pad = n => String(n).padStart(2, '0');

        if (d.toDateString() === now.toDateString()) {
            return `${pad(d.getHours())}:${pad(d.getMinutes())}`;
        }

        const yesterday = new Date(now);
        yesterday.setDate(yesterday.getDate() - 1);
        if (d.toDateString() === yesterday.toDateString()) {
            return `${TimelineI18n.getMessage('notepadYesterday') || '昨天'} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
        }

        if (d.getFullYear() === now.getFullYear()) {
            return `${d.getMonth() + 1}/${d.getDate()} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
        }

        return `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()}`;
    }

    _escapeHtml(str) {
        return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }

    _flushCurrentNote() {
        if (!this.activeNoteId || !this.textarea) return;
        const note = this._getNoteById(this.activeNoteId);
        if (!note) return;

        const newContent = this.textarea.value;
        if (note.content !== newContent) {
            note.content = newContent;
            note.updatedAt = Date.now();
            this.saveNotes();
            this._syncPreview();
        }
    }

    _getNoteById(id) {
        return this.notes.find(n => n.id === id) || null;
    }

    // ─── 文件夹位置 ────────────────────────────────────────────────────────────

    async _updateLocationDisplay() {
        if (!this.locationTextEl || !this.activeNoteId) return;

        const emptyText = TimelineI18n.getMessage('notepadSaveToFolder') || '保存到文件夹';
        const starRecord = await StarStorageManager.findByKey(this._getNoteStarKey(this.activeNoteId));

        if (!starRecord?.folderId || !this.folderManager) {
            this.locationTextEl.textContent = emptyText;
            this.locationTextEl.classList.add('ait-notepad-location-empty');
            this.locationTextEl.innerHTML = emptyText;
            return;
        }
        try {
            const path = await this.folderManager.getFolderPath(starRecord.folderId);
            if (path) {
                const title = starRecord.question || '';
                const folderHtml = `<span class="ait-notepad-loc-folder">${this._escapeHtml(path)}</span>`;
                const titleHtml = title ? `<span class="ait-notepad-loc-title">${this._escapeHtml(title)}</span>` : '';
                this.locationTextEl.innerHTML = folderHtml + titleHtml;
                this.locationTextEl.classList.remove('ait-notepad-location-empty');
            } else {
                this.locationTextEl.textContent = emptyText;
                this.locationTextEl.classList.add('ait-notepad-location-empty');
            }
        } catch (e) {
            this.locationTextEl.textContent = emptyText;
            this.locationTextEl.classList.add('ait-notepad-location-empty');
        }
    }

    _getNoteStarKey(noteId) {
        return `chatTimelineStar:notepad:${noteId}`;
    }

    async _showFolderPicker() {
        if (!this.activeNoteId || !this.folderManager || !window.starInputModal) return;

        const note = this._getNoteById(this.activeNoteId);
        if (!note) return;

        const starKey = this._getNoteStarKey(this.activeNoteId);
        const existingStar = await StarStorageManager.findByKey(starKey);

        const defaultTitle = existingStar?.question || this._extractTitle(note.content) || '';

        const result = await window.starInputModal.show({
            title: TimelineI18n.getMessage('zmvkpx') || '收藏到文件夹',
            defaultValue: defaultTitle,
            folderManager: this.folderManager,
            defaultFolderId: existingStar?.folderId || null
        });

        if (!result) {
            if (this.isOpen && this.panel) this._setFocused(true);
            return;
        }

        await StarStorageManager.add({
            key: starKey,
            noteId: this.activeNoteId,
            question: result.value?.trim() || defaultTitle,
            timestamp: Date.now(),
            folderId: result.folderId || null
        });

        this._updateLocationDisplay();
        if (this.isOpen && this.panel) this._setFocused(true);
    }

    // ─── Storage ──────────────────────────────────────────────────────────────

    scheduleSave() {
        clearTimeout(this.saveTimeout);
        this.saveTimeout = setTimeout(() => {
            this._flushCurrentNote();
        }, 600);
    }

    saveNotes() {
        this._isSaving = true;
        try {
            chrome.storage.local.set({ [this.NOTES_KEY]: this.notes }, () => {
                this._isSaving = false;
                if (chrome.runtime.lastError) {}
            });
        } catch (e) {
            this._isSaving = false;
        }
        setTimeout(() => { this._isSaving = false; }, 2000);
    }

    async loadNotes() {
        try {
            const result = await chrome.storage.local.get([this.NOTES_KEY, this.OLD_STORAGE_KEY]);

            if (result[this.NOTES_KEY] && result[this.NOTES_KEY].length) {
                this.notes = result[this.NOTES_KEY];
            } else if (result[this.OLD_STORAGE_KEY]) {
                const oldContent = result[this.OLD_STORAGE_KEY];
                if (oldContent.trim()) {
                    this.notes = [{
                        id: Date.now().toString(36),
                        content: oldContent,
                        updatedAt: Date.now()
                    }];
                    this.saveNotes();
                    try { chrome.storage.local.remove(this.OLD_STORAGE_KEY); } catch (e) {}
                }
            }
        } catch (e) {}
    }

    saveState() {
        try {
            chrome.storage.local.set({
                [this.STATE_KEY]: { position: this.position, size: this.size }
            });
        } catch (e) {}
    }

    loadState() {
        try {
            chrome.storage.local.get(this.STATE_KEY, (result) => {
                const state = result[this.STATE_KEY];
                if (state) {
                    if (state.position) {
                        if (state.position.right !== undefined) {
                            this.position = state.position;
                        } else if (state.position.x !== null && state.position.x !== undefined) {
                            this.position = {
                                right: window.innerWidth - state.position.x - (state.size?.width || this.DEFAULT_WIDTH),
                                bottom: window.innerHeight - state.position.y - (state.size?.height || this.DEFAULT_HEIGHT)
                            };
                        }
                    }
                    if (state.size) this.size = state.size;
                }
            });
        } catch (e) {}
    }

    // ─── 拖动（与 runner 完全一致）────────────────────────────────────────────

    startDrag(e) {
        this.isDragging = true;
        const rect = this.panel.getBoundingClientRect();
        this.dragOffset = {
            x: e.clientX - rect.left,
            y: e.clientY - rect.top
        };
        document.body.style.userSelect = 'none';
    }

    // ─── 调整大小（与 runner 完全一致）───────────────────────────────────────

    startResize(e, direction) {
        this.isResizing = true;
        this.resizeDirection = direction;
        this.resizeStart = {
            x: e.clientX,
            y: e.clientY,
            width: this.panel.offsetWidth,
            height: this.panel.offsetHeight,
            left: this.panel.offsetLeft,
            top: this.panel.offsetTop
        };
        document.body.style.userSelect = 'none';
        document.body.style.cursor = this.getCursorForDirection(direction);
    }

    getCursorForDirection(dir) {
        const cursors = {
            'n': 'ns-resize',   's': 'ns-resize',
            'e': 'ew-resize',   'w': 'ew-resize',
            'ne': 'nesw-resize', 'sw': 'nesw-resize',
            'nw': 'nwse-resize', 'se': 'nwse-resize'
        };
        return cursors[dir] || 'default';
    }

    onMouseMove(e) {
        if (this.isDragging) {
            const x = e.clientX - this.dragOffset.x;
            const y = e.clientY - this.dragOffset.y;
            this.setPosition(x, y);
        }
        if (this.isResizing) {
            this.doResize(e);
        }
    }

    doResize(e) {
        const { x, y, width, height, left, top } = this.resizeStart;
        const dx = e.clientX - x;
        const dy = e.clientY - y;
        const dir = this.resizeDirection;

        let newWidth = width;
        let newHeight = height;
        let newLeft = left;
        let newTop = top;

        if (dir.includes('e')) newWidth  = Math.max(this.MIN_WIDTH,  width  + dx);
        if (dir.includes('w')) {
            newWidth = Math.max(this.MIN_WIDTH, width - dx);
            newLeft  = left + (width - newWidth);
        }
        if (dir.includes('s')) newHeight = Math.max(this.MIN_HEIGHT, height + dy);
        if (dir.includes('n')) {
            newHeight = Math.max(this.MIN_HEIGHT, height - dy);
            newTop    = top + (height - newHeight);
        }

        this.panel.style.width  = newWidth  + 'px';
        this.panel.style.height = newHeight + 'px';
        this.panel.style.left   = newLeft   + 'px';
        this.panel.style.top    = newTop    + 'px';

        this.size     = { width: newWidth, height: newHeight };
        this.position = { right: window.innerWidth - newLeft - newWidth, bottom: window.innerHeight - newTop - newHeight };
    }

    onMouseUp() {
        if (this.isDragging || this.isResizing) {
            this.isDragging  = false;
            this.isResizing  = false;
            document.body.style.userSelect = '';
            document.body.style.cursor     = '';
            this.saveState();
        }
    }

    // ─── 位置（与 runner 完全一致）────────────────────────────────────────────

    setPosition(x, y) {
        const w = this.panel.offsetWidth;
        const h = this.panel.offsetHeight;
        const maxX = window.innerWidth  - w;
        const maxY = window.innerHeight - h;
        x = Math.max(0, Math.min(maxX, x));
        y = Math.max(0, Math.min(maxY, y));

        this.panel.style.left = x + 'px';
        this.panel.style.top  = y + 'px';
        this.position = { right: window.innerWidth - x - w, bottom: window.innerHeight - y - h };
    }

    _toLeftTop() {
        const x = window.innerWidth - this.position.right - this.size.width;
        const y = window.innerHeight - this.position.bottom - this.size.height;
        return {
            x: Math.max(0, Math.min(window.innerWidth - this.size.width, x)),
            y: Math.max(0, Math.min(window.innerHeight - this.size.height, y))
        };
    }

    applyState() {
        if (!this.panel) return;
        const { x, y } = this._toLeftTop();
        this.panel.style.width  = this.size.width  + 'px';
        this.panel.style.height = this.size.height + 'px';
        this.panel.style.left   = x + 'px';
        this.panel.style.top    = y + 'px';
    }

    // ─── Open / Close / Toggle ────────────────────────────────────────────────

    async open() {
        if (this.isOpen) return;
        this.isOpen = true;

        if (this.position.right === null) {
            this.position = this._calcDefaultPosition();
        }

        this.applyState();
        this.panel.hidden = false;
        this.panel.classList.add('ait-notepad-visible');
        this._setFocused(true);
        this._syncBtnActive();

        await this.loadNotes();
        if (!this.isOpen) return;

        if (!this.notes.length) {
            this.createNote();
        } else if (this.activeNoteId) {
            this.openNote(this.activeNoteId);
        } else {
            this.openNote(this.notes[this.notes.length - 1].id);
        }

        requestAnimationFrame(() => {
            if (!this.isOpen || this.currentView !== 'edit') return;
            this.textarea.focus();
            const len = this.textarea.value.length;
            this.textarea.setSelectionRange(len, len);
        });
    }

    _calcDefaultPosition() {
        const wrapper = document.querySelector('.ait-chat-timeline-wrapper');
        const W = this.size.width;
        const H = this.size.height;

        let right, bottom;
        if (wrapper) {
            const wRect = wrapper.getBoundingClientRect();
            right = (window.innerWidth - wRect.left) + 8;
            const notepadBtn = document.querySelector('.ait-notepad-btn');
            if (notepadBtn) {
                const btnRect = notepadBtn.getBoundingClientRect();
                bottom = window.innerHeight - btnRect.bottom;
            } else {
                bottom = window.innerHeight - wRect.bottom;
            }
        } else {
            right = 20;
            bottom = window.innerHeight - H - 100;
        }

        right  = Math.max(0, right);
        bottom = Math.max(0, bottom);
        return { right, bottom };
    }

    close() {
        if (!this.isOpen) return;
        this.isOpen = false;
        this.panel.hidden = true;
        this._flushCurrentNote();
        this._setFocused(false);
        this.panel.classList.remove('ait-notepad-visible');
        clearTimeout(this.saveTimeout);
        this._syncBtnActive();
    }

    toggle() {
        if (!this.isOpen) {
            this.open();
        } else if (this.panel.classList.contains('ait-notepad-focused')) {
            this.close();
        } else {
            this._setFocused(true);
        }
    }

    // ─── Helpers ─────────────────────────────────────────────────────────────

    _setFocused(focused) {
        if (!this.panel) return;
        this.panel.classList.toggle('ait-notepad-focused', focused);

        if (!this.textarea) return;
        if (focused) {
            this.textarea.removeAttribute('tabindex');
            this.textarea.removeAttribute('aria-hidden');
            if (this.currentView === 'edit') {
                requestAnimationFrame(() => {
                    if (!this.isOpen || this.currentView !== 'edit' || !this.panel?.classList.contains('ait-notepad-focused')) return;
                    this.textarea.focus();
                });
            }
            return;
        }

        this._flushCurrentNote();
        this._syncPreview();
        this.textarea.blur();
        this.textarea.setAttribute('tabindex', '-1');
        this.textarea.setAttribute('aria-hidden', 'true');
    }

    _syncPreview() {
        if (!this.preview || !this.textarea) return;
        const value = this.textarea.value;
        const placeholder = this.textarea.getAttribute('placeholder') || '';
        this.preview.textContent = value || placeholder;
        this.preview.classList.toggle('ait-notepad-preview-empty', !value);
    }

    _syncBtnActive() {
        const btn = document.querySelector('.ait-notepad-btn');
        if (btn) btn.classList.toggle('active', this.isOpen);
    }

    destroy() {
        this.isOpen = false;
        this.onMouseUp();
        if (this._onMouseMove) {
            document.removeEventListener('mousemove', this._onMouseMove);
            document.removeEventListener('mouseup', this._onMouseUp);
            this._onMouseMove = null;
            this._onMouseUp = null;
        }
        if (this._onFocusCheck) {
            document.removeEventListener('mousedown', this._onFocusCheck, true);
            this._onFocusCheck = null;
        }
        if (this._onStorageChange) {
            try { chrome.storage.onChanged.removeListener(this._onStorageChange); } catch {}
            this._onStorageChange = null;
        }
        if (this._onWindowResize) {
            window.removeEventListener('resize', this._onWindowResize);
            this._onWindowResize = null;
        }
        clearTimeout(this.saveTimeout);
        this._flushCurrentNote();
        if (this.panel) {
            this.panel.remove();
            this.panel = null;
        }
        this.textarea = null;
        this.preview = null;
        this.listContainer = null;
        this.listBtn = null;
        this.addBtn = null;
        this.locationEl = null;
        this.locationTextEl = null;
        this.footerEl = null;
    }
}

// Auto-initialize as singleton
window.notepadManager = new NotepadManager();
window.AITContentSession?.onStop(() => window.notepadManager.destroy());
window.notepadManager.init().catch(() => {});

