// Source: js/sidebarStarred/index.js
/**
 * Sidebar Starred - Entry Point
 *
 * 功能入口：检测当前平台是否支持侧边栏收藏列表，
 * 然后以重试机制等待侧边栏 DOM 就绪后初始化 SidebarStarredManager。
 *
 * 生命周期：
 *   1. 平台检测（feature gate）
 *   2. 等待侧边栏 DOM 出现（retry）
 *   3. 初始化 Manager
 *   4. SPA 路由变化时由 Manager 内部的 reinjectTimer 自动处理
 */

(async function () {
    const RETRY_DELAYS = [800, 1000, 1500, 2000, 2000, 3000];

    let manager = null;
    let platform = null;
    let adapter = null;
    let initInFlight = false;
    let bootstrapInFlight = false;
    let settingsListenerAttached = false;

    async function resolveSupport() {
        platform = await getCurrentPlatform();
        if (!platform || platform.features?.sidebarStarred !== true) {
            platform = null;
            adapter = null;
            return false;
        }

        const registry = window.sidebarStarredAdapterRegistry;
        if (!registry) {
            adapter = null;
            return false;
        }

        adapter = await registry.getAdapter();
        return !!adapter;
    }

    // ==================== Init with retry ====================

    function canInject() {
        if (!adapter) return false;
        const info = adapter.findInsertionPoint();
        if (!info) return false;
        const { parent } = info;
        if (!parent || !parent.offsetParent || parent.offsetHeight <= 0) return false;
        return true;
    }

    async function initialize(retryIndex) {
        if (manager || initInFlight) return;
        initInFlight = true;
        try {
            await TimelineI18n.ready();

            if (!adapter) {
                if (!await resolveSupport()) return;
            }

            if (window.AITContentSession?.active === false) return;
            manager = new SidebarStarredManager(adapter);
            const ok = await manager.init();
            if (window.AITContentSession?.active === false) return;

            if (!ok) {
                manager.destroy();
                manager = null;
                if (retryIndex !== undefined) {
                    initWithRetry(retryIndex + 1);
                }
            }
        } catch (error) {
            destroyManager();
            throw error;
        } finally {
            initInFlight = false;
        }
    }

    function destroyManager() {
        if (manager) {
            manager.destroy();
            manager = null;
        }
    }

    function initWithRetry(retryIndex = 0) {
        if (retryIndex >= RETRY_DELAYS.length) return;

        setTimeout(async () => {
            try {
                if (!await resolveSupport()) return;
                if (canInject()) {
                    await initialize(retryIndex);
                } else {
                    initWithRetry(retryIndex + 1);
                }
            } catch (error) {
            }
        }, RETRY_DELAYS[retryIndex]);
    }

    // ==================== 监听开关变化 ====================

    function attachSettingsListener() {
        if (settingsListenerAttached) return;
        settingsListenerAttached = true;
        StorageAdapter.addChangeListener((changes, areaName) => {
            if (areaName !== 'local' || !changes.sidebarStarredPlatformSettings) return;
            if (!platform) return;
            const settings = changes.sidebarStarredPlatformSettings.newValue || {};
            const enabled = settings[platform.id] !== false;
            if (enabled && !manager) {
                if (canInject()) {
                    initialize(0).catch(() => {});
                } else {
                    initWithRetry();
                }
            } else if (!enabled && manager) {
                destroyManager();
            }
        });
    }

    // ==================== Bootstrap ====================

    async function bootstrap() {
        if (manager || bootstrapInFlight) return;
        bootstrapInFlight = true;
        try {
            if (!await resolveSupport()) return;
            attachSettingsListener();

            const settings = await StorageAdapter.get('sidebarStarredPlatformSettings');
            if (window.AITContentSession?.active === false) return;
            if (settings && settings[platform.id] === false) return;

            if (canInject()) {
                await initialize(0);
            } else {
                initWithRetry();
            }
        } finally {
            bootstrapInFlight = false;
        }
    }

    window.AITContentSession?.onStop(() => {
        try { destroyManager(); } finally { adapter?.restoreNativeList(); }
    });
    window.AITPlatformFeatures.register('sidebar-starred', bootstrap);
})();

;

// Source: js/customSite/custom-site-utils.js
/**
 * Custom Site Utils
 *
 * 自定义站点检测工具：加载自定义时间轴适配配置，判断当前页面是否命中。
 */

let _customTimelineSiteDomains = null;

function loadCustomTimelineSiteDomains() {
    try {
        const staticConfigs = Array.isArray(window.CUSTOM_SITE_INFO)
            ? window.CUSTOM_SITE_INFO
            : [];
        const domains = staticConfigs
            .filter(config => config?.enabled !== false && Array.isArray(config.sites))
            .flatMap(config => config.sites)
            .map(site => String(site || '').trim().toLowerCase())
            .filter(Boolean);
        _customTimelineSiteDomains = [...new Set(domains)];
    } catch (e) {
        _customTimelineSiteDomains = [];
    }
}

function isCustomTimelineSite(url) {
    if (!_customTimelineSiteDomains || _customTimelineSiteDomains.length === 0) return false;

    try {
        const hostname = new URL(url).hostname.toLowerCase();
        return _customTimelineSiteDomains.some(domain =>
            hostname === domain || hostname.endsWith('.' + domain)
        );
    } catch {
        return false;
    }
}

function isCurrentCustomTimelineSite() {
    return isCustomTimelineSite(location.href);
}

;

// Source: js/customSite/custom-site-float-button.js
/**
 * Custom Site Float Button
 *
 * 自定义适配站点浮窗按钮：可拖拽，点击弹出提示词列表（复制模式）。
 * 提示词下拉菜单复用 prompt-dropdown-ui.js 共享渲染。
 * 点击提示词项时复制到剪贴板，不关闭弹窗。
 */

class CustomSiteFloatButton {
    constructor() {
        this.buttonElement = null;
        this.prompts = [];
        this._promptDropdown = null;
        this._promptOverlay = null;
        this._storageListener = null;
        this._boundCloseOnClickOutside = null;
        this.isDestroyed = false;

        // 拖拽状态
        this._isDragging = false;
        this._hasMoved = false;
        this._startX = 0;
        this._startY = 0;
        this._startLeft = 0;
        this._startTop = 0;
        this._boundOnPointerMove = null;
        this._boundOnPointerUp = null;
    }

    async init() {
        await TimelineI18n.ready();

        await this._loadPrompts();
        if (this.isDestroyed) return;
        this._createButton();
        await this._loadPosition();
        if (this.isDestroyed) return;
        this._initDrag();
        this._attachStorageListener();
    }

    async _loadPrompts() {
        try {
            const result = await chrome.storage.local.get('prompts');
            this.prompts = result.prompts || [];
        } catch (e) {
            this.prompts = [];
        }
    }

    _attachStorageListener() {
        this._storageListener = (changes, areaName) => {
            if (this.isDestroyed) return;
            if (areaName === 'local' && changes.prompts) {
                this.prompts = changes.prompts.newValue || [];
            }
        };
        chrome.storage.onChanged.addListener(this._storageListener);
    }

    // ==================== 按钮创建 ====================

    _createButton() {
        if (this.buttonElement) return;

        const btn = document.createElement('div');
        btn.setAttribute('data-ait-owned-ui', '');
        btn.className = 'custom-site-float-btn';
        btn.innerHTML = `<img src="${chrome.runtime.getURL('images/logo.png')}" alt="Timeline" class="custom-site-float-logo">`;
        document.body.appendChild(btn);
        this.buttonElement = btn;
    }

    // ==================== 拖拽 ====================

    _initDrag() {
        const btn = this.buttonElement;
        if (!btn) return;

        const onPointerDown = (e) => {
            if (e.button && e.button !== 0) return;
            this._isDragging = true;
            this._hasMoved = false;

            const clientX = e.touches ? e.touches[0].clientX : e.clientX;
            const clientY = e.touches ? e.touches[0].clientY : e.clientY;
            this._startX = clientX;
            this._startY = clientY;

            const rect = btn.getBoundingClientRect();
            this._startLeft = rect.left;
            this._startTop = rect.top;

            btn.style.transition = 'none';
        };

        this._boundOnPointerMove = (e) => {
            if (!this._isDragging) return;
            const clientX = e.touches ? e.touches[0].clientX : e.clientX;
            const clientY = e.touches ? e.touches[0].clientY : e.clientY;
            const dx = clientX - this._startX;
            const dy = clientY - this._startY;

            if (!this._hasMoved && (Math.abs(dx) > 4 || Math.abs(dy) > 4)) {
                this._hasMoved = true;
            }

            if (this._hasMoved) {
                const btnW = btn.offsetWidth;
                const btnH = btn.offsetHeight;
                const newLeft = Math.max(0, Math.min(this._startLeft + dx, window.innerWidth - btnW));
                const newTop = Math.max(0, Math.min(this._startTop + dy, window.innerHeight - btnH));
                btn.style.left = `${newLeft}px`;
                btn.style.top = `${newTop}px`;
                btn.style.right = 'auto';
                btn.style.bottom = 'auto';
            }
        };

        this._boundOnPointerUp = () => {
            if (!this._isDragging) return;
            this._isDragging = false;
            btn.style.transition = '';

            if (this._hasMoved) {
                this._savePosition();
            } else {
                this._handleClick();
            }
        };

        btn.addEventListener('mousedown', onPointerDown);
        btn.addEventListener('touchstart', onPointerDown, { passive: true });
        document.addEventListener('mousemove', this._boundOnPointerMove);
        document.addEventListener('touchmove', this._boundOnPointerMove, { passive: true });
        document.addEventListener('mouseup', this._boundOnPointerUp);
        document.addEventListener('touchend', this._boundOnPointerUp);
    }

    async _savePosition() {
        if (!this.buttonElement) return;
        const rect = this.buttonElement.getBoundingClientRect();
        try {
            await chrome.storage.local.set({
                customSiteFloatPos: { left: rect.left, top: rect.top }
            });
        } catch { /* ignore */ }
    }

    async _loadPosition() {
        try {
            const result = await chrome.storage.local.get(['customSiteFloatPos', 'mirrorSiteFloatPos']);
            const pos = result.customSiteFloatPos || result.mirrorSiteFloatPos;
            if (pos && this.buttonElement) {
                const btnW = this.buttonElement.offsetWidth || 44;
                const btnH = this.buttonElement.offsetHeight || 44;
                const left = Math.max(0, Math.min(pos.left, window.innerWidth - btnW));
                const top = Math.max(0, Math.min(pos.top, window.innerHeight - btnH));
                this.buttonElement.style.left = `${left}px`;
                this.buttonElement.style.top = `${top}px`;
                this.buttonElement.style.right = 'auto';
                this.buttonElement.style.bottom = 'auto';
            }
        } catch { /* use default CSS position */ }
    }

    // ==================== 提示词弹窗（复用共享 UI） ====================

    _handleClick() {
        if (this._promptDropdown) {
            this._hidePromptDropdown();
        } else {
            this._showPromptDropdown();
        }
    }

    _showPromptDropdown() {
        if (window.globalDropdownManager) {
            window.globalDropdownManager.hide(true);
        }

        const filteredPrompts = this.prompts.filter(p => !p.platformId);

        this._promptDropdown = createPromptDropdownUI({
            prompts: filteredPrompts,
            tooltipPlacement: 'left',
            showStoreDetailButton: false,
            onItemClick: (prompt, itemEl) => {
                this._copyPrompt(prompt, itemEl);
            },
            onManageClick: () => {
                this._hidePromptDropdown();
                if (window.panelModal) window.panelModal.show('prompt');
            }
        });

        this._promptOverlay = document.createElement('div');
        this._promptOverlay.className = 'prompt-dropdown-overlay';
        this._promptOverlay.setAttribute('data-ait-owned-ui', 'prompt-menu');
        document.body.append(this._promptOverlay, this._promptDropdown);
        this._positionDropdown();

        requestAnimationFrame(() => {
            this._promptDropdown.classList.add('visible');
        });

        this._boundCloseOnClickOutside = (e) => {
            if (!this._promptDropdown?.contains(e.target) && !this.buttonElement?.contains(e.target)) {
                this._hidePromptDropdown();
            }
        };
        setTimeout(() => {
            document.addEventListener('click', this._boundCloseOnClickOutside, true);
        }, 0);
    }

    async _copyPrompt(prompt, itemEl) {
        if (!prompt.content) return;

        try {
            await navigator.clipboard.writeText(prompt.content);
        } catch {
            const ta = document.createElement('textarea');
            ta.value = prompt.content;
            ta.style.cssText = 'position:fixed;left:-9999px;top:-9999px;opacity:0';
            document.body.appendChild(ta);
            ta.select();
            document.execCommand('copy');
            ta.remove();
        }

        // 项目闪烁反馈
        if (itemEl) {
            itemEl.classList.add('custom-site-copy-flash');
            setTimeout(() => itemEl.classList.remove('custom-site-copy-flash'), 600);
        }

        if (window.globalToastManager) {
            const toastTarget = itemEl?.querySelector('.prompt-dropdown-item-content') || itemEl;
            window.globalToastManager.success(
                TimelineI18n.getMessage('mirrorSiteCopied') || '已复制到剪贴板',
                toastTarget,
                { position: 'top', gap: 8 }
            );
        }
    }

    _positionDropdown() {
        if (!this._promptDropdown || !this.buttonElement) return;

        const btnRect = this.buttonElement.getBoundingClientRect();
        const dw = 320, dh = 400, gap = 10;

        this._promptDropdown.style.width = `${dw}px`;
        this._promptDropdown.style.height = `${dh}px`;
        this._promptDropdown.style.visibility = 'hidden';
        this._promptDropdown.style.display = 'flex';

        let left = btnRect.right - dw;
        if (left < 8) left = 8;
        if (left + dw > window.innerWidth - 8) left = window.innerWidth - dw - 8;

        let top = btnRect.top - gap - dh;
        if (top < 20) top = btnRect.bottom + gap;

        this._promptDropdown.style.left = `${left}px`;
        this._promptDropdown.style.top = `${top}px`;
        this._promptDropdown.style.visibility = 'visible';
    }

    _hidePromptDropdown() {
        if (this._boundCloseOnClickOutside) {
            document.removeEventListener('click', this._boundCloseOnClickOutside, true);
            this._boundCloseOnClickOutside = null;
        }
        if (window.globalTooltipManager) window.globalTooltipManager.hide();

        if (this._promptDropdown) {
            this._promptDropdown.classList.remove('visible');
            setTimeout(() => {
                this._promptDropdown?.parentNode?.removeChild(this._promptDropdown);
                this._promptDropdown = null;
            }, 150);
        }
        if (this._promptOverlay?.parentNode) {
            this._promptOverlay.parentNode.removeChild(this._promptOverlay);
        }
        this._promptOverlay = null;
    }

    // ==================== 销毁 ====================

    destroy() {
        this.isDestroyed = true;
        this._hidePromptDropdown();

        if (this._storageListener) {
            try { chrome.storage.onChanged.removeListener(this._storageListener); } catch {}
            this._storageListener = null;
        }
        if (this._boundOnPointerMove) {
            document.removeEventListener('mousemove', this._boundOnPointerMove);
            document.removeEventListener('touchmove', this._boundOnPointerMove);
        }
        if (this._boundOnPointerUp) {
            document.removeEventListener('mouseup', this._boundOnPointerUp);
            document.removeEventListener('touchend', this._boundOnPointerUp);
        }
        if (this.buttonElement?.parentNode) {
            this.buttonElement.parentNode.removeChild(this.buttonElement);
            this.buttonElement = null;
        }
    }
}

;

// Source: js/customSite/index.js
/**
 * Custom Site Entry Point
 *
 * 检测当前页面是否命中自定义时间轴适配站点，
 * 如果是，初始化浮窗按钮（提示词复制模式）。
 */

(function () {
    async function initCustomSite() {
        if (window._customSiteFloatButton) return;
        await TimelineI18n.ready();

        if (typeof loadCustomTimelineSiteDomains === 'function') {
            loadCustomTimelineSiteDomains();
        }

        if (typeof isCurrentCustomTimelineSite === 'function' && isCurrentCustomTimelineSite()) {
            if (window.AITContentSession?.active === false) return;
            const floatButton = new CustomSiteFloatButton();
            window.AITContentSession?.onStop(() => floatButton.destroy());
            await floatButton.init();
            window._customSiteFloatButton = floatButton;
        }
    }

    window.AITPlatformFeatures.register('custom-site', initCustomSite);
})();

;

// Source: js/conversationExport/constants.js
/**
 * Conversation Export - 常量与共享工具
 *
 * 集中管理对话导出功能的：
 * - 文案（已接入 i18n：TimelineI18n 取值 + 中文兜底，见 CE_TEXT）
 * - 导出格式定义
 * - PNG 图片主题色（canvas 友好的定义）
 * - 通用工具函数（文件名清洗、时间格式化等）
 *
 * 不涉及 DOM 抽取与渲染，保持纯数据/纯函数，便于复用与测试。
 */

/**
 * 文案集中管理（已接入 i18n）。
 *
 * 通过 TimelineI18n.getMessage 惰性取值：
 * - 每次访问 CE_TEXT.xxx 时实时解析，随语言切换即时生效；
 * - i18n key 缺失或 TimelineI18n 尚未就绪时，回退到 CE_TEXT_FALLBACK 的中文兜底；
 * - 角色标签 Q / A 为固定符号，不接入 i18n，仅保留在兜底表中。
 * 各文案的 i18n key 见 CE_TEXT_I18N_KEYS，中文/英文分别维护在 _locales/{zh_CN,en}/messages.json。
 */
const CE_TEXT_FALLBACK = {
    buttonTooltip: '导出对话',
    modalTitle: '导出对话',

    sectionRange: '导出范围',
    sectionFormat: '导出格式',
    sectionHeader: '更多配置',
    sectionTheme: '主题色',
    sectionList: '选择对话',

    rangeAll: '整个会话',
    rangeSelect: '选择对话',

    headerShowUrl: '对话 URL',
    headerShowTime: '导出时间',
    headerShowConversationTime: '对话时间',
    askTimeLabel: '提问时间',

    selectAll: '全选',
    selectedCount: '已选 {count} / {total} 条',
    turnPrefix: '对话',
    // 角色标签：PNG / Markdown / TXT / 选择列表统一使用 Q / A
    exportRoleUser: 'Q',
    exportRoleAssistant: 'A',
    emptyAssistant: '未找到回复内容',
    emptyUserPreview: '（无文本内容）',

    cancel: '取消',
    confirm: '导出',

    loading: '加载对话中...',
    loadingProgress: '加载对话中...（已加载 {count} 条）',
    cancelLoading: '取消加载',
    exporting: '导出中...',
    done: '对话已导出',
    failed: '导出失败',
    noConversation: '未找到可导出的对话',
    needSelect: '请至少选择 1 条对话',

    sourceLabel: '对话 URL',
    timeLabel: '导出时间',
    titleLabel: '标题',
    imageCannotEmbed: '图片无法内嵌',
    imageNotRendered: '图片未渲染，无法内嵌（可滚动到该轮后重试）',
    truncatedNotice: '内容过长，已截断',
    imageListTitle: '图片',

    // 兜底文案：会话标题 / 文件名缺省值
    defaultTitle: '对话导出',
};

/**
 * 文案 key → i18n message key 映射。
 * 未列入者（如 exportRoleUser / exportRoleAssistant）不走 i18n，直接使用中文兜底。
 */
const CE_TEXT_I18N_KEYS = {
    buttonTooltip: 'conversationExportButtonTooltip',
    modalTitle: 'conversationExportModalTitle',

    sectionRange: 'conversationExportSectionRange',
    sectionFormat: 'conversationExportSectionFormat',
    sectionHeader: 'conversationExportSectionHeader',
    sectionTheme: 'conversationExportSectionTheme',
    sectionList: 'conversationExportSectionList',

    rangeAll: 'conversationExportRangeAll',
    rangeSelect: 'conversationExportRangeSelect',

    headerShowUrl: 'conversationExportHeaderShowUrl',
    headerShowTime: 'conversationExportHeaderShowTime',
    headerShowConversationTime: 'conversationExportHeaderShowConversationTime',
    askTimeLabel: 'conversationExportAskTimeLabel',

    selectAll: 'conversationExportSelectAll',
    selectedCount: 'conversationExportSelectedCount',
    turnPrefix: 'conversationExportTurnPrefix',
    emptyAssistant: 'conversationExportEmptyAssistant',
    emptyUserPreview: 'conversationExportEmptyUserPreview',

    cancel: 'conversationExportCancel',
    confirm: 'conversationExportConfirm',

    loading: 'conversationExportLoading',
    loadingProgress: 'conversationExportLoadingProgress',
    cancelLoading: 'conversationExportCancelLoading',
    exporting: 'conversationExportExporting',
    done: 'conversationExportDone',
    failed: 'conversationExportFailed',
    noConversation: 'conversationExportNoConversation',
    needSelect: 'conversationExportNeedSelect',

    sourceLabel: 'conversationExportSourceLabel',
    timeLabel: 'conversationExportTimeLabel',
    titleLabel: 'conversationExportTitleLabel',
    imageCannotEmbed: 'conversationExportImageCannotEmbed',
    imageNotRendered: 'conversationExportImageNotRendered',
    truncatedNotice: 'conversationExportTruncatedNotice',
    imageListTitle: 'conversationExportImageListTitle',

    defaultTitle: 'conversationExportDefaultTitle',
};

/**
 * 取指定文案：优先 i18n，回退中文兜底。
 * @param {string} key - CE_TEXT_FALLBACK 中的键
 * @returns {string}
 */
function ceGetText(key) {
    const i18nKey = CE_TEXT_I18N_KEYS[key];
    if (i18nKey && typeof TimelineI18n !== 'undefined') {
        const message = TimelineI18n.getMessage(i18nKey);
        if (message) return message;
    }
    return CE_TEXT_FALLBACK[key];
}

/**
 * 文案访问对象：保持 CE_TEXT.xxx 的调用方式不变，读取时惰性解析 i18n。
 */
const CE_TEXT = Object.keys(CE_TEXT_FALLBACK).reduce((acc, key) => {
    Object.defineProperty(acc, key, {
        get() { return ceGetText(key); },
        enumerable: true,
    });
    return acc;
}, {});

/**
 * 导出格式定义。
 * @typedef {Object} ExportFormat
 * @property {string} id
 * @property {string} label
 * @property {string} ext - 文件扩展名（含点）
 * @property {string} mime
 */
const CE_FORMATS = [
    { id: 'markdown', label: 'Markdown', ext: '.md', mime: 'text/markdown' },
    { id: 'txt', label: 'TXT', ext: '.txt', mime: 'text/plain' },
    { id: 'json', label: 'JSON', ext: '.json', mime: 'application/json' },
    { id: 'csv', label: 'CSV', ext: '.csv', mime: 'text/csv' },
    { id: 'png', label: 'PNG', ext: '.png', mime: 'image/png' },
    { id: 'pdf', label: 'PDF', ext: '.pdf', mime: 'application/pdf' },
];

const CE_DEFAULT_FORMAT = 'markdown';

/**
 * 采集策略：决定 collectAllTurns 如何把完整对话准备到「可读取」状态。
 * - SCROLL：滚动把未渲染内容加载/渲染出来（Gemini 顶部懒加载、ChatGPT 虚拟化空壳等）
 * - STATIC：完整对话数据已在 DOM/内存，无需滚动，直接读取
 *
 * 新增平台时按其加载方式选择策略；需要全新加载方式时可在此扩展并在基类 collectAllTurns 分派。
 */
const CE_LOAD_STRATEGY = {
    SCROLL: 'scroll',
    STATIC: 'static',
};

/**
 * PNG 图片主题色（canvas 友好定义）。
 * 由全局 ACTIVE_COLOR_PALETTE 派生，色值与时间轴激活色共享同一来源，避免重复维护；
 * id 天然与时间轴激活色保持一致，默认主题色可跟随平台激活色设置。
 * - solid 主题保留纯色填充；gradient 主题转成 canvas 色标数组 [[offset, color], ...]
 * - 头部文字统一使用白色
 *
 * @typedef {Object} ExportTheme
 * @property {string} id
 * @property {string} label
 * @property {string} textColor - 头部文字颜色
 * @property {string} [solid] - 纯色填充
 * @property {Array<[number,string]>} [gradient] - 渐变色标 [offset, color]
 */
const CE_THEMES = ACTIVE_COLOR_PALETTE.map(entry => ({
    id: entry.id,
    label: entry.label,
    textColor: '#ffffff',
    ...(entry.gradient
        ? { gradient: entry.gradient.stops.map(stop => [...stop]) }
        : { solid: entry.solid }),
}));

const CE_DEFAULT_THEME = 'purple';

/**
 * 小于该尺寸（任一边）的图片视为装饰图（头像、图标等），不作为对话图片导出。
 */
const CE_MIN_IMAGE_SIZE = 48;

/**
 * 文件名最大长度（不含扩展名），避免过长导致下载失败。
 */
const CE_MAX_FILENAME_LENGTH = 80;

/**
 * 浏览器 canvas 高度的保守上限。
 * 各浏览器实际上限不同（Chrome 约 32767），这里留出余量。
 */
const CE_MAX_CANVAS_HEIGHT = 30000;

/**
 * 按模板插值文案。
 * @param {string} template - 含 {key} 占位符的模板
 * @param {Object} params
 * @returns {string}
 */
function ceFormatText(template, params = {}) {
    return String(template).replace(/\{(\w+)\}/g, (match, key) => (
        Object.prototype.hasOwnProperty.call(params, key) ? String(params[key]) : match
    ));
}

/**
 * 根据 id 获取主题定义，找不到时回退默认主题。
 * @param {string} themeId
 * @returns {ExportTheme}
 */
function ceGetTheme(themeId) {
    return CE_THEMES.find(t => t.id === themeId) ||
        CE_THEMES.find(t => t.id === CE_DEFAULT_THEME) ||
        CE_THEMES[0];
}

/**
 * 清洗文件名：移除系统不允许的字符并限制长度。
 * @param {string} rawName
 * @returns {string}
 */
function ceSanitizeFilename(rawName) {
    const fallback = CE_TEXT.defaultTitle;
    let name = (rawName || '').toString().trim();

    // 移除控制字符与文件系统保留字符 \ / : * ? " < > |
    name = name
        .replace(/[\x00-\x1f\x80-\x9f]/g, '')
        .replace(/[\\/:*?"<>|]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();

    // 去除结尾的点（Windows 不允许文件名以点结尾）
    name = name.replace(/\.+$/, '').trim();

    if (!name) name = fallback;

    if (name.length > CE_MAX_FILENAME_LENGTH) {
        name = name.slice(0, CE_MAX_FILENAME_LENGTH).trim();
    }

    return name || fallback;
}

/**
 * 格式化为本地时间字符串。
 * @param {Date} [date]
 * @returns {string}
 */
function ceFormatLocalTime(date = new Date()) {
    try {
        const pad = (n) => String(n).padStart(2, '0');
        return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ` +
            `${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
    } catch {
        return '';
    }
}

/**
 * 格式化提问时间（时间戳，毫秒）为简洁的本地时间字符串。
 * 与导出时间一致采用 YYYY-MM-DD HH:mm 形式（不含秒）。
 * @param {number} timestamp - 毫秒时间戳
 * @returns {string}
 */
function ceFormatChatTime(timestamp) {
    if (!timestamp) return '';
    try {
        const date = new Date(timestamp);
        if (Number.isNaN(date.getTime())) return '';
        const pad = (n) => String(n).padStart(2, '0');
        return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ` +
            `${pad(date.getHours())}:${pad(date.getMinutes())}`;
    } catch {
        return '';
    }
}

/**
 * 检测当前是否深色模式（复用全局 detectDarkMode）。
 * @returns {boolean}
 */
function ceIsDarkMode() {
    return typeof detectDarkMode === 'function' ? detectDarkMode() : false;
}

