// Source: js/conversationExport/adapters/base.js
/**
 * Conversation Export - 导出适配器基类
 *
 * 独立的多平台适配器家族（对齐 timeline/sidebarStarred/smartInputBox 的架构）。
 * 基类只承载「平台无关」的通用能力：
 * - 采集编排 collectAllTurns：按 loadStrategy（SCROLL 滚动加载 / STATIC 内存直读）
 *   把对话准备到可读取状态 → prepareCollection 一次性准备 → 逐轮 extractTurn 读取去重
 * - 「平台事实」优先委托时间轴 adapter（单一事实来源）：用户/助手消息选择器、
 *   对话路由判断、按钮插入锚点、会话标题、滚动容器；时间轴未运行时，选择器回退到
 *   全局 registry 里同平台的时间轴 adapter（仍是单一来源，无需重复维护），其余回退子类兜底
 * - 通用抽取 helper：_domMarkdownFrom（正文根→markdown）、_pairFlatTurns（扁平角色序列配对）
 * - 默认主题色、平台名等派生信息
 *
 * 「平台相关」的取数由子类实现（DOM 范式见 gemini.js / chatgpt.js）。
 *
 * 数据结构（turn）：
 * {
 *   id: string,
 *   order: number,
 *   user: { text: string, images: Array, time: number|null },
 *   assistant: { markdown: string, text: string, images: Array }
 * }
 *
 * user.time 为提问时间戳（毫秒），来源于扩展的 ChatTimeRecorder 记录（chatTimes 存储）；
 * 未记录（历史对话/平台未开启该功能）时为 null。
 */

class CEExportAdapter {
    constructor(platformId) {
        this.platformId = platformId;
        this.domToMarkdown = new CEDomToMarkdown();
        // 采集策略（见 CE_LOAD_STRATEGY）。默认滚动加载（Gemini 等）。
        this.loadStrategy = CE_LOAD_STRATEGY.SCROLL;
    }

    // ---------- 平台事实（默认委托时间轴 adapter，子类提供兜底/覆盖） ----------

    /**
     * 解析同平台的时间轴 adapter（平台事实的单一来源）。
     * 优先返回运行中的 timelineManager.adapter（携带页面运行态）；时间轴未运行时，
     * 从全局只读单例 siteAdapterRegistry 按 platformId 取同平台内置 adapter，
     * 以复用其静态平台事实（如消息选择器），避免在导出侧重复维护一份。
     * 都取不到时返回 null。
     * @returns {SiteAdapter|null}
     */
    _resolveTimelineAdapter() {
        const live = window.timelineManager?.adapter;
        if (live) return live;
        try {
            const registry = window.siteAdapterRegistry;
            const all = registry?.getAllAdapters?.() || [];
            return all.find(a => a.platformId === this.platformId) || null;
        } catch {
            return null;
        }
    }

    /**
     * 当前页面是否可导出。
     * 默认实现：平台匹配 + 对话路由（复用时间轴 adapter 的 isConversationRoute，
     * 不可用时跳过该检查）+ 页面存在用户消息。
     */
    isExportablePage() {
        if (!matchesCurrentPlatformSync(this.platformId)) return false;

        const isRoute = window.timelineManager?.adapter?.isConversationRoute?.(location.pathname);
        if (isRoute === false) return false;

        const selector = this.getUserMessageSelector();
        return !!selector && document.querySelector(selector) !== null;
    }

    /**
     * 按钮插入锚点（插入到该元素前面）；返回 null 则不显示按钮。
     * 优先复用时间轴 adapter 的收藏按钮锚点（两者插入同一位置，单一事实来源），
     * 时间轴不可用时回退子类的 _fallbackButtonInsertTarget。
     */
    getButtonInsertTarget() {
        const shared = window.timelineManager?.adapter?.getStarChatButtonTarget?.();
        return shared || this._fallbackButtonInsertTarget();
    }

    /** 时间轴不可用时的按钮锚点兜底，由子类实现 */
    _fallbackButtonInsertTarget() { return null; }

    /**
     * 会话标题。
     * 优先复用时间轴 adapter 的 getDefaultChatTheme（已做平台后缀清洗），
     * 退化为 document.title → 第一条用户消息文本。
     */
    getConversationTitle() {
        const shared = window.timelineManager?.adapter?.getDefaultChatTheme?.();
        if (shared) return shared;

        const title = (document.title || '').trim();
        if (title) return title;

        const selector = this.getUserMessageSelector();
        const firstUser = selector ? document.querySelector(selector) : null;
        if (firstUser) {
            const text = (firstUser.textContent || '').replace(/\s+/g, ' ').trim();
            if (text) return text.slice(0, 40);
        }
        return CE_TEXT.defaultTitle;
    }

    /**
     * 滚动容器。
     * 优先复用时间轴已解析好的滚动容器（与页面实际滚动区域一致），
     * 再尝试子类兜底 _fallbackScrollContainer，最后退化为页面根滚动元素。
     */
    getScrollContainer() {
        const timelineContainer = window.timelineManager?.scrollContainer;
        if (timelineContainer && timelineContainer.nodeType === 1) {
            return timelineContainer;
        }

        const custom = this._fallbackScrollContainer();
        if (custom) return custom;

        return document.scrollingElement || document.documentElement || window;
    }

    /** 时间轴不可用时的滚动容器兜底，由子类按需实现 */
    _fallbackScrollContainer() { return null; }

    // ---------- 子类需实现（平台相关） ----------

    /**
     * 当前对话的「轮单元」列表，按对话顺序排列。
     * 轮单元对基类是不透明的：可以是 DOM 容器（Gemini 的 .conversation-container），
     * 也可以是平台自定义对象（ChatGPT 的 {userEl, assistantEl} 配对）——
     * 基类只负责按顺序把它逐个传给 extractTurn，由同一子类负责解释。
     * @returns {Array<*>}
     */
    getTurnContainers() { return []; }

    /**
     * 从单个轮单元抽取一轮对话。
     * @param {*} turnUnit - getTurnContainers 返回的轮单元（Element 或平台自定义对象）
     * @returns {{id:string|null, user:Object, assistant:Object}|null}
     */
    extractTurn(turnUnit) { return null; }

    /**
     * 是否仍在加载更早的历史内容（平台各自的加载指示器）。
     * 默认无指示器，采集循环会退化为“滚动到位置稳定即停”。
     * @returns {boolean}
     */
    isLoadingMore() { return false; }

    /**
     * 采集前的准备钩子（在滚动加载完成、正式读取每轮内容之前调用一次）。
     * 平台可在此做一次性准备（如预取/缓存平台数据）。默认无操作。
     * @returns {Promise<void>}
     */
    async prepareCollection() { /* no-op by default */ }

    // ---------- 通用 helper（供子类复用平台无关的抽取模式） ----------

    /**
     * 从消息元素里挑选「正文根节点」并转 markdown。
     *
     * 依次尝试 rootSelectors，命中第一个作为正文根；都不命中时退化为 el 本身。
     * 用于消除各平台 _extractAssistant 里「找 .markdown 等正文根再交给 domToMarkdown」的重复。
     *
     * @param {Element} el - 消息元素（如 model-response / 助手轮）
     * @param {string[]} [rootSelectors] - 正文根候选选择器（按优先级）
     * @returns {{markdown:string, text:string, images:Array}}
     */
    _domMarkdownFrom(el, rootSelectors = []) {
        if (!el) return { markdown: '', text: '', images: [] };
        let root = null;
        for (const sel of rootSelectors) {
            try { root = el.querySelector(sel); } catch { root = null; }
            if (root) break;
        }
        return this.domToMarkdown.convert(root || el);
    }

    /**
     * 把「按文档顺序排列、带角色的元素序列」配对成一问一答的 turn 单元。
     *
     * 以用户消息为锚：其后、下一个用户消息之前的第一个助手消息作为该轮回复。
     * 适用于 user/assistant 交替的扁平消息列表（ChatGPT 等；Gemini 那种一个容器含问答的
     * 结构不需要它）。开头出现、无前置用户轮的助手消息（如开场白）忽略。
     *
     * ⚠️ 隐含假设：一轮回复只对应一个助手元素。若平台把一轮回复拆成多个连续的
     * assistant 元素（如工具调用 + 正文分段），第二个起会被丢弃——这类平台应在
     * 元素粒度上先合并（如 ChatGPT 在 turn 级聚合 messages），或自行实现配对。
     *
     * @param {Element[]} orderedEls - 按文档顺序排列的消息/轮元素
     * @param {(el:Element)=>string} getRole - 返回 'user' | 'assistant' | 其他
     * @returns {Array<{userEl:Element, assistantEl:Element|null}>}
     */
    _pairFlatTurns(orderedEls, getRole) {
        const pairs = [];
        let current = null;
        for (const el of orderedEls) {
            const role = getRole(el);
            if (role === 'user') {
                if (current) pairs.push(current);
                current = { userEl: el, assistantEl: null };
            } else if (role === 'assistant') {
                if (current && !current.assistantEl) current.assistantEl = el;
            }
        }
        if (current) pairs.push(current);
        return pairs;
    }

    /**
     * 收集元素内的对话图片（按 src 去重，过滤装饰小图，规则见 CEDomToMarkdown.extractImage）。
     * @param {Element} root
     * @param {'user'|'assistant'} role
     * @returns {Array}
     */
    _collectImagesFrom(root, role) {
        if (!root) return [];
        const images = [];
        const seen = new Set();
        root.querySelectorAll('img').forEach(img => {
            const info = this.domToMarkdown.extractImage(img, role);
            if (info && !seen.has(info.src)) {
                seen.add(info.src);
                images.push(info);
            }
        });
        return images;
    }

    /**
     * 从消息元素中按优先级取正文根节点。
     * @param {Element} el
     * @param {string[]} rootSelectors
     * @returns {Element|null}
     */
    _contentRootFrom(el, rootSelectors = []) {
        if (!el) return null;
        for (const selector of rootSelectors) {
            try {
                const root = el.querySelector(selector);
                if (root) return root;
            } catch { /* ignore invalid/stale platform selector */ }
        }
        return el;
    }

    /**
     * 通用用户消息抽取：文本限定在正文根，图片扫描整个消息行。
     * @param {Element} userEl
     * @param {string[]} rootSelectors
     * @returns {{text:string, images:Array, time:number|null}}
     */
    _extractUserFrom(userEl, rootSelectors = []) {
        if (!userEl) return { text: '', images: [], time: null };
        const root = this._contentRootFrom(userEl, rootSelectors);
        const text = (root?.textContent || '')
            .split('\n')
            .map(line => line.trim())
            .filter(Boolean)
            .join('\n');
        return {
            text,
            images: this._collectImagesFrom(userEl, 'user'),
            time: this._getAskTime(userEl),
        };
    }

    /**
     * 通用助手消息抽取：正文转 markdown，并补收正文根外的对话图片。
     * @param {Element|null} assistantEl
     * @param {string[]} rootSelectors
     * @returns {{markdown:string, text:string, images:Array}}
     */
    _extractAssistantFrom(assistantEl, rootSelectors = []) {
        if (!assistantEl) return { markdown: '', text: '', images: [] };
        const result = this._domMarkdownFrom(assistantEl, rootSelectors);
        const seen = new Set(result.images.map(image => image.src));
        this._collectImagesFrom(assistantEl, 'assistant').forEach(image => {
            if (seen.has(image.src)) return;
            seen.add(image.src);
            result.images.push(image);
        });
        return result;
    }

    /**
     * 尝试从平台 DOM 属性中取稳定消息 ID。
     * @param {Element|null} el
     * @returns {string|null}
     */
    _resolveElementId(el) {
        if (!el) return null;
        const candidates = [el, el.parentElement, el.closest?.('[data-virtual-list-item-key]')];
        const attrs = ['data-message-id', 'data-archer-id', 'data-virtual-list-item-key', 'data-msgid'];
        for (const candidate of candidates) {
            if (!candidate) continue;
            for (const attr of attrs) {
                const value = candidate.getAttribute?.(attr);
                if (value) return String(value);
            }
            if (candidate.id) return String(candidate.id);
        }
        return null;
    }

    // ---------- 通用能力（平台无关） ----------

    /**
     * 用户消息选择器。
     * 复用同平台时间轴 adapter 的 getUserMessageSelector（单一事实来源，
     * 运行态优先、否则取全局 registry 里的同平台 adapter）。
     * @returns {string}
     */
    getUserMessageSelector() {
        return this._resolveTimelineAdapter()?.getUserMessageSelector?.() || '';
    }

    /**
     * AI 回复消息选择器。
     * 复用同平台时间轴 adapter 的 getAssistantMessageSelector（单一事实来源，
     * 运行态优先、否则取全局 registry 里的同平台 adapter）。
     * @returns {string}
     */
    getAssistantMessageSelector() {
        return this._resolveTimelineAdapter()?.getAssistantMessageSelector?.() || '';
    }

    /**
     * 构建「用户消息元素 → 提问时间戳」映射。
     *
     * 复用扩展已记录的提问时间（ChatTimeRecorder 写入的 chatTimes 存储）：
     * 键为时间轴 adapter 的 generateTurnId(userEl, index)。这里对时间轴 adapter 声明的
     * 用户消息元素逐个计算相同的 nodeId 并回填时间戳，用 WeakMap 以元素为键，
     * 便于子类在 extractTurn 中按用户元素直接取用（无需关心 ID 规则差异）。
     *
     * 存储无记录 / 时间轴不可用 / 平台未开启该功能时返回 null。
     * @returns {Promise<WeakMap<Element, number>|null>}
     */
    async _buildAskTimeMap() {
        try {
            const adapter = window.timelineManager?.adapter;
            if (!adapter?.generateTurnId || typeof ChatTimeStorageManager === 'undefined') return null;

            const conversationKey = location.href
                .replace(/^https?:\/\//, '')
                .split('?')[0]
                .split('#')[0];
            if (!conversationKey) return null;

            const data = await ChatTimeStorageManager.getByConversation(conversationKey);
            const nodes = data?.nodes || {};
            if (!Object.keys(nodes).length) return null;

            const selector = adapter.getUserMessageSelector?.();
            if (!selector) return null;

            const els = Array.from(document.querySelectorAll(selector));
            const map = new WeakMap();
            els.forEach((el, index) => {
                const nodeId = adapter.generateTurnId(el, index);
                const ts = nodes[String(nodeId)];
                if (ts) map.set(el, ts);
            });
            return map;
        } catch {
            return null;
        }
    }

    /**
     * 按用户消息元素取提问时间戳（毫秒），无记录时返回 null。
     * @param {Element} userEl
     * @returns {number|null}
     */
    _getAskTime(userEl) {
        if (!userEl || !this._askTimeMap) return null;
        return this._askTimeMap.get(userEl) || null;
    }

    /** 平台展示名 */
    async getPlatformName() {
        const platform = await getPlatformById(this.platformId);
        return platform?.name || this.platformId;
    }

    /** 默认 PNG 主题色：跟随时间轴激活色设置 */
    async getDefaultThemeId() {
        try {
            const result = await chrome.storage.local.get('timelineActiveColorByPlatform');
            const settings = result?.timelineActiveColorByPlatform || {};
            const colorId = resolveTimelineActiveColorId(this.platformId, settings);
            // 仅当该 id 也是导出可选主题时才采用，否则回退默认
            if (CE_THEMES.some(t => t.id === colorId)) return colorId;
        } catch { /* ignore */ }
        return CE_DEFAULT_THEME;
    }

    /**
     * 自动加载并采集完整对话。
     *
     * 流程：① 按 loadStrategy 把对话准备到「可读取」状态 → ② prepareCollection 一次性准备
     * →（③）按 getTurnContainers 顺序逐轮 extractTurn 读取、去重。
     *
     * 加载策略（见 CE_LOAD_STRATEGY）：
     * - SCROLL（Gemini/ChatGPT 等）：滚动把未渲染内容加载/渲染出来（平台可覆盖 _loadByScrolling）。
     * - STATIC：完整对话数据已在 DOM/内存，无需滚动，直接读取。
     *
     * @param {Object} options
     * @param {(count:number)=>void} [options.onProgress]
     * @param {()=>boolean} [options.shouldCancel]
     * @returns {Promise<Array>} 按对话顺序排列的 turn 列表
     */
    async collectAllTurns({ onProgress, shouldCancel } = {}) {
        const scroller = this.getScrollContainer();

        const getScrollTop = () => (scroller === window ? window.scrollY : scroller.scrollTop);
        const scrollTo = (top) => {
            if (scroller === window) window.scrollTo(0, top);
            else scroller.scrollTop = top;
        };

        const initialScrollTop = getScrollTop();

        // ① 按策略把完整对话准备到可读取状态
        if (this.loadStrategy === CE_LOAD_STRATEGY.SCROLL) {
            await this._loadByScrolling({ onProgress, shouldCancel, scrollTo });
        } else {
            // STATIC：数据已在内存，仅上报当前数量供进度显示
            onProgress?.(this.getTurnContainers().length);
        }

        if (shouldCancel?.()) {
            try { scrollTo(initialScrollTop); } catch { /* ignore */ }
            return [];
        }

        // ② 正式读取前的一次性准备（平台按需实现 prepareCollection）
        try {
            await this.prepareCollection();
        } catch (error) {
        }

        if (shouldCancel?.()) {
            try { scrollTo(initialScrollTop); } catch { /* ignore */ }
            return [];
        }

        // 预取提问时间映射（元素 → 时间戳），供 extractTurn 里按用户元素取用
        this._askTimeMap = await this._buildAskTimeMap();

        // ③ 按顺序一次性读取所有对话轮。
        const turns = [];
        const seen = new Set();
        for (const container of this.getTurnContainers()) {
            let turn;
            try {
                turn = this.extractTurn(container);
            } catch {
                turn = null;
            }
            if (!turn) continue;
            const key = turn.id || `sig:${this._signature(turn)}`;
            if (seen.has(key)) continue;
            seen.add(key);
            turns.push(turn);
        }

        // 恢复用户原始滚动位置（尽量不打扰）
        try { scrollTo(initialScrollTop); } catch { /* ignore */ }

        turns.forEach((turn, index) => { turn.order = index + 1; });
        return turns;
    }

    /**
     * SCROLL 策略：反复跳到顶部把只在顶部懒加载的历史全部加载出来。
     *
     * 每次 scrollTo(0) 触发上方历史加载 —— 在加载就等其完成后再跳；跳顶后既不在加载、
     * 对话数也不再增长，说明已到达真正的顶部、历史全部加载完成。
     *
     * @param {Object} ctx
     * @param {(count:number)=>void} [ctx.onProgress]
     * @param {()=>boolean} [ctx.shouldCancel]
     * @param {(top:number)=>void} ctx.scrollTo
     * @returns {Promise<void>}
     */
    async _loadByScrolling({ onProgress, shouldCancel, scrollTo }) {
        const maxRounds = 800;

        let prevCount = this.getTurnContainers().length;
        onProgress?.(prevCount);
        for (let round = 0; round < maxRounds; round++) {
            if (shouldCancel?.()) break;

            scrollTo(0);
            await this._wait(1000);             // 给顶部“加载中”一点启动时间
            await this._waitWhileLoading(2000); // 若正在加载则等其完成

            const count = this.getTurnContainers().length;
            onProgress?.(count);

            if (this.isLoadingMore()) continue; // 仍在加载 → 再跳顶继续
            if (count === prevCount) break;     // 不在加载且无新增 → 已到顶、全部加载完成
            prevCount = count;                  // 有新增 → 再跳顶看是否还有更早历史
        }
    }

    /**
     * 等待“加载中”动画结束（最多 maxMs）。
     *
     * 借鉴 AIStateMonitor 的“免轮询”思路：搭全局共享的 DOMObserverManager
     * body 观察器——加载指示器的出现/消失都是节点增删，能被捕获——每次 DOM 变化时
     * 重新判断 isLoadingMore()，加载结束（连续 IDLE 无加载）即结算，最长等待 maxMs。
     * DOMObserverManager 不可用时直接结算（采集循环自身还有多轮兜底）。
     *
     * @param {number} maxMs
     * @returns {Promise<void>}
     */
    _waitWhileLoading(maxMs = 3000) {
        return new Promise((resolve) => {
            const manager = window.DOMObserverManager;
            if (!manager || !manager.getInstance) {
                resolve();
                return;
            }

            const IDLE_MS = 150; // 连续无加载达到该时长视为加载结束
            let done = false;
            let unsubscribe = null;
            let idleTimer = null;
            let maxTimer = null;

            const cleanup = () => {
                if (idleTimer) { clearTimeout(idleTimer); idleTimer = null; }
                if (maxTimer) { clearTimeout(maxTimer); maxTimer = null; }
                if (unsubscribe) { unsubscribe(); unsubscribe = null; }
            };
            const finish = () => {
                if (done) return;
                done = true;
                cleanup();
                resolve();
            };

            const scheduleIdleConfirm = () => {
                if (idleTimer) clearTimeout(idleTimer);
                idleTimer = setTimeout(() => {
                    idleTimer = null;
                    if (!this.isLoadingMore()) finish();
                }, IDLE_MS);
            };

            const evaluate = () => {
                if (this.isLoadingMore()) {
                    // 仍在加载：取消结束确认，继续等待下一次 DOM 变化
                    if (idleTimer) { clearTimeout(idleTimer); idleTimer = null; }
                } else {
                    scheduleIdleConfirm();
                }
            };

            maxTimer = setTimeout(finish, maxMs);

            try {
                // 不设过滤：加载条出现=增节点、消失=删节点，都要感知
                unsubscribe = manager.getInstance().subscribeBody('ce-export-loading-wait', {
                    callback: evaluate,
                });
            } catch {
                finish();
                return;
            }

            // 立即评估一次当前状态
            evaluate();
        });
    }

    _signature(turn) {
        const u = (turn.user?.text || '').replace(/\s+/g, ' ').slice(0, 80);
        const aLen = (turn.assistant?.text || '').length;
        return `${u}#${aLen}`;
    }

    _wait(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }
}

;

// Source: js/conversationExport/adapters/gemini.js
/**
 * Conversation Export - Gemini 导出适配器
 *
 * DOM 采集范式（SCROLL 策略）：对话轮定位、用户/助手内容抽取、加载指示器。
 * 页面可导出判断、按钮锚点、标题、滚动容器等「平台事实」由基类优先委托
 * 时间轴 adapter，本类只提供时间轴不可用时的兜底。
 */

class CEGeminiExportAdapter extends CEExportAdapter {
    constructor() {
        super('gemini');
    }

    /** 兜底：与时间轴 getStarChatButtonTarget 相同的顶栏锚点 */
    _fallbackButtonInsertTarget() {
        const topBarActions = document.querySelector('.top-bar-actions');
        if (!topBarActions) return null;
        const rightSection = topBarActions.querySelector('.right-section');
        if (!rightSection) return null;
        return rightSection.firstElementChild;
    }

    /** 兜底：从对话容器向上查找可滚动祖先（与时间轴 resolveScrollContainer 一致） */
    _fallbackScrollContainer() {
        const selector = this.getUserMessageSelector();
        const firstContainer = document.querySelector('.conversation-container') ||
            (selector ? document.querySelector(selector) : null);
        let node = firstContainer;
        while (node && node !== document.body) {
            const style = window.getComputedStyle(node);
            if (style.overflowY === 'auto' || style.overflowY === 'scroll') {
                return node;
            }
            node = node.parentElement;
        }
        return null;
    }

    getTurnContainers() {
        const containers = Array.from(document.querySelectorAll('.conversation-container'));
        if (containers.length) return containers;

        // 退化：直接用用户消息元素的最近容器
        const selector = this.getUserMessageSelector();
        if (!selector) return [];
        const userQueries = Array.from(document.querySelectorAll(selector));
        const seen = new Set();
        const result = [];
        userQueries.forEach(uq => {
            const container = uq.closest('.conversation-container') || uq.parentElement || uq;
            if (container && !seen.has(container)) {
                seen.add(container);
                result.push(container);
            }
        });
        return result;
    }

    extractTurn(container) {
        if (!container) return null;

        const selector = this.getUserMessageSelector();
        const userEl = selector ? container.querySelector(selector) : null;
        const assistantSelector = this.getAssistantMessageSelector();
        const modelEl = assistantSelector ? container.querySelector(assistantSelector) : null;

        // 既无用户也无助手内容，跳过
        if (!userEl && !modelEl) return null;

        const id = this._resolveTurnId(container, userEl);
        const user = this._extractUser(userEl);
        const assistant = this._extractAssistant(modelEl);

        return { id, user, assistant };
    }

    /**
     * 加载指示器：Gemini 加载上方未渲染节点时，页面顶部出现可见的
     * indeterminate mat-progress-bar（class 含 mdc-linear-progress--indeterminate）。
     * @returns {boolean}
     */
    isLoadingMore() {
        try {
            const bars = document.querySelectorAll(
                'mat-progress-bar[mode="indeterminate"], .mdc-linear-progress--indeterminate'
            );
            for (const bar of bars) {
                const rect = bar.getBoundingClientRect();
                if (rect.width > 0 && rect.height > 0) return true;
            }
        } catch { /* ignore */ }
        return false;
    }

    _resolveTurnId(container, userEl) {
        if (container.id) return `gemini-${container.id}`;
        const parentId = userEl?.parentElement?.id;
        if (parentId) return `gemini-${parentId}`;
        if (userEl?.id) return `gemini-${userEl.id}`;
        return null;
    }

    _extractUser(userEl) {
        if (!userEl) return { text: '', images: [], time: null };

        // 文本：优先 .query-text-line（保留换行），回退整体文本
        const lines = userEl.querySelectorAll('.query-text-line');
        let text = '';
        if (lines.length) {
            text = Array.from(lines)
                .map(line => (line.textContent || '').trim())
                .filter(Boolean)
                .join('\n');
        } else {
            const queryText = userEl.querySelector('.query-text') || userEl;
            text = (queryText.textContent || '').replace(/\s+/g, ' ').trim();
        }

        const images = this._collectImagesFrom(userEl, 'user');
        return { text, images, time: this._getAskTime(userEl) };
    }

    _extractAssistant(modelEl) {
        if (!modelEl) {
            return { markdown: '', text: '', images: [] };
        }

        // 文本/markdown 限定在正文根（避免把界面文字当正文）。
        const result = this._domMarkdownFrom(modelEl, ['.markdown', 'message-content', '.model-response-text']);

        // 图片检测独立于正文根：直接扫描整个 model-response 补收图片，按 src 去重合并。
        // 原因：Gemini 生成图片常被包在 <button>（点击放大）里，DOM→markdown 会整体跳过
        // button 子树而漏收；且不同/后续版本可能把图片放在 .markdown 之外。扫描整个回复容器
        // 更抗平台结构变动，装饰性小图标由 _extractImageInfo 的尺寸/gif 过滤剔除。
        const seen = new Set(result.images.map(img => img.src));
        this._collectImagesFrom(modelEl, 'assistant').forEach(img => {
            if (!seen.has(img.src)) {
                seen.add(img.src);
                result.images.push(img);
            }
        });

        return result;
    }
}

;

// Source: js/conversationExport/adapters/chatgpt.js
/**
 * Conversation Export - ChatGPT 导出适配器
 *
 * 与 Gemini 的关键差异：
 * 1. ChatGPT 是「视口窗口式」虚拟渲染：任意时刻 DOM 里只有视口附近一屏的轮次是
 *    已渲染的 <article>，其余全部是 [data-turn-id-container]
 *    [data-is-intersecting="false"] 空壳（运行日志实证：121 个容器滚到顶后仅 8 对
 *    已渲染，反复滚顶无增益）。因此基类「先加载完、再统一读」的编排不成立，
 *    本类覆盖 collectAllTurns：从顶到底逐屏滚动，分别采集用户和助手消息，
 *    结束后按容器 DOM 顺序配对输出。提问和回复无需在同一滚动窗口内同时存在。
 * 2. ChatGPT 的用户与助手是各自独立的 <article data-turn="user|assistant" data-turn-id>，
 *    不像 Gemini 用一个 .conversation-container 同时装问答。因此需要按文档顺序把
 *    「用户轮 + 紧随其后的助手轮」配成一对。
 *
 * 内容完全来自 DOM（滚动渲染后采集）；
 * 用户/助手消息选择器复用基类共享方法（优先取时间轴 adapter）。
 */

class CEChatGPTExportAdapter extends CEExportAdapter {
    static MODERN_MESSAGE_SELECTOR = '[data-thread-find-target="conversation"] [data-chatgpt-search-unit-key][data-chatgpt-search-message-ids]';
    static MODERN_TURN_SELECTOR = '[data-thread-find-target="conversation"] [data-turn-key]';

    constructor() {
        super('chatgpt');
    }

    /**
     * 未渲染的虚拟化空壳轮次列表。
     * ChatGPT 给视口外轮次保留 [data-turn-id-container] 容器，
     * 并以 data-is-intersecting="false" 标记（内部 React 子树已卸载）。
     * @returns {Element[]}
     */
    _getUnrenderedShells() {
        return Array.from(document.querySelectorAll(
            `[data-turn-id-container][data-is-intersecting="false"], ${CEChatGPTExportAdapter.MODERN_TURN_SELECTOR}`
        ));
    }

    _getMessageId(element) {
        return element.getAttribute('data-turn-id')
            || element.getAttribute('data-chatgpt-search-message-ids')?.trim().split(/\s+/)[0]
            || null;
    }

    _getMessageRole(element) {
        return element.getAttribute('data-turn')
            || element.getAttribute('data-chatgpt-search-unit-key')?.split(':').pop();
    }

    _getRenderedMessages() {
        return Array.from(document.querySelectorAll(
            `[data-turn-id][data-turn], ${CEChatGPTExportAdapter.MODERN_MESSAGE_SELECTOR}`
        )).filter(el => ['user', 'assistant'].includes(this._getMessageRole(el)));
    }

    /**
     * 覆盖基类采集编排：以「空壳」为锚点逐个滚动渲染、边滚边采集。
     *
     * 为什么不能用基类「先加载完、再统一读」的两段式编排：
     * ChatGPT 的虚拟化是视口窗口式的——滚到哪里就只渲染哪里，滚过去的轮次
     * 会被卸载回空壳。不存在「全部渲染完成」的时刻，必须在滚动途中即时提取。
     *
     * 为什么按空壳元素锚定、而不是按像素逐屏步进（运行日志实证的两个坑）：
     * 1. 空壳渲染成真实内容后高度膨胀（一次运行页面总高从 35250 涨到 43986），
     *    下方内容整体下移，固定像素步进会被重排反超、整段跳过；
     *    元素锚定用空壳的实时位置滚动，天然免疫重排。
     * 2. [data-turn-id-container] 容器本身也是窗口化的（同一运行中 121 → 85），
     *    结束时的单次快照排不出完整顺序——改为每轮把当前窗口的容器 id 序列
     *    增量合并进全局有序表（相邻窗口高度重叠，按锚点插入）。
     *
     * 流程：跳到顶部 → 每轮找文档序第一个「未处理过的空壳」滚到视口 → 等待渲染
     * 稳定（固定启动等待 + DOM 安静确认）→ 提取当前已渲染轮次（按用户轮 turn id
     * 去重）并合并容器顺序 → 无未处理空壳或连续多轮无进展时结束 → 按全局有序表
     * 排序输出，恢复用户原始滚动位置。
     *
     * @param {Object} options
     * @param {(count:number)=>void} [options.onProgress]
     * @param {()=>boolean} [options.shouldCancel]
     * @returns {Promise<Array>}
     */
    async collectAllTurns({ onProgress, shouldCancel } = {}) {
        const scroller = this.getScrollContainer();
        const isWin = scroller === window;
        const reverse = !isWin && scroller.nodeType === 1
            && getComputedStyle(scroller).flexDirection === 'column-reverse';
        const scrollRange = () => Math.max(0, (isWin
            ? document.documentElement.scrollHeight - window.innerHeight
            : scroller.scrollHeight - scroller.clientHeight) || 0);
        const getScrollTop = () => (isWin ? window.scrollY : scroller.scrollTop);
        const scrollTo = (top) => {
            if (isWin) window.scrollTo(0, top);
            else scroller.scrollTop = top;
        };

        const initialScrollTop = getScrollTop();

        // 提问时间表（按 turn id 查，替代基类按元素的 WeakMap——
        // 逐屏采集时元素随滚动创建/卸载，元素键在跨屏后失效）
        const askTimes = await this._loadAskTimes();

        const capturedMessages = new Map(); // 消息 turn id → { id, role, content }
        const capturedUserIds = new Set(); // 进度统计，避免每轮扫描全部快照
        const capturedOrder = [];      // 消息首次渲染顺序（旧版 DOM / 顺序表兜底）
        const processedIds = new Set(); // 渲染过（内容采集过）的容器 id
        const masterOrder = [];         // 全局容器 id 顺序（跨窗口增量合并）

        // 把当前窗口的容器 id 序列合并进全局有序表。
        // 相邻轮次的窗口高度重叠：已知 id 作为锚点推进，未知 id 插到锚点之后。
        const mergeContainerOrder = () => {
            const seen = new Set();
            const current = [];
            // 新版 data-turn-key 包含一问一答，排序必须使用内部消息 ID，
            // 不能把整轮的用户 ID 当作两条消息的顺序。
            document.querySelectorAll(`[data-turn-id-container], ${CEChatGPTExportAdapter.MODERN_MESSAGE_SELECTOR}`).forEach(el => {
                if (el.hasAttribute('data-chatgpt-search-unit-key')
                    && !['user', 'assistant'].includes(this._getMessageRole(el))) return;
                const id = el.getAttribute('data-turn-id-container') || this._getMessageId(el);
                if (id && !seen.has(id)) { seen.add(id); current.push(id); }
            });
            // 从顶部向下扫描时，无共同节点的新窗口应接到末尾。
            if (current.length && !current.some(id => masterOrder.includes(id))) {
                masterOrder.push(...current);
                return;
            }
            let ptr = -1; // masterOrder 中最后命中的锚点位置
            for (const id of current) {
                const idx = masterOrder.indexOf(id);
                if (idx >= 0) {
                    ptr = Math.max(ptr, idx);
                } else {
                    masterOrder.splice(ptr + 1, 0, id);
                    ptr += 1;
                }
            }
        };

        // 标记当前已渲染的容器（内部有 [data-turn] 真实内容，或明确 intersecting）
        const markProcessed = () => {
            document.querySelectorAll('[data-turn-id-container]').forEach(el => {
                const id = el.getAttribute('data-turn-id-container');
                if (!id || processedIds.has(id)) return;
                if (el.getAttribute('data-is-intersecting') === 'true' || el.querySelector('[data-turn]')) {
                    processedIds.add(id);
                }
            });
        };

        const collectRendered = () => {
            this._getRenderedMessages().forEach(element => {
                const id = this._getMessageId(element);
                const role = this._getMessageRole(element);
                if (!id || (role !== 'user' && role !== 'assistant')) return;

                let content;
                try {
                    if (role === 'user') {
                        content = this._extractUser(element);
                        if (askTimes) content.time = askTimes[`chatgpt-${id}`] || null;
                    } else {
                        content = this._extractAssistant(element);
                    }
                } catch {
                    return;
                }

                if (!capturedMessages.has(id)) capturedOrder.push(id);
                if (role === 'user') capturedUserIds.add(id);
                // 同一消息再次渲染时使用最新快照，兼容延迟补齐的正文、图片和公式。
                capturedMessages.set(id, { id, role, content });
            });
            markProcessed();
            mergeContainerOrder();
            onProgress?.(capturedUserIds.size);
        };

        // 文档序第一个「未处理过的空壳」（渲染过的容器被虚拟化卸载回空壳时不再重复处理）
        const nextPendingShell = () =>
            this._getUnrenderedShells().find(el => {
                const id = el.getAttribute('data-turn-id-container') || el.getAttribute('data-turn-key');
                return id && !processedIds.has(id);
            }) || null;

        // 从顶部开始（建立全局顺序表的头部）
        // 顶部历史分页加载后需再次到顶，连续两次确认稳定才开始采集。
        let stableTop = 0;
        for (let attempt = 0; attempt < 30 && stableTop < 2; attempt++) {
            if (shouldCancel?.()) {
                try { scrollTo(initialScrollTop); } catch {}
                return [];
            }
            const beforeRange = scrollRange();
            scrollTo(reverse ? -beforeRange : 0);
            await this._wait(1000);
            await this._waitWhileLoading(2000);
            const range = scrollRange();
            const atTop = Math.abs(getScrollTop() - (reverse ? -range : 0)) <= 2;
            stableTop = atTop && Math.abs(range - beforeRange) <= 2 ? stableTop + 1 : 0;
        }
        collectRendered();

        // 逐个把未处理空壳滚进视口渲染并采集
        const maxRounds = 800;
        let stagnantRounds = 0;
        for (let round = 0; round < maxRounds; round++) {
            if (shouldCancel?.()) {
                try { scrollTo(initialScrollTop); } catch { /* ignore */ }
                return [];
            }

            const shell = nextPendingShell();
            if (!shell) {
                // 当前 DOM 已采完不代表历史已采完；向下扫屏触发下一窗口渲染。
                const bottom = reverse ? 0 : scrollRange();
                const current = getScrollTop();
                if (bottom - current <= 1) break;
                const viewport = isWin ? window.innerHeight : (scroller.clientHeight || window.innerHeight);
                scrollTo(Math.min(bottom, current + Math.max(1, viewport * 0.8)));
                await this._wait(400);
                await this._waitWhileLoading(2000);
                collectRendered();
                if (Math.abs(getScrollTop() - current) < 1) {
                    if (++stagnantRounds >= 5) break;
                } else stagnantRounds = 0;
                continue;
            }

            const beforeCaptured = capturedMessages.size;
            const beforeProcessed = processedIds.size;

            // 元素锚定滚动：按空壳当前实时位置，把它滚到视口上沿附近
            const rect = shell.getBoundingClientRect();
            const viewTop = isWin ? 0 : scroller.getBoundingClientRect().top;
            scrollTo(getScrollTop() + (rect.top - viewTop) - 80);
            await this._wait(400);              // 渲染启动
            await this._waitWhileLoading(2000); // DOM 稳定确认
            collectRendered();
            // 新版每轮都滚动到一次，触发虚拟内容渲染后才标记完成。
            const modernTurnId = shell.getAttribute('data-turn-key');
            if (modernTurnId && capturedMessages.has(modernTurnId)) {
                processedIds.add(modernTurnId);
            }

            // 连续多轮既无新采集也无新渲染 → 虚拟化不再响应，避免死循环
            if (capturedMessages.size === beforeCaptured && processedIds.size === beforeProcessed) {
                stagnantRounds++;
                if (stagnantRounds >= 5) break;
            } else {
                stagnantRounds = 0;
            }
        }
        collectRendered(); // 结束前最后再采一次

        // 用户和助手独立采集，最后才按完整顺序配对，避免虚拟窗口边界漏回复。
        const turns = this._pairCapturedMessages(capturedMessages, masterOrder, capturedOrder);

        // 恢复用户原始滚动位置（尽量不打扰）
        try { scrollTo(initialScrollTop); } catch { /* ignore */ }

        turns.forEach((turn, index) => { turn.order = index + 1; });
        return turns;
    }

    /**
     * 按全局消息顺序把独立快照组成对话轮。
     * 助手消息即使在用户消息卸载后才渲染，也能通过稳定 turn id 和顺序正确归属。
     *
     * @param {Map<string,{id:string,role:string,content:Object}>} capturedMessages
     * @param {string[]} masterOrder
     * @param {string[]} capturedOrder
     * @returns {Array}
     */
    _pairCapturedMessages(capturedMessages, masterOrder, capturedOrder) {
        const orderedIds = [];
        const seen = new Set();
        [...masterOrder, ...capturedOrder].forEach(id => {
            if (!id || seen.has(id) || !capturedMessages.has(id)) return;
            seen.add(id);
            orderedIds.push(id);
        });

        const turns = [];
        let pendingUser = null;
        const emptyAssistant = () => ({ markdown: '', text: '', images: [] });
        const flushPending = () => {
            if (!pendingUser) return;
            const { id, user, assistant } = pendingUser;
            if (user.text || user.images.length || assistant.text || assistant.images.length) {
                turns.push({ id: `chatgpt-${id}`, user, assistant });
            }
            pendingUser = null;
        };

        orderedIds.forEach(id => {
            const message = capturedMessages.get(id);
            if (message.role === 'user') {
                flushPending();
                pendingUser = {
                    id,
                    user: message.content,
                    assistant: emptyAssistant(),
                    assistantAssigned: false
                };
                return;
            }
            if (message.role === 'assistant' && pendingUser && !pendingUser.assistantAssigned) {
                pendingUser.assistant = message.content;
                pendingUser.assistantAssigned = true;
            }
        });
        flushPending();
        return turns;
    }

    /**
     * 读取扩展记录的提问时间表（ChatTimeRecorder 写入的 chatTimes 存储）。
     * 键为时间轴 generateTurnId 的产物（chatgpt-<turnId>），值为毫秒时间戳。
     * 无记录/存储不可用时返回 null。
     * @returns {Promise<Object|null>}
     */
    async _loadAskTimes() {
        try {
            if (typeof ChatTimeStorageManager === 'undefined') return null;
            const conversationKey = location.href
                .replace(/^https?:\/\//, '')
                .split('?')[0]
                .split('#')[0];
            if (!conversationKey) return null;
            const data = await ChatTimeStorageManager.getByConversation(conversationKey);
            const nodes = data?.nodes || {};
            return Object.keys(nodes).length ? nodes : null;
        } catch {
            return null;
        }
    }

    /** 兜底：与时间轴 getStarChatButtonTarget 相同的分享按钮锚点 */
    _fallbackButtonInsertTarget() {
        return window.AITChatHeaderActions?.getInsertTarget?.()
            || document.querySelector('[data-testid="share-chat-button"]');
    }

    /**
     * 对话轮单元 = { userEl, assistantEl } 配对。
     * ChatGPT 用户与助手是各自独立的 <article data-turn>，按文档顺序用基类
     * _pairFlatTurns 配对（以用户轮为锚，配其后的第一个助手轮）。
     * @returns {Array<{userEl:Element, assistantEl:Element|null}>}
     */
    getTurnContainers() {
        return this._pairFlatTurns(this._getRenderedMessages(), el => this._getMessageRole(el));
    }

    /**
     * @param {{userEl:Element, assistantEl:Element|null}} pair
     */
    extractTurn(pair) {
        if (!pair || !pair.userEl) return null;

        const userTurnId = this._getMessageId(pair.userEl);
        const user = this._extractUser(pair.userEl);
        const assistant = this._extractAssistant(pair.assistantEl);

        // 用户与助手都为空，跳过
        if (!user.text && !user.images.length && !assistant.text && !assistant.images.length) {
            return null;
        }

        const id = userTurnId ? `chatgpt-${userTurnId}` : null;
        return { id, user, assistant };
    }

    // ==================== 内部 ====================

    _extractUser(userEl) {
        const text = this._domUserText(userEl);
        const images = this._collectImagesFrom(userEl, 'user');
        return { text, images, time: this._getAskTime(userEl) };
    }

    _extractAssistant(assistantEl) {
        if (!assistantEl) return { markdown: '', text: '', images: [] };
        return this._domMarkdownFrom(assistantEl, ['[data-markdown-text-style="assistant-message"]', '.markdown', '[data-message-author-role="assistant"]']);
    }

    _domUserText(userEl) {
        if (!userEl) return '';
        const textEl = userEl.querySelector('[data-user-message-bubble]')
            || userEl.querySelector('.whitespace-pre-wrap');
        const raw = textEl ? textEl.textContent : userEl.textContent;
        return (raw || '').replace(/\s+/g, ' ').trim();
    }

}

;

// Source: js/conversationExport/adapters/deepseek.js
/**
 * Conversation Export - DeepSeek 导出适配器
 *
 * DeepSeek 使用虚拟列表；滚到顶部后历史消息会物化到 DOM，
 * 因此复用基类 SCROLL 策略即可收集完整会话。
 */

class CEDeepSeekExportAdapter extends CEExportAdapter {
    constructor() {
        super('deepseek');
    }

    getUserMessageSelector() {
        return '.ds-message:not(:has(.ds-assistant-message-main-content))';
    }

    getAssistantMessageSelector() {
        return '.ds-message:has(.ds-assistant-message-main-content)';
    }

    _fallbackButtonInsertTarget() {
        const path = document.querySelector('path[d^="M15.7484 11.1004"]');
        return path?.closest('.ds-icon-button') || null;
    }

    _fallbackScrollContainer() {
        return document.querySelector('.ds-virtual-list--printable');
    }

    getTurnContainers() {
        const messages = Array.from(document.querySelectorAll('.ds-message'));
        return this._pairFlatTurns(messages, element => (
            element.querySelector('.ds-assistant-message-main-content') ? 'assistant' : 'user'
        ));
    }

    extractTurn(pair) {
        if (!pair?.userEl) return null;
        const user = this._extractUserFrom(pair.userEl, [':scope > div']);
        const assistant = this._extractAssistantFrom(pair.assistantEl, [
            '.ds-assistant-message-main-content',
            '.ds-markdown',
        ]);
        if (!user.text && !user.images.length && !assistant.text && !assistant.images.length) return null;

        const elementId = this._resolveElementId(pair.userEl);
        return {
            id: elementId ? `deepseek-${elementId}` : null,
            user,
            assistant,
        };
    }

    isLoadingMore() {
        const loading = document.querySelector('.ds-loading');
        if (!loading) return false;
        const rect = loading.getBoundingClientRect();
        return rect.width > 0 && rect.height > 0;
    }
}

;

// Source: js/conversationExport/adapters/kimi.js
/**
 * Conversation Export - Kimi 导出适配器
 */

class CEKimiExportAdapter extends CEExportAdapter {
    constructor() {
        super('kimi');
    }

    getAssistantMessageSelector() {
        return '.chat-content-item-assistant';
    }

    _fallbackButtonInsertTarget() {
        return document.querySelector('.chat-header-actions .icon');
    }

    _fallbackScrollContainer() {
        return document.querySelector('.chat-detail-main');
    }

    getTurnContainers() {
        const messages = Array.from(document.querySelectorAll(
            '.chat-content-item-user, .chat-content-item-assistant'
        ));
        return this._pairFlatTurns(messages, element => {
            if (element.classList.contains('chat-content-item-user')) return 'user';
            if (element.classList.contains('chat-content-item-assistant')) return 'assistant';
            return '';
        });
    }

    extractTurn(pair) {
        if (!pair?.userEl) return null;
        const user = this._extractUserFrom(pair.userEl, ['.user-content']);
        const assistant = this._extractAssistantFrom(pair.assistantEl, [
            '.markdown-container',
            '.markdown',
        ]);
        if (!user.text && !user.images.length && !assistant.text && !assistant.images.length) return null;

        const elementId = this._resolveElementId(pair.userEl);
        return {
            id: elementId ? `kimi-${elementId}` : null,
            user,
            assistant,
        };
    }
}

